const PENDING = "pending";
const RUNNING = "running";
const SUSPENDED = "suspended";
const ERROR = "error";
const COMPLETE = "complete";

const TRANSITIONS = {
  start: RUNNING,
  pause: SUSPENDED,
  resume: RUNNING,
  fail: ERROR,
  finish: COMPLETE
};

const REQUIRED_SOURCE = {
  start: PENDING,
  pause: RUNNING,
  resume: SUSPENDED
};

const TERMINAL_STATES = [ERROR, COMPLETE];

function normalizeAction(action) {
  if (typeof action !== "string") {
    throw new TypeError("each action must be a string");
  }
  return action.trim().toLowerCase();
}

function nextState(currentState, action) {
  const name = normalizeAction(action);
  const target = TRANSITIONS[name];
  if (target === undefined) {
    throw new RangeError("unknown action: " + name);
  }
  if (TERMINAL_STATES.includes(currentState)) {
    throw new Error("job already finished in state: " + currentState);
  }
  const required = REQUIRED_SOURCE[name];
  if (required !== undefined && currentState !== required) {
    throw new Error(
      "cannot apply " + name
      + " to a job that is not "
      + required
    );
  }
  return target;
}

function transition(actions) {
  if (!Array.isArray(actions)) {
    throw new TypeError("actions must be an array");
  }
  let state = PENDING;
  const history = [];
  for (const action of actions) {
    state = nextState(state, action);
    history.push(state);
  }
  return history;
}

function parseScript(script) {
  return script.split(/\s+/).filter(part => part.length > 0);
}

function describeRun(actions) {
  const states = transition(actions);
  const steps = states.map((state, index) => normalizeAction(actions[index]) + " -> " + state);
  const finalState = states.length === 0 ? PENDING : states[states.length - 1];
  const trail = steps.join(", ");
  return trail + " | final: " + finalState;
}

function main() {
  const scripts = [
    "start pause resume finish",
    "start fail",
    "start pause",
    "start resume"
  ];
  for (const script of scripts) {
    try {
      console.log(describeRun(parseScript(script)));
    } catch (err) {
      console.log("rejected: " + err.message);
    }
  }
}

main();

module.exports = { transition, nextState, parseScript, describeRun };

