const COMPASS = [
  "north",
  "east",
  "south",
  "west"
];

const RIGHT_COMMANDS = [
  "right",
  "turn right",
  "r",
  "clockwise"
];

const LEFT_COMMANDS = [
  "left",
  "turn left",
  "l",
  "counterclockwise"
];

function normalizeCommand(command) {
  if (typeof command !== "string") {
    throw new TypeError("each direction must be a string");
  }
  return command.trim().toLowerCase().replace(/\s+/g, " ");
}

function classifyCommand(command) {
  const cleaned = normalizeCommand(command);
  if (RIGHT_COMMANDS.includes(cleaned)) {
    return "right";
  }
  if (LEFT_COMMANDS.includes(cleaned)) {
    return "left";
  }
  throw new Error(`unknown command: ${cleaned}`);
}

function turn(facing, rotation) {
  const index = COMPASS.indexOf(facing);
  const step = rotation === "right" ? 1 : 3;
  return COMPASS[(index + step) % COMPASS.length];
}

function navigate(directions) {
  if (!Array.isArray(directions)) {
    throw new TypeError("directions must be an array");
  }
  let facing = "north";
  for (const command of directions) {
    facing = turn(facing, classifyCommand(command));
  }
  return facing;
}

function parseRoute(text) {
  if (typeof text !== "string") {
    throw new TypeError("a route must be given as text");
  }
  return text.split(",").map((piece) => piece.trim()).filter((piece) => piece.length > 0);
}

function formatReport(text) {
  const route = parseRoute(text);
  let label = "(no commands)";
  if (route.length > 0) {
    label = route.join(", ");
  }
  return `${label} -> ${navigate(route)}`;
}

function main() {
  const argument = process.argv.slice(2).join(",");
  const routes = [
    "right, right, left",
    "turn left, turn left",
    "L, counterclockwise, Clockwise"
  ];
  for (const route of argument.length > 0 ? [argument] : routes) {
    try {
      console.log(formatReport(route));
    } catch (error) {
      console.log(`rejected: ${error.message}`);
    }
  }
}

main();

