const CATEGORIES = {
  mercury: "terrestrial",
  venus: "terrestrial",
  earth: "terrestrial",
  mars: "terrestrial",
  jupiter: "gas giant",
  saturn: "gas giant",
  uranus: "ice giant",
  neptune: "ice giant",
  pluto: "dwarf planet"
};

const FIELD_SEPARATOR = ": ";
const MEMBER_SEPARATOR = ", ";

function normalize(name) {
  if (typeof name !== "string") {
    return "";
  }
  return name.trim().toLowerCase();
}

function categorize(planets) {
  if (!Array.isArray(planets)) {
    throw new TypeError("categorize expects a list of planet names");
  }
  return planets.map(function (planet) {
    const key = normalize(planet);
    return Object.prototype.hasOwnProperty.call(CATEGORIES, key)
      ? CATEGORIES[key]
      : "invalid";
  });
}

function titleCase(name) {
  const key = normalize(name);
  if (key === "") {
    return "(unnamed)";
  }
  return key.charAt(0).toUpperCase() + key.slice(1);
}

function labelFor(category) {
  if (category === "invalid") {
    return "unknown body";
  }
  return category;
}

function groupByCategory(planets) {
  const groups = new Map();
  categorize(planets).forEach(function (category, index) {
    if (!groups.has(category)) {
      groups.set(category, []);
    }
    groups.get(category).push(titleCase(planets[index]));
  });
  return groups;
}

function report(planets) {
  const lines = [];
  groupByCategory(planets).forEach(function (members, category) {
    lines.push(labelFor(category) + FIELD_SEPARATOR + members.join(MEMBER_SEPARATOR));
  });
  return lines.join("\n");
}

function main() {
  const sample = [
    "Mercury",
    " earth ",
    "MARS",
    "jupiter",
    "saturn",
    "neptune",
    "pluto",
    "vulcan"
  ];
  console.log(categorize(sample).join(MEMBER_SEPARATOR));
  console.log(report(sample));
}

main();

module.exports = { categorize, groupByCategory, report };

