const INTENT_GREETING = "greeting";
const INTENT_BILLING = "billing";
const INTENT_ASSISTANCE = "assistance";
const INTENT_CLOSING = "closing";
const INTENT_UNKNOWN = "unknown";

const GREETING_PREFIXES = [
  "hello",
  "hi"
];
const BILLING_KEYWORDS = [
  "price",
  "cost"
];
const ASSISTANCE_KEYWORDS = [
  "help",
  "support"
];
const CLOSING_KEYWORDS = [
  "bye",
  "quit"
];

const SEPARATOR = " ";

function normalize(message) {
  if (typeof message !== "string") {
    throw new TypeError("each message must be a string");
  }
  const cleaned = message.toLowerCase().replace(/[^a-z0-9\s]/g, SEPARATOR);
  return cleaned.trim().replace(/\s+/g, SEPARATOR);
}

function startsWithAny(text, prefixes) {
  const words = text.split(SEPARATOR);
  return prefixes.some((prefix) => words[0] === prefix);
}

function containsAny(text, keywords) {
  const words = text.split(SEPARATOR);
  return keywords.some((keyword) => words.includes(keyword));
}

function classify(message) {
  const text = normalize(message);
  if (startsWithAny(text, GREETING_PREFIXES)) {
    return INTENT_GREETING;
  }
  if (containsAny(text, BILLING_KEYWORDS)) {
    return INTENT_BILLING;
  }
  if (containsAny(text, ASSISTANCE_KEYWORDS)) {
    return INTENT_ASSISTANCE;
  }
  if (containsAny(text, CLOSING_KEYWORDS)) {
    return INTENT_CLOSING;
  }
  return INTENT_UNKNOWN;
}

function parse(messages) {
  if (!Array.isArray(messages)) {
    throw new TypeError("messages must be an array");
  }
  return messages.map(classify);
}

function summarize(intents) {
  const counts = new Map();
  for (const intent of intents) {
    counts.set(intent, (counts.get(intent) || 0) + 1);
  }
  const parts = [];
  for (const [intent, total] of counts) {
    parts.push(intent + "=" + total);
  }
  return parts.join(", ");
}

function main() {
  const conversation = [
    "Hello there, agent!",
    "What is the price of the premium plan?",
    "I need help with my invoice",
    "The cost seems too high",
    "Please quit the session",
    "The weather is nice today"
  ];
  const intents = parse(conversation);
  conversation.forEach((message, index) => {
    console.log(intents[index].padEnd(12, SEPARATOR) + message);
  });
  console.log("summary: " + summarize(intents));
}

main();

module.exports = { parse, classify, normalize, summarize };

