const SOLFEGE_TO_LETTER = {
  do: "c",
  re: "d",
  mi: "e",
  fa: "f",
  sol: "g",
  la: "a",
  ti: "b"
};

function normalize(note) {
  if (typeof note !== "string") {
    throw new TypeError("each note must be a string, got " + typeof note);
  }
  return note.trim().toLowerCase();
}

function translate(notes) {
  if (!Array.isArray(notes)) {
    throw new TypeError("translate expects an array of solfege syllables");
  }
  return notes.map(function (note) {
    const syllable = normalize(note);
    const letter = SOLFEGE_TO_LETTER[syllable];
    if (letter === undefined) {
      throw new RangeError("unknown solfege syllable: " + syllable);
    }
    return letter;
  });
}

function parsePhrase(phrase) {
  return phrase
    .split(/[\s,-]+/)
    .filter(function (token) {
      return token !== "";
    });
}

function formatScore(letters) {
  return letters
    .map(function (letter) {
      return letter.toUpperCase();
    })
    .join(" ");
}

function describe(phrase) {
  const syllables = parsePhrase(phrase);
  if (syllables.length === 0) {
    return "(silence)";
  }
  const letters = translate(syllables);
  const source = syllables.join("-");
  return source + " => " + formatScore(letters);
}

function main() {
  const phrases = [
    "do re mi fa sol la ti",
    "Sol, sol, la, sol, do",
    "mi mi fa sol"
  ];
  phrases.forEach(function (phrase) {
    console.log(describe(phrase));
  });
  try {
    console.log(describe("do si"));
  } catch (err) {
    console.log("error: " + err.message);
  }
}

main();

module.exports = { translate, parsePhrase, formatScore, describe };

