const PHRASES = {
  clr: 'clear sky',
  cld: 'cloudy',
  rn: 'raining',
  sn: 'snowing',
  st: 'stormy',
  fg: 'foggy',
  unk: 'unknown weather'
};

function normalizeCode(code) {
  if (typeof code !== 'string') {
    throw new TypeError('weather codes must be given as strings');
  }
  return code.trim().toLowerCase();
}

function describe(code) {
  const key = normalizeCode(code);
  if (!Object.prototype.hasOwnProperty.call(PHRASES, key)) {
    throw new RangeError('unrecognized weather code: ' + key);
  }
  return PHRASES[key];
}

function forecast(readings) {
  if (!Array.isArray(readings)) {
    throw new TypeError('forecast expects an array of weather codes');
  }
  return readings.map(describe);
}

function knownCodes() {
  return Object.keys(PHRASES).sort();
}

function formatHour(hour) {
  const padded = String(hour % 24).padStart(2, '0');
  return padded + ':00';
}

function displayBoard(readings, startHour) {
  const phrases = forecast(readings);
  return phrases.map(function (phrase, index) {
    const label = formatHour(startHour + index);
    return label + '  ' + phrase.toUpperCase();
  });
}

function summarize(readings) {
  const counts = new Map();
  forecast(readings).forEach(function (phrase) {
    counts.set(phrase, (counts.get(phrase) || 0) + 1);
  });
  const parts = [];
  counts.forEach(function (count, phrase) {
    parts.push(count + 'x ' + phrase);
  });
  return parts.join(', ');
}

function main() {
  const readings = [
    'clr',
    'cld',
    'RN ',
    'st',
    'fg',
    'unk',
    'clr'
  ];
  console.log(forecast(readings).join(' | '));
  displayBoard(readings, 6).forEach(function (line) {
    console.log(line);
  });
  console.log('summary: ' + summarize(readings));
  const supported = knownCodes().join(' ');
  console.log('supported: ' + supported);
  try {
    forecast(['hail']);
  } catch (err) {
    console.log('rejected input -> ' + err.message);
  }
}

main();

module.exports = { forecast, describe, displayBoard, summarize, knownCodes };

