const QUERY_PREFIXES = {
  read: "select from table",
  add: "insert into table",
  modify: "update table set",
  remove: "delete from table",
  count: "select count from table"
};

const NEWLINE = "\n";
const UNSUPPORTED_LABEL = "<unsupported>";

const DEFAULT_OPERATIONS = [
  "read",
  "add",
  "Modify ",
  "remove",
  "count",
  "read"
];

function normalize(operation) {
  if (typeof operation !== "string") {
    throw new TypeError("operation must be a string");
  }
  return operation.trim().toLowerCase();
}

function isSupported(operation) {
  return Object.prototype.hasOwnProperty.call(QUERY_PREFIXES, normalize(operation));
}

function generate(operations) {
  if (!Array.isArray(operations)) {
    throw new TypeError("operations must be an array");
  }
  const prefixes = [];
  for (const operation of operations) {
    const key = normalize(operation);
    if (!isSupported(key)) {
      throw new RangeError("unknown operation: " + key);
    }
    prefixes.push(QUERY_PREFIXES[key]);
  }
  return prefixes;
}

function summarize(operations) {
  const counts = new Map();
  for (const operation of operations) {
    const key = normalize(operation);
    counts.set(key, (counts.get(key) || 0) + 1);
  }
  const lines = [];
  for (const [key, total] of counts) {
    const label = isSupported(key) ? QUERY_PREFIXES[key] : UNSUPPORTED_LABEL;
    let line = key + " x";
    line += total;
    line += " -> ";
    lines.push(line + label);
  }
  return lines.join(NEWLINE);
}

function formatNumbered(prefix, index) {
  return (index + 1) + ". " + prefix;
}

function report(operations) {
  let prefixes;
  try {
    prefixes = generate(operations);
  } catch (error) {
    return "error: " + error.message;
  }
  const sections = [];
  sections.push("Generated queries:");
  sections.push(prefixes.map(formatNumbered).join(NEWLINE));
  sections.push("Summary:");
  sections.push(summarize(operations));
  return sections.join(NEWLINE);
}

function main() {
  const args = process.argv.slice(2);
  const requested = args.length > 0 ? args : DEFAULT_OPERATIONS;
  console.log(report(requested));
}

main();

module.exports = { generate, isSupported, summarize, report };

