const ZONE_MAP = {
  lion: "big cats",
  tiger: "big cats",
  elephant: "plains",
  rhino: "plains",
  penguin: "aquatic",
  seal: "aquatic",
  monkey: "primates",
  ape: "primates",
  parrot: "aviary",
  eagle: "aviary"
};

function normalize(animal) {
  if (typeof animal !== "string") {
    throw new TypeError("animal names must be strings");
  }
  return animal.trim().toLowerCase();
}

function zoneFor(animal) {
  const key = normalize(animal);
  const zone = ZONE_MAP[key];
  if (zone === undefined) {
    throw new Error("no zone defined for " + key);
  }
  return zone;
}

function route(animals) {
  if (!Array.isArray(animals)) {
    throw new TypeError("route expects an array of animal names");
  }
  return animals.map(zoneFor);
}

function countByZone(zones) {
  const totals = new Map();
  for (const zone of zones) {
    totals.set(zone, (totals.get(zone) || 0) + 1);
  }
  return totals;
}

function formatManifest(animals) {
  const zones = route(animals);
  const lines = animals.map(function (animal, index) {
    return normalize(animal) + " -> " + zones[index];
  });
  const totals = countByZone(zones);
  const summary = [...totals.entries()]
    .sort(function (a, b) {
      return a[0].localeCompare(b[0]);
    })
    .map(function (entry) {
      return entry[0] + ": " + entry[1];
    })
    .join(", ");
  lines.push("totals -> " + summary);
  return lines.join("\n");
}

function main() {
  const arrivals = [
    "Lion",
    "penguin",
    "ape",
    "eagle",
    "rhino",
