const BENEFITS = {
  free: "basic access",
  bronze: "ad removal",
  silver: "high definition",
  gold: "offline downloads",
  platinum: "family sharing",
  diamond: "dedicated support"
};

const TIER_ORDER = Object.keys(BENEFITS);

const DEFAULT_TIERS = [
  "free",
  "Bronze",
  " silver ",
  "gold",
  "PLATINUM",
  "diamond"
];

function normalizeTier(tier) {
  if (typeof tier !== "string") {
    throw new TypeError("tier must be a string, got " + typeof tier);
  }
  return tier.trim().toLowerCase();
}

function benefitOf(tier) {
  const key = normalizeTier(tier);
  if (!Object.prototype.hasOwnProperty.call(BENEFITS, key)) {
    throw new RangeError("unknown subscription tier: " + key);
  }
  return BENEFITS[key];
}

function features(tiers) {
  if (!Array.isArray(tiers)) {
    throw new TypeError("features expects an array of tier names");
  }
  return tiers.map(benefitOf);
}

function rankOf(tier) {
  return TIER_ORDER.indexOf(normalizeTier(tier));
}

function highestTier(tiers) {
  return tiers.reduce(function (best, tier) {
    return rankOf(tier) > rankOf(best) ? tier : best;
  }, "free");
}

function formatReport(tiers) {
  const benefits = features(tiers);
  const lines = tiers.map(function (tier, index) {
    const label = normalizeTier(tier).padEnd(9);
    const arrow = "-> ";
    return label + arrow + benefits[index];
  });
  const top = normalizeTier(highestTier(tiers));
  lines.push("best plan: " + top);
