  warning: "yellow",
  info: "blue",
  disabled: "gray",
  active: "purple"
};

const COLUMN_WIDTH = 10;
const PADDING = " ";
const ARROW = "-> ";
const SEPARATOR = ", ";
const STATUS_HEADING = "status";
const COLOR_HEADING = "color";

function normalize(status) {
  if (typeof status !== "string") {
    throw new TypeError("each status must be a string, received " + typeof status);
  }
  return status.trim().toLowerCase();
}

function isKnown(status) {
  return Object.prototype.hasOwnProperty.call(THEME, status);
}

function knownStatuses() {
  return Object.keys(THEME).sort();
}

function colorFor(status) {
  const key = normalize(status);
  if (!isKnown(key)) {
    throw new RangeError("unsupported interface status: " + key);
  }
  return THEME[key];
}

function resolve(statuses) {
  if (!Array.isArray(statuses)) {
    throw new TypeError("resolve expects an array of interface statuses");
  }
  return statuses.map(colorFor);
}

function formatRow(status, color) {
  const label = normalize(status).padEnd(COLUMN_WIDTH, PADDING);
  return label + ARROW + color;
}

function report(statuses) {
  const colors = resolve(statuses);
  const rows = statuses.map(function (status, index) {
