  v: "paste",
  x: "cut",
  z: "undo",
  y: "redo",
  s: "save"
};

const COMMAND_SEPARATOR = " | ";

function normalizeKey(key) {
  if (typeof key !== "string") {
    throw new TypeError("each key press must be a string, got " + typeof key);
  }
  return key.trim().toLowerCase();
}

function bind(keys) {
  if (!Array.isArray(keys)) {
    throw new TypeError("bind expects an array of key presses");
  }
  return keys.map(function (key) {
    const normalized = normalizeKey(key);
    if (!Object.prototype.hasOwnProperty.call(KEY_COMMANDS, normalized)) {
      throw new Error("no command is bound to the key " + JSON.stringify(key));
    }
    return KEY_COMMANDS[normalized];
  });
}

function describeBinding(key, command) {
  return normalizeKey(key) + " -> " + command;
}

function countCommands(commands) {
  const tally = new Map();
  commands.forEach(function (command) {
    tally.set(command, (tally.get(command) || 0) + 1);
  });
  return tally;
}

function formatSummary(commands) {
  if (commands.length === 0) {
    return "no keys pressed";
  }
  const parts = [];
  Array.from(countCommands(commands).entries())
    .sort(function (a, b) {
      return a[0].localeCompare(b[0]);
    })
    .forEach(function (entry) {
