const ROLE_STATS = {
  warrior: "strength",
  mage: "intelligence",
  rogue: "dexterity",
  cleric: "wisdom",
  bard: "charisma",
  paladin: "vitality"
};

function normalizeRole(role) {
  if (typeof role !== "string") {
    throw new TypeError("role name must be a string, got " + typeof role);
  }
  return role.trim().toLowerCase();
}

function statFor(role) {
  const key = normalizeRole(role);
  const stat = ROLE_STATS[key];
  if (stat === undefined) {
    throw new RangeError("unknown role: " + JSON.stringify(role));
  }
  return stat;
}

function attributes(classes) {
  if (!Array.isArray(classes)) {
    throw new TypeError("classes must be an array of role names");
  }
  return classes.map(statFor);
}

function tallyStats(classes) {
  const counts = new Map();
  for (const stat of attributes(classes)) {
    counts.set(stat, (counts.get(stat) || 0) + 1);
  }
  return counts;
}

function formatParty(classes) {
  const stats = attributes(classes);
  const width = classes.reduce(function (max, role) {
    return Math.max(max, normalizeRole(role).length);
  }, 0);
  const rows = classes.map(function (role, index) {
    const label = normalizeRole(role).padEnd(width, " ");
    return label + " -> " + stats[index];
  });
  return rows.join("\n");
}

function formatTally(classes) {
  const parts = [];
  tallyStats(classes).forEach(function (count, stat) {
    parts.push(stat + " x" + count);
  });
  return parts.join(", ");
}

function parseRoster(text) {
  return text.split(",").map(normalizeRole).filter(function (role) {
    return role.length > 0;
  });
}

