  march: "spring",
  april: "spring",
  may: "spring",
  june: "summer",
  july: "summer",
  august: "summer",
  september: "autumn",
  october: "autumn",
  november: "autumn",
  december: "winter"
};

const SEASON_ORDER = [
  "spring",
  "summer",
  "autumn",
  "winter"
];

function normalizeMonth(name) {
  if (typeof name !== "string") {
    throw new TypeError("month names must be supplied as strings");
  }
  return name.trim().toLowerCase();
}

function convert(months) {
  if (!Array.isArray(months)) {
    throw new TypeError("convert expects an array of month names");
  }
  return months.map(function (month) {
    const key = normalizeMonth(month);
    const season = SEASON_BY_MONTH[key];
    if (season === undefined) {
      throw new RangeError("unknown month name: " + key);
    }
    return season;
  });
}

function formatPairs(months, seasons) {
