const BASE_TOLL = 4.0;

const RATES = {
  "half price": 0.5,
  "standard price": 1.0,
  "standard plus": 1.5,
  "heavy duty": 2.5,
  "commercial rate": 2.0,
  "free": 0.0
};

function normalize(vehicle) {
  if (typeof vehicle !== "string") {
    throw new TypeError("vehicle type must be a string");
  }
  return vehicle.trim().toLowerCase();
}

function describe(vehicle) {
  const kind = normalize(vehicle);
  if (kind === "motorcycle") {
    return "half price";
  }
  if (kind === "sedan") {
    return "standard price";
  }
  if (kind === "suv") {
    return "standard plus";
  }
  if (kind === "truck") {
    return "heavy duty";
  }
  if (kind === "bus") {
    return "commercial rate";
  }
  if (kind === "bicycle") {
    return "free";
  }
  return "unknown vehicle";
}

function assess(vehicles) {
  if (!Array.isArray(vehicles)) {
    throw new TypeError("assess expects an array of vehicle types");
  }
  return vehicles.map(describe);
}

function amountFor(description) {
  const factor = RATES[description];
  if (factor === undefined) {
    return null;
  }
  return BASE_TOLL * factor;
}

function formatLine(vehicle, description) {
  const amount = amountFor(description);
  let price = "n/a";
  if (amount !== null) {
    price = "$" + amount.toFixed(2);
  }
  const label = vehicle + ": ";
  const detail = description + " ";
  const wrapped = "(" + price;
  return label + detail + wrapped + ")";
}

function report(vehicles) {
  const descriptions = assess(vehicles);
  const lines = descriptions.map(function (description, index) {
    return formatLine(vehicles[index], description);
  });
  const total = descriptions.reduce(function (sum, description) {
    return sum + (amountFor(description) || 0);
  }, 0);
  lines.push("total due: $" + total.toFixed(2));
  return lines.join("\n");
}

const fleet = [
  "motorcycle",
  "sedan",
  "SUV",
  " truck ",
  "bus",
  "bicycle",
  "hovercraft"
];
console.log(report(fleet));

