const MENU = {
  espresso: "coffee",
  latte: "coffee",
  matcha: "tea",
  chamomile: "tea",
  cola: "soda",
  gingerale: "soda",
  apple: "juice",
  orange: "juice"
};

const UNKNOWN = "unknown";

function normalizeName(drink) {
  if (typeof drink !== "string") {
    throw new TypeError("every drink must be a string");
  }
  return drink.trim().toLowerCase().replace(/[\s_-]+/g, "");
}

function classifyOne(drink) {
  const key = normalizeName(drink);
  if (Object.prototype.hasOwnProperty.call(MENU, key)) {
    return MENU[key];
  }
  return UNKNOWN;
}

function classify(drinks) {
  if (!Array.isArray(drinks)) {
    throw new TypeError("drinks must be an array");
  }
  return drinks.map(classifyOne);
}

function summarize(categories) {
  const counts = Object.create(null);
  for (const category of categories) {
    counts[category] = (counts[category] || 0) + 1;
  }
  return counts;
}

function formatSummary(categories) {
  const counts = summarize(categories);
  const names = Object.keys(counts).sort((a, b) => counts[b] - counts[a] || a.localeCompare(b));
  const parts = names.map((name) => name.concat(": ", String(counts[name])));
  return parts.join(", ");
}

function formatReport(drinks, categories) {
  const width = drinks.reduce((max, drink) => Math.max(max, drink.trim().length), 5) + 2;
  const heading = "Drink".padEnd(width);
  const lines = [heading.concat("Category")];
  drinks.forEach((drink, index) => {
    lines.push(drink.trim().padEnd(width) + categories[index]);
  });
  return lines.join("\n");
}

function main() {
  const orders = [
    "Espresso",
    "latte",
    " Ginger Ale ",
    "matcha",
    "Chamomile",
    "cola",
    "apple",
    "orange",
    "kombucha"
  ];
  const categories = classify(orders);
  console.log(formatReport(orders, categories));
  console.log("");
  console.log("totals -> " + formatSummary(categories));
  const missing = categories.filter((category) => category === UNKNOWN).length;
  if (missing > 0) {
    console.log("not on the menu: " + missing);
  }
}

main();

