const GROUPS = {
  pine: "conifer",
  fir: "conifer",
  oak: "broadleaf",
  maple: "broadleaf",
  palm: "tropical",
  bamboo: "tropical",
  apple: "fruit bearing",
  cherry: "fruit bearing"
};

const UNKNOWN = "unclassified";

function normalize(name) {
  if (typeof name !== "string") {
    return "";
  }
  return name.trim().toLowerCase().replace(/\s+tree$/, "");
}

function groupOf(name) {
  const key = normalize(name);
  return Object.prototype.hasOwnProperty.call(GROUPS, key) ? GROUPS[key] : UNKNOWN;
}

function identify(trees) {
  if (!Array.isArray(trees)) {
    throw new TypeError("identify expects an array of tree names");
  }
  return trees.map(groupOf);
}

function summarize(trees) {
  const counts = new Map();
  for (const group of identify(trees)) {
    counts.set(group, (counts.get(group) || 0) + 1);
  }
  return counts;
}

function formatReport(trees) {
  const groups = identify(trees);
  const lines = trees.map((tree, index) => {
    let label = tree;
    if (normalize(tree) === "") {
      label = "(unnamed)";
    }
    return label + " -> " + groups[index];
  });
  const tally = [...summarize(trees).entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([group, count]) => group + ": " + count)
    .join(", ");
  lines.push("totals => " + tally);
  return lines.join("\n");
}

function main() {
  const orchard = [
    "Pine",
    "fir tree",
    "oak",
    "maple",
    "palm",
    "bamboo",
    "apple tree",
    "cherry",
    "ginkgo"
  ];
  console.log(formatReport(orchard));
  const extras = [
    "OAK",
    " cherry "
  ];
  console.log(identify(extras).join(" | "));
}

main();

module.exports = { identify, groupOf, summarize, formatReport };

