const DEPARTMENTS = {
  sweeping: "cleaning",
  mopping: "cleaning",
  cooking: "kitchen",
  baking: "kitchen",
  painting: "maintenance",
  fixing: "maintenance",
  guarding: "security",
  patrolling: "security"
};

const UNASSIGNED = "unassigned";

function normalize(chore) {
  if (typeof chore !== "string") {
    throw new TypeError("each chore must be a string");
  }
  const key = chore.trim().toLowerCase();
  if (key === "") {
    throw new RangeError("a chore name cannot be empty");
  }
  return key;
}

function departmentFor(chore) {
  const key = normalize(chore);
  return Object.prototype.hasOwnProperty.call(DEPARTMENTS, key) ? DEPARTMENTS[key] : UNASSIGNED;
}

function schedule(tasks) {
  if (!Array.isArray(tasks)) {
    throw new TypeError("tasks must be an array of chore names");
  }
  return tasks.map(departmentFor);
}

function groupByDepartment(tasks) {
  const assignments = schedule(tasks);
  const groups = new Map();
  assignments.forEach(function (department, index) {
    if (!groups.has(department)) {
      groups.set(department, []);
    }
    groups.get(department).push(normalize(tasks[index]));
  });
  return groups;
}

function formatRoster(tasks) {
  const groups = groupByDepartment(tasks);
  const names = Array.from(groups.keys()).sort();
  return names
    .map(function (department) {
      const members = groups.get(department).join(", ");
      return department.toUpperCase() + ": " + members;
    })
    .join("\n");
}

