const KEPT = [
  "error",
  "fatal",
  "critical"
];
const DISCARDED = [
  "debug",
  "info",
  "warning"
];

function normalizeSeverity(severity) {
  if (typeof severity !== "string") {
    throw new TypeError("severity must be a string");
  }
  return severity.trim().toLowerCase();
}

function isKept(severity) {
  if (KEPT.includes(severity)) {
    return true;
  }
  if (DISCARDED.includes(severity)) {
    return false;
  }
  throw new RangeError("unknown severity level: " + severity);
}

function formatEntry(severity, message) {
  const opened = "(" + severity.toUpperCase();
  const tag = opened + ")";
  return message + " " + tag;
}

function filter(logs) {
  if (!Array.isArray(logs)) {
    throw new TypeError("logs must be an array of entries");
  }
  const kept = [];
  for (const entry of logs) {
    if (!Array.isArray(entry) || entry.length !== 2) {
      throw new TypeError("each entry must be a severity/message pair");
    }
    const severity = normalizeSeverity(entry[0]);
    if (typeof entry[1] !== "string") {
      throw new TypeError("message must be a string");
    }
    if (isKept(severity)) {
      kept.push(formatEntry(severity, entry[1].trim()));
    }
  }
  return kept;
}

function report(logs) {
  const kept = filter(logs);
  if (kept.length === 0) {
    return "no actionable logs";
  }
  return kept
    .map((line, index) => index + 1 + ". " + line)
    .join("\n");
}

function main() {
  const logs = [
    [
      "debug",
      "entering request handler"
    ],
    [
      "error",
      "database crash"
    ],
    [
      "Critical",
      "disk full on /var"
    ],
    [
      "FATAL",
      "unrecoverable segfault in worker 3"
    ]
  ];
  console.log(report(logs));
}

main();

module.exports = { filter, report, formatEntry };

