const PRICE_LIST = new Map([
  ["short", 2],
  ["tall", 3],
  ["grande", 4],
  ["venti", 5],
  ["trenta", 6]
]);

const DISCOUNT_THRESHOLD = 4;
const DISCOUNT_AMOUNT = 1;
const SIZE_SEPARATOR = " ";
const LIST_SEPARATOR = ", ";

function normalizeSize(size) {
  if (typeof size !== "string") {
    return "";
  }
  return size.trim().toLowerCase();
}

function priceOf(size) {
  const key = normalizeSize(size);
  return PRICE_LIST.has(key) ? PRICE_LIST.get(key) : 0;
}

function parseTicket(text) {
  return text.split(SIZE_SEPARATOR).filter(function (word) {
    return word.length > 0;
  });
}

function summarize(orders) {
  if (!Array.isArray(orders)) {
    throw new TypeError("summarize expects an array of cup sizes");
  }
  const summary = { served: 0, ignored: [], subtotal: 0, discount: 0 };
  for (const entry of orders) {
    const price = priceOf(entry);
    if (price === 0) {
      summary.ignored.push(normalizeSize(entry) || "(empty)");
    } else {
      summary.served += 1;
      summary.subtotal += price;
    }
  }
  if (orders.length > DISCOUNT_THRESHOLD) {
    summary.discount = DISCOUNT_AMOUNT;
  }
  return summary;
}

function calculate(orders) {
  const summary = summarize(orders);
  const total = Math.max(0, summary.subtotal - summary.discount);
  return "Total is " + total;
}

function report(orders) {
  const summary = summarize(orders);
  const lines = [calculate(orders)];
  lines.push("Cups served: " + summary.served);
  if (summary.ignored.length > 0) {
    lines.push("Ignored sizes: " + summary.ignored.join(LIST_SEPARATOR));
  }
  if (summary.discount > 0) {
    lines.push("Bulk discount: -" + summary.discount);
  }
  return lines.join("\n");
}

function main() {
  const tickets = [
    "short tall grande",
    "venti trenta mug demi",
    "short short tall venti grande"
  ];
  tickets.forEach(function (text, index) {
    console.log("Ticket #" + (index + 1));
    console.log(report(parseTicket(text)));
    console.log("");
  });
}

main();

module.exports = { calculate, report, summarize, priceOf, normalizeSize, parseTicket };

