const SHUTTER_PRIORITY = "shutter priority";
const APERTURE_PRIORITY = "aperture priority";
const MANUAL_MODE = "manual mode";
const AUTO_FLASH = "auto flash";
const PROGRAM_AUTO = "program auto";

const SHUTTER_SCENES = [
  "sport",
  "action",
  "race",
  "match",
  "football"
];

const APERTURE_SCENES = [
  "portrait",
  "macro",
  "headshot",
  "closeup",
  "bokeh"
];

const MANUAL_SCENES = [
  "landscape",
  "architecture",
  "cathedral",
  "skyline",
  "mountain"
];

const FLASH_SCENES = [
  "party",
  "indoor",
  "reception",
  "birthday"
];

function singular(word) {
  if (word.length > 4 && word.endsWith("ies")) {
    return `${word.slice(0, -3)}y`;
  }
  if (word.length > 3 && word.endsWith("s")) {
    return word.slice(0, -1);
  }
  return word;
}

const MODE_TABLE = [
  { mode: SHUTTER_PRIORITY, keywords: new Set(SHUTTER_SCENES.map(singular)) },
  { mode: APERTURE_PRIORITY, keywords: new Set(APERTURE_SCENES.map(singular)) },
  { mode: MANUAL_MODE, keywords: new Set(MANUAL_SCENES.map(singular)) },
  { mode: AUTO_FLASH, keywords: new Set(FLASH_SCENES.map(singular)) }
];

function tokenize(scene) {
  if (typeof scene !== "string") {
    throw new TypeError("Each scene description must be a string");
  }
  const cleaned = scene.toLowerCase().replace(/[^a-z0-9]+/g, " ");
  return cleaned.split(/\s+/).filter(Boolean).map(singular);
}

function classifyScene(scene) {
  const tokens = tokenize(scene);
  for (const entry of MODE_TABLE) {
    if (tokens.some((token) => entry.keywords.has(token))) {
      return entry.mode;
    }
  }
  return PROGRAM_AUTO;
}

function shoot(scenes) {
  if (!Array.isArray(scenes)) {
    throw new TypeError("shoot expects an array of scene descriptions");
  }
  return scenes.map(classifyScene);
}

function formatReport(scenes, modes) {
  const header = "Selected camera configurations";
  const rule = "=".repeat(header.length);
  const rows = scenes.map((scene, index) => `${index + 1}. ${scene} -> ${modes[index]}`);
  return [header, rule].concat(rows).join("\n");
}

const plannedScenes = [
  "Sunday league football match",
  "Studio portrait of a violinist",
  "Macro shot of a dew covered web",
  "Mountain landscape at golden hour",
  "Gothic cathedral architecture",
  "Office parties indoors",
  "Still life of fruit on a table"
];

console.log(formatReport(plannedScenes, shoot(plannedScenes)));

