"use strict";

const SIGN_BY_MONTH = {
  january: "capricorn",
  february: "aquarius",
  march: "pisces",
  april: "aries",
  may: "taurus",
  june: "gemini",
  july: "cancer",
  august: "leo",
  september: "virgo",
  october: "libra",
  november: "scorpio",
  december: "sagittarius"
};

const MONTH_NAMES = Object.keys(SIGN_BY_MONTH);

function normalizeMonth(value) {
  if (typeof value === "number" && Number.isInteger(value)) {
    return MONTH_NAMES[value - 1] || "";
  }
  if (typeof value !== "string") {
    return "";
  }
  const cleaned = value.trim().toLowerCase().replace(/[^a-z]/g, "");
  if (cleaned.length < 3) {
    return "";
  }
  return MONTH_NAMES.find((name) => name.startsWith(cleaned)) || "";
}

function zodiac(months) {
  if (!Array.isArray(months)) {
    throw new TypeError("zodiac expects an array of birth months");
  }
  return months.map((month) => SIGN_BY_MONTH[normalizeMonth(month)] || "unknown");
}

function countSigns(signs) {
  const tally = new Map();
  for (const sign of signs) {
    tally.set(sign, (tally.get(sign) || 0) + 1);
  }
  return tally;
}

function formatReport(months, signs) {
  const width = months.reduce((max, m) => Math.max(max, String(m).length), 0);
  const arrow = " -> ";
  const rows = months.map((month, i) => String(month).padEnd(width) + arrow + signs[i]);
  const tally = countSigns(signs);
  const summary = [...tally.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([sign, n]) => sign + " x" + n)
    .join(", ");
  rows.push("totals: " + summary);
  return rows.join("\n");
}

const birthMonths = [
  "April",
  " may ",
  "Dec",
  "june",
  7,
  "MARCH",
  "Octo",
  "smarch",
  null,
  2
];
const signs = zodiac(birthMonths);
console.log(formatReport(birthMonths, signs));
console.log(signs.join(", "));

module.exports = { zodiac, normalizeMonth, countSigns, formatReport };

