function normalize(code) {
  if (typeof code !== "string") {
    throw new TypeError("every status code must be a string");
  }
  return code.trim().toLowerCase().replace(/\s+/g, " ");
}

function describeOne(code) {
  switch (normalize(code)) {
    case "ok":
      return "success";
    case "bad request":
      return "user error";
    case "unauthorized":
      return "login required";
    case "forbidden":
      return "access denied";
    case "not found":
      return "missing page";
    case "internal error":
      return "server crash";
    default:
      return "unknown status";
  }
}

function describe(codes) {
  if (!Array.isArray(codes)) {
    throw new TypeError("describe expects an array of status codes");
  }
  return codes.map(describeOne);
}

function tally(descriptions) {
  const counts = new Map();
  for (const text of descriptions) {
    counts.set(text, (counts.get(text) || 0) + 1);
  }
  return counts;
}

function formatReport(codes) {
  const descriptions = describe(codes);
  const lines = codes.map(function (code, index) {
    return normalize(code) + " => " + descriptions[index];
  });
  const summary = [];
  for (const [text, count] of tally(descriptions)) {
    summary.push(text + " x" + count);
  }
  const separator = ", ";
  lines.push("-- " + summary.join(separator));
  return lines.join("\n");
}

