const OPENING_TAGS = [
  "div",
  "span",
  "paragraph",
  "anchor"
];
const CLOSING_PREFIX = "end";

function isOpeningTag(tag) {
  return OPENING_TAGS.indexOf(tag) !== -1;
}

function closingTargetOf(tag) {
  if (!tag.startsWith(CLOSING_PREFIX)) {
    return null;
  }
  const target = tag.slice(CLOSING_PREFIX.length);
  return isOpeningTag(target) ? target : null;
}

function verify(tags) {
  const stack = [];
  for (const raw of tags) {
    const tag = String(raw).trim().toLowerCase();
    if (isOpeningTag(tag)) {
      stack.push(tag);
      continue;
    }
    const target = closingTargetOf(tag);
    if (target === null) {
      throw new Error("unrecognised tag: " + tag);
    }
    if (stack.pop() !== target) {
      return "mismatch";
    }
  }
  if (stack.length > 0) {
    return "incomplete";
  }
  return "valid";
}

function parseTagList(text) {
  return text
    .split(/[\s,]+/)
    .filter(function (piece) {
      return piece.length > 0;
    });
}

function describe(result) {
  switch (result) {
    case "valid":
      return "all tags are perfectly balanced";
    case "mismatch":
      return "a tag was closed out of order";
    default:
      return "some tags were left open";
  }
}

function report(text) {
  const tags = parseTagList(text);
  try {
    const result = verify(tags);
    return result + " -> " + describe(result);
  } catch (error) {
    return "error -> " + error.message;
  }
}

function main() {
  const samples = [
    "div span endspan enddiv",
    "div paragraph endparagraph anchor endanchor enddiv",
    "div span enddiv endspan",
    "div span endspan",
    "div table endtable enddiv"
  ];
  for (const sample of samples) {
    const line = sample + ": " + report(sample);
    console.log(line);
  }
}

main();

