const POLYGONS = [
  "triangle",
  "square",
  "pentagon",
  "hexagon",
  "octagon"
];

const CURVES = [
  "circle",
  "oval",
  "ellipse",
  "crescent"
];

const LABELS = [
  "polygons",
  "curves",
  "others"
];

const EMPTY_GROUP = "(none)";
const SEPARATOR = ", ";

function normalize(shape) {
  if (typeof shape !== "string") {
    throw new TypeError("every shape must be a string");
  }
  return shape.trim().toLowerCase();
}

function classify(shape) {
  const name = normalize(shape);
  if (POLYGONS.indexOf(name) !== -1) {
    return LABELS[0];
  }
  if (CURVES.indexOf(name) !== -1) {
    return LABELS[1];
  }
  return LABELS[2];
}

function sort(shapes) {
  if (!Array.isArray(shapes)) {
    throw new TypeError("sort expects an array of shapes");
  }
  const groups = [[], [], []];
  for (const shape of shapes) {
    groups[LABELS.indexOf(classify(shape))].push(shape);
  }
  return groups;
}

function describe(groups) {
  const lines = groups.map(function (group, index) {
    const body = group.length === 0 ? EMPTY_GROUP : group.join(SEPARATOR);
    return LABELS[index] + ": " + body;
  });
  return lines.join("\n");
}

function main() {
  const input = [
    "Triangle",
    "circle",
    "blob",
    "hexagon",
    " ellipse ",
    "square",
    "crescent",
    "spiral",
    "octagon",
    "oval",
    "pentagon",
