const POINTS = {
  A: 4,
  B: 3,
  C: 2,
  D: 1,
  F: 0
};

const ALIASES = {
  EXCELLENT: "A",
  GOOD: "B",
  AVERAGE: "C",
  POOR: "D",
  FAILING: "F",
  WITHDRAW: "W",
  AUDIT: "AU",
  INCOMPLETE: "I"
};

const UNSCORED = new Set([
  "W",
  "AU",
  "I"
]);

const SKIPPED_PREFIX = " (";
const SKIPPED_SUFFIX = " not counted)";

function normalize(grade) {
  if (typeof grade !== "string") {
    throw new TypeError("Every grade must be supplied as a string");
  }
  const code = grade.trim().toUpperCase();
  if (code.length === 0) {
    throw new RangeError("A grade cannot be blank");
  }
  return Object.prototype.hasOwnProperty.call(ALIASES, code) ? ALIASES[code] : code;
}

function pointsFor(code) {
  if (!Object.prototype.hasOwnProperty.call(POINTS, code)) {
    throw new RangeError("Unrecognized grade: " + code);
  }
  return POINTS[code];
}

function summarize(grades) {
  return grades.map(normalize).reduce(function (acc, code) {
    if (UNSCORED.has(code)) {
      acc.skipped += 1;
    } else {
      acc.points += pointsFor(code);
      acc.counted += 1;
    }
    return acc;
  }, { points: 0, counted: 0, skipped: 0 });
}

function formatAverage(value) {
  return value.toFixed(2).replace(/\.?0+$/, "");
}

function gpa(grades) {
  if (!Array.isArray(grades)) {
    throw new TypeError("gpa expects an array of letter grades");
  }
  const summary = summarize(grades);
  const average = summary.counted === 0 ? 0 : summary.points / summary.counted;
  return "Average is " + formatAverage(average);
}

function parseTranscript(line) {
  const split = line.indexOf(":");
  if (split < 0) {
    throw new SyntaxError("A transcript line needs a term followed by a colon");
  }
  const listed = line.slice(split + 1).split(",");
  return {
    term: line.slice(0, split).trim(),
    grades: listed.filter(function (part) {
      return part.trim().length > 0;
    })
  };
}

function report(lines) {
  return lines.map(function (line) {
    const record = parseTranscript(line);
    const summary = summarize(record.grades);
    let note = "";
    if (summary.skipped > 0) {
      note = SKIPPED_PREFIX + summary.skipped + SKIPPED_SUFFIX;
    }
    return record.term + " -> " + gpa(record.grades) + note;
  }).join("\n");
}

const TRANSCRIPTS = [
  "Spring: A, B, W, C, A",
  "Fall: Good, Incomplete, D, F, Audit, Excellent",
  "Summer: W, Audit"
];

console.log(report(TRANSCRIPTS));

