const BEATS = {
  rock: "scissors lizard",
  paper: "rock spock",
  scissors: "paper lizard",
  lizard: "paper spock",
  spock: "rock scissors"
};

const VALID_MOVES = Object.keys(BEATS);
const PLAYER_ONE = "player one";
const PLAYER_TWO = "player two";
const DRAW = "draw";
const INVALID = "invalid";

function normalize(move) {
  if (typeof move !== "string") {
    return null;
  }
  const cleaned = move.trim().toLowerCase();
  return VALID_MOVES.indexOf(cleaned) === -1 ? null : cleaned;
}

function defeats(attacker, defender) {
  return BEATS[attacker].split(" ").indexOf(defender) !== -1;
}

function judgeMatch(match) {
  if (!Array.isArray(match) || match.length !== 2) {
    return INVALID;
  }
  const one = normalize(match[0]);
  const two = normalize(match[1]);
  if (one === null || two === null) {
    return INVALID;
  }
  if (one === two) {
    return DRAW;
  }
  if (defeats(one, two)) {
    return PLAYER_ONE;
  }
  return PLAYER_TWO;
}

function judge(matches) {
  if (!Array.isArray(matches)) {
    throw new TypeError("judge expects an array of matches");
  }
  return matches.map(judgeMatch);
}

function describe(match, outcome) {
  const moves = Array.isArray(match) ? match.join(" vs ") : String(match);
  let label = outcome;
  if (outcome === INVALID) {
    label = "invalid move";
  } else if (outcome !== DRAW) {
    label = outcome + " wins";
  }
  return moves + ": " + label;
}

function report(matches) {
  const outcomes = judge(matches);
  return outcomes
    .map((outcome, index) => describe(matches[index], outcome))
    .join("\n");
}

function parseMatch(line) {
  return line.split("/").map((part) => part.trim());
}

const ROUNDS = [
  "rock / scissors",
  "Spock / paper",
  "lizard / lizard",
  "paper / spock",
  "scissors / banana",
  "lizard / rock"
];

const tournament = ROUNDS.map(parseMatch);
const summary = judge(tournament).join(", ");

console.log(report(tournament));
console.log("outcomes: " + summary);

