const PIECE_VALUES = {
  "pawn": 1,
  "knight": 3,
  "bishop": 3,
  "rook": 5,
  "queen": 9,
  "king": 0
};

const CAPTURE = "capture";
const SACRIFICE = "sacrifice";
const LIST_SEPARATOR = ", ";
const PLUS_SEPARATOR = " + ";
const ARROW = " => ";

function normalize(token) {
  if (typeof token !== "string") {
    throw new TypeError("every entry must be a string");
  }
  return token.trim().toLowerCase();
}

function isModifier(word) {
  return word === CAPTURE || word === SACRIFICE;
}

function parse(pieces) {
  if (!Array.isArray(pieces)) {
    throw new TypeError("pieces must be an array");
  }
  const words = pieces.map(normalize);
  const unknown = words.filter(function (word) {
    return !(word in PIECE_VALUES) && !isModifier(word);
  });
  if (unknown.length > 0) {
    throw new Error("unrecognised term: " + unknown.join(LIST_SEPARATOR));
  }
  return words;
}

function evaluate(pieces) {
  const words = parse(pieces);
  let total = words.reduce(function (sum, word) {
    return sum + (PIECE_VALUES[word] || 0);
  }, 0);
  if (words.includes(CAPTURE)) {
    total *= 2;
  }
  if (words.includes(SACRIFICE)) {
    total /= 2;
  }
  return total;
}

function describe(pieces) {
  const words = parse(pieces);
  const material = words.filter(function (word) {
    return word in PIECE_VALUES;
  });
  const modifiers = words.filter(isModifier);
  const parts = [];
  if (material.length > 0) {
    parts.push(material.join(PLUS_SEPARATOR));
  } else {
    parts.push("nothing");
  }
  if (modifiers.length > 0) {
    parts.push(modifiers.join(LIST_SEPARATOR));
  }
  return parts.join(" ") + ARROW + evaluate(pieces);
}

