  const key = normalize(code);
  if (key === null) {
    return REFUND;
  }
  if (key === EMPTY_REQUEST) {
    return PROMPT;
  }
  const item = CATALOG[key];
  return typeof item === "string" ? item : REFUND;
}

function vend(codes) {
  if (!Array.isArray(codes)) {
    throw new TypeError("vend expects an array of button codes");
  }
  return codes.map(dispense);
}

