  const tally = { dispensed: 0, prompts: 0, refunds: 0 };
  for (const result of results) {
    if (result === REFUND) {
      tally.refunds += 1;
    } else if (result === PROMPT) {
      tally.prompts += 1;
    } else {
      tally.dispensed += 1;
