const WEEKDAYS = [
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday"
];

const WEEKENDS = [
  "saturday",
  "sunday"
];

const QUOTE = "\"";

const EMPTY_GROUP = "(none)";

const SEPARATOR = ", ";

const LABELS = [
  "Weekdays",
  "Weekends",
  "Invalid"
];

function normalize(day) {
  if (typeof day !== "string") {
    return "";
  }
  return day.trim().toLowerCase();
}

function categoryOf(day) {
  const key = normalize(day);
  if (WEEKDAYS.indexOf(key) !== -1) {
    return "weekday";
  }
  if (WEEKENDS.indexOf(key) !== -1) {
    return "weekend";
  }
  return "invalid";
}

function schedule(days) {
  if (!Array.isArray(days)) {
    throw new TypeError("schedule expects an array of day names");
  }
  const weekdays = [];
  const weekends = [];
  const invalids = [];
  for (const day of days) {
    const category = categoryOf(day);
    if (category === "weekday") {
      weekdays.push(day);
    } else if (category === "weekend") {
      weekends.push(day);
    } else {
      invalids.push(day);
    }
  }
  return [weekdays, weekends, invalids];
}

function describe(value) {
  if (typeof value === "string") {
    return QUOTE + value + QUOTE;
  }
  return String(value);
}

function report(days) {
  const groups = schedule(days);
  const lines = [];
  for (let i = 0; i < groups.length; i += 1) {
    const items = groups[i].map(describe);
    const body = items.length > 0 ? items.join(SEPARATOR) : EMPTY_GROUP;
    lines.push(LABELS[i] + ": " + body);
  }
  return lines.join("\n");
}

