const GENRE_MAP = {
  rock: "heavy",
  metal: "heavy",
  punk: "heavy",
  jazz: "smooth",
  blues: "smooth",
  soul: "smooth",
  techno: "electronic",
  house: "electronic",
  trance: "electronic",
  rap: "urban",
  hiphop: "urban"
};

const FALLBACK_GENRE = "miscellaneous";

function normalizeStyle(style) {
  if (typeof style !== "string") {
    throw new TypeError("each style must be a string");
  }
  return style.trim().toLowerCase().replace(/[\s_-]+/g, "");
}

function categorize(tracks) {
  if (!Array.isArray(tracks)) {
    throw new TypeError("categorize expects an array of style names");
  }
  return tracks.map(function (style) {
    const key = normalizeStyle(style);
    return Object.prototype.hasOwnProperty.call(GENRE_MAP, key) ? GENRE_MAP[key] : FALLBACK_GENRE;
  });
}

function countByGenre(tracks) {
  const tally = new Map();
  categorize(tracks).forEach(function (genre) {
    tally.set(genre, (tally.get(genre) || 0) + 1);
  });
  return tally;
}

function summarize(tracks) {
  const entries = Array.from(countByGenre(tracks).entries());
  if (entries.length === 0) {
    return "no tracks";
  }
  return entries
    .sort(function (a, b) {
      return b[1] - a[1] || a[0].localeCompare(b[0]);
    })
    .map(function (entry) {
      return entry[0] + "=" + entry[1];
    })
    .join(", ");
}

function formatReport(tracks) {
  const genres = categorize(tracks);
  const lines = tracks.map(function (style, index) {
    return normalizeStyle(style) + " -> " + genres[index];
  });
  lines.push("summary: " + summarize(tracks));
  return lines.join("\n");
}

function main() {
  const playlist = [
    "metal",
    "jazz",
    "Trance",
    "hip-hop",
    "punk",
    "polka",
    "soul",
    "house"
  ];
  console.log(categorize(playlist).join(" | "));
  console.log(formatReport(playlist));
}

main();

module.exports = { categorize, countByGenre, summarize, formatReport };

