const COIN_VALUES = {
  'penny': 1,
  'nickel': 5,
  'dime': 10,
  'quarter': 25,
  'half dollar': 50,
  'dollar': 100
};

const FOREIGN = 'foreign';

const FOREIGN_PENALTY = -5;

const LIST_SEPARATOR = ', ';

function normalize(name) {
  if (typeof name !== 'string') {
    return '';
  }
  return name.trim().toLowerCase().replace(/\s+/g, ' ');
}

function valueOf(name) {
  const key = normalize(name);
  if (key === FOREIGN) {
    return FOREIGN_PENALTY;
  }
  if (Object.prototype.hasOwnProperty.call(COIN_VALUES, key)) {
    return COIN_VALUES[key];
  }
  return 0;
}

function tally(coins) {
  if (!Array.isArray(coins)) {
    throw new TypeError('tally expects an array of coin names');
  }
  let total = 0;
  for (const coin of coins) {
    total += valueOf(coin);
  }
  return 'Total cents is ' + total;
}

function describe(coins) {
  const counted = [];
  const ignored = [];
  for (const coin of coins) {
    const key = normalize(coin);
    if (key === FOREIGN || Object.prototype.hasOwnProperty.call(COIN_VALUES, key)) {
      counted.push(key);
    } else {
      ignored.push(key);
    }
  }
  const lines = [tally(coins)];
  if (counted.length > 0) {
    lines.push('Counted: ' + counted.join(LIST_SEPARATOR));
  }
  if (ignored.length > 0) {
    lines.push('Ignored: ' + ignored.join(LIST_SEPARATOR));
  }
  return lines.join('\n');
}

function main() {
  const purse = [
    'quarter',
    'Dime',
    'penny',
    'half dollar',
    'foreign',
    'button',
    'dollar',
    'nickel'
  ];
  console.log(describe(purse));
  const travelChange = [
    'foreign',
    'foreign',
    'penny'
  ];
  console.log(tally(travelChange));
  console.log(tally([]));
}

