const GRAB_SCREWDRIVER = "grab screwdriver";
const GRAB_HAMMER = "grab hammer";
const APPLY_GLUE = "apply glue";
const ATTACH_DOOR = "attach door";
const TIGHTEN_BOLT = "tighten bolt";
const CHECK_MANUAL = "check manual";

const ACTIONS = new Map([
  ["screw", GRAB_SCREWDRIVER],
  ["peg", GRAB_HAMMER],
  ["board", APPLY_GLUE],
  ["hinge", ATTACH_DOOR],
  ["handle", TIGHTEN_BOLT]
]);

function normalizePart(part) {
  if (typeof part !== "string") {
    throw new TypeError("each part name must be a string");
  }
  const name = part.trim().toLowerCase();
  if (name.length === 0) {
    throw new RangeError("part names must not be empty");
  }
  if (name.endsWith("s")) {
    return name.slice(0, -1);
  }
  return name;
}

function actionFor(part) {
  const name = normalizePart(part);
  if (ACTIONS.has(name)) {
    return ACTIONS.get(name);
  }
  return CHECK_MANUAL;
}

function assemble(parts) {
  if (!Array.isArray(parts)) {
    throw new TypeError("assemble expects an array of part names");
  }
  return parts.map(actionFor);
}

function summarize(parts) {
  const counts = new Map();
  for (const step of assemble(parts)) {
    counts.set(step, (counts.get(step) || 0) + 1);
  }
  const lines = [];
  for (const [step, times] of counts) {
    if (times === 1) {
      lines.push(step);
    } else {
      lines.push(step + " x" + times);
    }
  }
  return lines.join("; ");
}

function formatInstructions(parts) {
  const steps = assemble(parts);
  if (steps.length === 0) {
    return "nothing to assemble";
  }
  const lines = steps.map(function (step, index) {
    return String(index + 1) + ". " + step;
  });
  return lines.join("\n");
}

function main() {
  const order = [
    "pegs",
    "boards",
    "screw",
    "Hinges",
    "handle",
    "sandpaper"
  ];
  console.log(formatInstructions(order));
  console.log("summary: " + summarize(order));
}

main();

module.exports = { assemble, actionFor, summarize, formatInstructions };

