const DICTIONARY = {
  hello: "hola",
  goodbye: "adios",
  please: "por favor",
  thanks: "gracias",
  yes: "si",
  no: "no",
  morning: "buenos dias",
  night: "buenas noches"
};

const UNKNOWN = "?";

function normalize(word) {
  if (typeof word !== "string") {
    return "";
  }
  return word.trim().toLowerCase().replace(/[.,!?;:]+$/, "");
}

function translateWord(word) {
  const key = normalize(word);
  if (Object.prototype.hasOwnProperty.call(DICTIONARY, key)) {
    return DICTIONARY[key];
  }
  return UNKNOWN;
}

function translate(greetings) {
  if (!Array.isArray(greetings)) {
    throw new TypeError("translate expects an array of greetings");
  }
  return greetings.map(translateWord);
}

function countUnknown(translated) {
  return translated.filter(function (word) {
    return word === UNKNOWN;
  }).length;
}

function formatPairs(greetings, translated) {
  return greetings
    .map(function (word, index) {
      return normalize(word) + " -> " + translated[index];
    })
    .join("\n");
}

function report(greetings) {
  const translated = translate(greetings);
  const missing = countUnknown(translated);
  const sentence = translated.join(" ");
  const lines = [formatPairs(greetings, translated)];
  lines.push("spanish: " + sentence);
  if (missing > 0) {
    lines.push("untranslated words: " + missing);
  } else {
    lines.push("every word was translated");
  }
  return lines.join("\n");
}

function main() {
  const input = [
    "Hello",
    "morning",
    "please",
    "Thanks",
    "yes",
    "no",
    "night",
    "goodbye",
    "pizza"
  ];
  console.log(report(input));
  console.log(JSON.stringify(translate(input)));
}

main();

module.exports = { translate, translateWord, report };

