const POSITIVE_WORDS = new Set([
  "happy",
  "great",
  "excellent",
  "joyful"
]);

const NEGATIVE_WORDS = new Set([
  "sad",
  "terrible",
  "awful",
  "miserable"
]);

const NEUTRAL_WORDS = new Set([
  "okay",
  "fine",
  "whatever"
]);

function normalize(word) {
  if (typeof word !== "string") {
    throw new TypeError("analyze expects an array of strings");
  }
  return word.trim().toLowerCase().replace(/[.,!?;:]+$/, "");
}

function classify(word) {
  const key = normalize(word);
  if (POSITIVE_WORDS.has(key)) {
    return "positive";
  }
  if (NEGATIVE_WORDS.has(key)) {
    return "negative";
  }
  if (NEUTRAL_WORDS.has(key)) {
    return "neutral";
  }
  return "unknown";
}

function tally(words) {
  const counts = { positive: 0, negative: 0, neutral: 0, unknown: 0 };
  for (const word of words) {
    counts[classify(word)] += 1;
  }
  return counts;
}

function analyze(words) {
  if (!Array.isArray(words)) {
    throw new TypeError("analyze expects an array");
  }
  const counts = tally(words);
  if (counts.positive > counts.negative) {
    return "optimistic";
  }
  if (counts.negative > counts.positive) {
    return "pessimistic";
  }
  return "balanced";
}

function report(words) {
  const counts = tally(words);
  const parts = [];
  parts.push("mood=" + analyze(words));
  parts.push("positive=" + counts.positive);
  parts.push("negative=" + counts.negative);
  parts.push("ignored=" + (counts.neutral + counts.unknown));
  return parts.join(", ");
}

function tokenize(text) {
  return text.split(/\s+/).filter((token) => token.length > 0);
}

const words = tokenize(process.argv.slice(2).join(" "));
if (words.length > 0) {
  console.log(report(words));
}

module.exports = { analyze, report, classify, tokenize };

