const GENRE_BY_SUBJECT = {
  magic: "fantasy",
  dragons: "fantasy",
  spaceships: "sci-fi",
  aliens: "sci-fi",
  murder: "mystery",
  detective: "mystery",
  ghosts: "horror",
  vampires: "horror"
};

const DEFAULT_GENRE = "fiction";

function normalizeSubject(value) {
  if (typeof value !== "string") {
    return "";
  }
  return value.trim().toLowerCase();
}

function genreOf(book) {
  if (book === null || typeof book !== "object") {
    throw new TypeError("each book must be an object");
  }
  return GENRE_BY_SUBJECT[normalizeSubject(book.subject)] || DEFAULT_GENRE;
}

function categorize(books) {
  if (!Array.isArray(books)) {
    throw new TypeError("categorize expects a list of books");
  }
  return books.map(genreOf);
}

function countGenres(books) {
  const tally = new Map();
  for (const genre of categorize(books)) {
    tally.set(genre, (tally.get(genre) || 0) + 1);
  }
  return tally;
}

function describe(book) {
  let title = book.title;
  if (normalizeSubject(title).length === 0) {
    title = "untitled";
  }
  return title + " -> " + genreOf(book);
}

function summarize(books) {
  const tally = countGenres(books);
  return [...tally.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([genre, count]) => genre + ": " + count)
    .join(", ");
}

function report(books) {
  const lines = books.map(describe);
  lines.push("summary -> " + summarize(books));
  return lines.join("\n");
}

