const SPACE = " ";
const SEVERITIES = "critical high medium low".split(SPACE);
const CUSTOMERS = "enterprise standard".split(SPACE);

function normalize(value) {
  return String(value == null ? "" : value).trim().toLowerCase();
}

function validateTicket(ticket, index) {
  if (ticket === null || typeof ticket !== "object") {
    throw new TypeError("not a ticket object at index " + index);
  }
  const severity = normalize(ticket.severity);
  const customer = normalize(ticket.customer);
  if (SEVERITIES.indexOf(severity) === -1) {
    throw new RangeError("unknown severity at index " + index);
  }
  if (CUSTOMERS.indexOf(customer) === -1) {
    throw new RangeError("unknown customer tier at index " + index);
  }
  return { severity: severity, customer: customer };
}

function classify(severity, customer) {
  const enterprise = customer === "enterprise";
  if (severity === "critical") {
    if (enterprise) {
      return "urgent";
    }
    return "high";
  }
  if (severity === "high" && enterprise) {
    return "high";
  }
  if (severity === "low" && !enterprise) {
    return "low";
  }
  return "normal";
}

function prioritize(tickets) {
  if (!Array.isArray(tickets)) {
    throw new TypeError("tickets must be an array");
  }
  return tickets.map(function (ticket, index) {
    const clean = validateTicket(ticket, index);
    return classify(clean.severity, clean.customer);
  });
}

function parseTicket(text, index) {
  const parts = String(text).split("/");
  if (parts.length !== 2) {
    throw new SyntaxError("expected severity/customer at index " + index);
  }
  return { severity: parts[0], customer: parts[1] };
}

function main() {
  const requests = [
    "critical/enterprise",
    "high/enterprise",
    "critical/standard",
    "low/standard",
    "medium/enterprise",
    "high/standard"
  ];
  const queue = requests.map(parseTicket);
  const priorities = prioritize(queue);
  priorities.forEach(function (priority, index) {
    console.log(requests[index] + " -> " + priority);
  });
}

main();

