function readField(device, name) {
  const value = device[name];
  if (typeof value !== "string") {
    return "";
  }
  return value.trim().toLowerCase();
}

function classify(state, battery) {
  if (state === "offline") {
    return "disconnected";
  }
  if (state === "active") {
    if (battery === "full") {
      return "running smoothly";
    }
    if (battery === "low") {
      return "running but needs charge";
    }
  }
  if (state === "sleep") {
    if (battery === "low") {
      return "waking up to charge";
    }
    if (battery === "full") {
      return "resting";
    }
  }
  return "unknown state";
}

function normalize(devices) {
  if (!Array.isArray(devices)) {
    throw new TypeError("normalize expects an array of device objects");
  }
  return devices.map(function (device) {
    if (device === null || typeof device !== "object") {
      return "unknown state";
    }
    const state = readField(device, "state");
    const battery = readField(device, "battery");
    return classify(state, battery);
  });
}

function parseDevice(spec) {
  const parts = String(spec).split("/");
  return { state: parts[0], battery: parts[1] };
}

function describeDevice(device) {
  const state = readField(device, "state");
  const battery = readField(device, "battery");
  return [state, battery].join("/");
}

function summarize(statuses) {
  const counts = new Map();
  statuses.forEach(function (status) {
    counts.set(status, (counts.get(status) || 0) + 1);
  });
  return Array.from(counts.entries()).sort(function (a, b) {
    return b[1] - a[1] || a[0].localeCompare(b[0]);
  });
}

function formatReport(devices, statuses) {
  const lines = ["Device status report"];
  statuses.forEach(function (status, index) {
    const position = String(index + 1);
    const label = describeDevice(devices[index]);
    lines.push([position, label, status].join(" | "));
  });
  lines.push("Totals:");
  summarize(statuses).forEach(function (entry) {
    lines.push(entry.join(": "));
  });
  return lines.join("\n");
}

function main() {
  const specs = [
    "active/full",
    "Active/ low ",
    "sleep/low",
    "sleep/full",
    "offline/low",
    "rebooting/full",
    "active/medium"
  ];
  const devices = specs.map(parseDevice);
  console.log(normalize(devices.slice(0, 1)));
  console.log(formatReport(devices, normalize(devices)));
}

main();

