const SIZES = [
  "small",
  "medium",
  "large"
];

const SEASONS = [
  "spring",
  "summer",
  "autumn",
  "winter"
];

function normalizeField(value, label) {
  if (typeof value !== "string") {
    throw new TypeError(label + " must be a string");
  }
  return value.trim().toLowerCase();
}

function normalizeEvent(event) {
  if (event === null || typeof event !== "object") {
    throw new TypeError("each event must be an object");
  }
  const size = normalizeField(event.size, "size");
  const season = normalizeField(event.season, "season");
  if (SIZES.indexOf(size) === -1) {
    throw new RangeError("unknown size: " + size);
  }
  if (SEASONS.indexOf(season) === -1) {
    throw new RangeError("unknown season: " + season);
  }
  return { size: size, season: season };
}

function venueFor(size, season) {
  switch (size) {
    case "large":
      switch (season) {
        case "summer":
          return "outdoor stadium";
        case "winter":
          return "indoor arena";
      }
      break;
    case "small":
      switch (season) {
        case "summer":
          return "garden pavilion";
        case "winter":
          return "cozy hall";
      }
      break;
    case "medium":
      if (season === "spring") {
        return "open tent";
      }
      break;
  }
  return "community center";
}

function recommend(events) {
  if (!Array.isArray(events)) {
    throw new TypeError("events must be an array");
  }
  return events.map(function (event) {
    const clean = normalizeEvent(event);
    return venueFor(clean.size, clean.season);
  });
}

function formatReport(events, venues) {
  const lines = venues.map(function (venue, index) {
    const event = normalizeEvent(events[index]);
    const label = [event.size, event.season].join(
      "/"
    );
    return label + ": " + venue;
  });
  const tally = {};
  venues.forEach(function (venue) {
    tally[venue] = (tally[venue] || 0) + 1;
  });
  Object.keys(tally).sort().forEach(function (venue) {
    lines.push(venue + " x" + tally[venue]);
  });
  return lines.join("\n");
}

function parseSchedule(text) {
  return text.split(";").map(function (entry) {
    const parts = entry.split(",");
    return { size: parts[0], season: parts[1] };
  });
}

const schedule = parseSchedule(
  "large,summer;Large,winter;small,summer;small,winter;medium,spring;medium,autumn"
);

console.log(formatReport(schedule, recommend(schedule)));

module.exports = {
  recommend: recommend,
  venueFor: venueFor,
  formatReport: formatReport,
  parseSchedule: parseSchedule
};

