const FARES = {
  senior: {
    local: "free ride",
    express: "discounted express"
  },
  student: {
    local: "student local",
    express: "student express"
  },
  adult: {
    local: "standard local",
    express: "standard express"
  }
};

const SPEC_SEPARATOR = "/";
const ARROW = " -> ";

function normalizeToken(value, field) {
  if (typeof value !== "string") {
    throw new TypeError(field + " must be a string");
  }
  const token = value.trim().toLowerCase();
  if (token === "") {
    throw new Error(field + " must not be empty");
  }
  return token;
}

function fareFor(trip) {
  if (trip === null || typeof trip !== "object") {
    throw new TypeError("each trip must be an object with rider and zone");
  }
  const rider = normalizeToken(trip.rider, "rider");
  const zone = normalizeToken(trip.zone, "zone");
  const zones = FARES[rider];
  if (zones === undefined) {
    throw new Error("unsupported rider category: " + rider);
  }
  const fare = zones[zone];
  if (fare === undefined) {
    throw new Error("unsupported zone: " + zone);
  }
  return fare;
}

function calculate(trips) {
  if (!Array.isArray(trips)) {
    throw new TypeError("calculate expects an array of trips");
  }
  return trips.map(fareFor);
}

function parseTrip(spec) {
  const parts = normalizeToken(spec, "trip spec").split(SPEC_SEPARATOR);
  if (parts.length !== 2) {
    throw new Error("trip spec must look like rider/zone");
  }
  return { rider: parts[0], zone: parts[1] };
}

function formatReport(trips, fares) {
  const lines = ["Fare summary"];
  for (let i = 0; i < trips.length; i += 1) {
    const label = trips[i].rider + SPEC_SEPARATOR + trips[i].zone;
    const numbered = String(i + 1) + ". ";
    lines.push(numbered + label + ARROW + fares[i]);
  }
  return lines.join("\n");
}

function main() {
  const specs = [
    "senior/local",
    "senior/express",
    "student/local",
    "Student/Express",
    "adult/local",
    " ADULT/express "
  ];
  const trips = specs.map(parseTrip);
  console.log(formatReport(trips, calculate(trips)));
}

main();

