  if (typeof value !== "string") {
    return "";
  }
  return value.trim().toLowerCase();
}

function statusFor(location, requirement) {
  switch (location) {
    case "warehouse":
      return "awaiting sorting";
    case "transit":
      return "on the move";
    case "facility":
      return "at local facility";
    case "destination":
      if (requirement === "mandatory") {
        return "out for delivery signature needed";
      }
      if (requirement === "none") {
        return "out for delivery dropoff";
      }
      return "tracking unavailable";
    default:
      return "tracking unavailable";
  }
}

function track(packages) {
  if (!Array.isArray(packages)) {
    throw new TypeError("track expects an array of package objects");
  }
  return packages.map(function (pkg) {
    if (pkg === null || typeof pkg !== "object") {
      return "tracking unavailable";
    }
    return statusFor(normalize(pkg.location), normalize(pkg.requirement));
  });
}

function formatReport(packages, statuses) {
  return statuses.map(function (status, index) {
    const pkg = packages[index];
    const id = normalize(pkg && pkg.id) || "unlabelled-" + index;
    const label = id.toUpperCase().padEnd(12);
    return label + " -> " + status;
  });
}

function countOutForDelivery(statuses) {
