const PRICE_TIERS = {
  white: {
    basic: "budget",
    full: "standard"
  },
  black: {
    basic: "standard",
    full: "premium"
  },
  neon: {
    basic: "premium",
    full: "luxury"
  }
};

const SPEC_SEPARATOR = "/";
const COLUMN_PAD = " ";
const ARROW = "  =>  ";

function normalizeField(value, field) {
  if (typeof value !== "string") {
    const subject = "shirt " + field;
    throw new TypeError(subject + " must be a string");
  }
  return value.trim().toLowerCase();
}

function parseShirt(spec) {
  const parts = normalizeField(spec, "spec").split(SPEC_SEPARATOR);
  if (parts.length !== 2) {
    throw new Error("expected a spec shaped like color/print, got: " + spec);
  }
  return { color: parts[0], print: parts[1] };
}

function price(shirts) {
  return shirts.map(function (shirt) {
    const color = normalizeField(shirt.color, "color");
    const printStyle = normalizeField(shirt.print, "print");
    const byPrint = PRICE_TIERS[color];
    if (!byPrint) {
      throw new Error("unsupported shirt color: " + color);
    }
    const tier = byPrint[printStyle];
    if (!tier) {
      throw new Error("unsupported print style: " + printStyle);
    }
    return tier;
  });
}

function formatReport(shirts, tiers) {
  const labels = shirts.map(function (shirt) {
    return shirt.color + " / " + shirt.print;
  });
  const width = labels.reduce(function (widest, label) {
    return Math.max(widest, label.length);
  }, 0);
  const rows = labels.map(function (label, index) {
    return label.padEnd(width, COLUMN_PAD) + ARROW + tiers[index];
  });
  return rows.join("\n");
}

function summarize(tiers) {
  const counts = new Map();
  tiers.forEach(function (tier) {
    counts.set(tier, (counts.get(tier) || 0) + 1);
  });
  const parts = [];
  counts.forEach(function (count, tier) {
    parts.push(tier + " x" + count);
  });
  return parts.join(", ");
}

function main() {
  const specs = [
    "white/basic",
    "white/full",
    "black/basic",
    "black/full",
    "neon/basic",
    "neon/full"
  ];
  const shirts = specs.map(parseShirt);
  const tiers = price(shirts);
  console.log(formatReport(shirts, tiers));
  console.log("totals: " + summarize(tiers));
}

main();

