const SHELF_LIFE = {
  CREAM_PASTRY: "refrigerate consume today",
  FRUIT_PASTRY: "room temperature consume today",
  PLAIN_BREAD: "room temperature good for three days",
  CHEESE_BREAD: "refrigerate good for two days",
  COOKIE: "room temperature good for one week",
  UNKNOWN: "ask baker"
};

const COMBINATIONS = {
  "pastry|cream": SHELF_LIFE.CREAM_PASTRY,
  "pastry|fruit": SHELF_LIFE.FRUIT_PASTRY,
  "bread|none": SHELF_LIFE.PLAIN_BREAD,
  "bread|cheese": SHELF_LIFE.CHEESE_BREAD
};

function normalize(value) {
  if (typeof value !== "string") {
    return "";
  }
  return value.trim().toLowerCase();
}

function classify(dough, filling) {
  if (dough === "cookie") {
    return SHELF_LIFE.COOKIE;
  }
  const key = dough + "|";
  const advice = COMBINATIONS[key + filling];
  return advice || SHELF_LIFE.UNKNOWN;
}

function evaluate(items) {
  if (!Array.isArray(items)) {
    throw new TypeError("evaluate expects a list of bakery items");
  }
  return items.map(function (item) {
    if (item === null || typeof item !== "object") {
      return SHELF_LIFE.UNKNOWN;
    }
    return classify(normalize(item.dough), normalize(item.filling));
  });
}

function describe(item, advice) {
  const dough = normalize(item.dough) || "unspecified dough";
  const filling = normalize(item.filling) || "unspecified filling";
  let line = dough + " with ";
  line += filling;
  line += ": ";
  return line + advice;
}

function report(items) {
  const advice = evaluate(items);
  const lines = items.map(function (item, index) {
    return describe(item, advice[index]);
  });
  return lines.join("\n");
}

const tray = [
  {
    dough: "Pastry",
    filling: "cream"
  },
  {
    dough: "bread",
    filling: "cheese"
  },
  {
    dough: "filo",
    filling: "spinach"
  }
];

console.log(report(tray));

module.exports = { evaluate, report };

