const REWARD_TABLE = {
  platinum: {
    high: "free international flight",
    low: "free domestic flight",
  },
  gold: {
    high: "free hotel stay",
    low: "free lounge access",
  },
  silver: {
    high: "free checked bag",
  },
};

const DEFAULT_REWARD = "no current reward";
const UNKNOWN_FIELD = "unknown";

function normalizeField(value) {
  if (value === null || value === undefined) {
    return "";
  }
  return String(value).trim().toLowerCase();
}

function reward(customers) {
  if (!Array.isArray(customers)) {
    throw new TypeError("reward expects an array of customer objects");
  }
  return customers.map((customer) => {
    if (customer === null || typeof customer !== "object") {
      throw new TypeError("every customer entry must be an object");
    }
    const tier = REWARD_TABLE[normalizeField(customer.status)];
    if (!tier) {
      return DEFAULT_REWARD;
    }
    return tier[normalizeField(customer.volume)] || DEFAULT_REWARD;
  });
}

function parseCustomer(record) {
  const fields = normalizeField(record).split(/\s+/);
  return { status: fields[0], volume: fields[1] };
}

function describeCustomer(customer, index) {
  const parts = [];
  parts.push("Customer " + (index + 1));
  parts.push(normalizeField(customer.status) || UNKNOWN_FIELD);
  parts.push(normalizeField(customer.volume) || UNKNOWN_FIELD);
  return parts.join(" | ");
}

function formatRewardReport(customers) {
  const rewards = reward(customers);
  const lines = rewards.map(
    (earned, index) => describeCustomer(customers[index], index) + " -> " + earned
  );
  return lines.join("\n");
}

function summarizeRewards(customers) {
  const counts = new Map();
  for (const earned of reward(customers)) {
    counts.set(earned, (counts.get(earned) || 0) + 1);
  }
  const entries = [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  const parts = entries.map(([earned, total]) => earned + " x" + total);
  return parts.join("; ");
}

function main() {
  const records = [
    "platinum high",
    "platinum low",
    "gold high",
    "gold low",
    "silver high",
    "silver low",
    "bronze high",
  ];
  const customers = records.map(parseCustomer);
  console.log(reward([parseCustomer("platinum high")]));
  console.log(formatRewardReport(customers));
  console.log("Totals: " + summarizeRewards(customers));
}

if (require.main === module) {
  main();
}

module.exports = { reward, parseCustomer, formatRewardReport, summarizeRewards };

