const KEY_SEPARATOR = ":";

const REPAIRS = {
  "refrigerator:cooling":
    "compressor repair needed",
  "refrigerator:leaking":
    "seal replacement needed",
  "washer:draining":
    "pump repair needed",
  "washer:spinning":
    "belt replacement needed",
  "oven:heating":
    "element repair needed"
};

function normalize(value) {
  if (typeof value !== "string") {
    return "";
  }
  return value.trim().toLowerCase();
}

function repairKey(appliance) {
  const type = normalize(appliance.type);
  const issue = normalize(appliance.issue);
  return type + KEY_SEPARATOR + issue;
}

function estimate(appliances) {
  if (!Array.isArray(appliances)) {
    throw new TypeError("estimate expects an array of appliance objects");
  }
  return appliances.map(function (appliance) {
    if (appliance === null || typeof appliance !== "object") {
      return FALLBACK;
    }
    const key = repairKey(appliance);
    return Object.prototype.hasOwnProperty.call(REPAIRS, key) ? REPAIRS[key] : FALLBACK;
  });
}

function describe(appliance) {
  const type = normalize(appliance && appliance.type) || "unknown appliance";
  const issue = normalize(appliance && appliance.issue) || "unspecified issue";
  const opening = type + " (";
  return opening + issue + ")";
}

function report(appliances) {
  const estimates = estimate(appliances);
  const lines = estimates.map(function (text, index) {
    return describe(appliances[index]) + " -> " + text;
  });
  const diagnostics = estimates.filter(function (text) {
    return text === FALLBACK;
  }).length;
  lines.push("known repairs: " + (estimates.length - diagnostics));
  lines.push("diagnostics required: " + diagnostics);
  return lines.join("\n");
}

function main() {
