function normalizeItem(item) {
  const category = String(item.category || "").trim().toLowerCase();
  const storage = String(item.storage || "").trim().toLowerCase();
  return { category, storage };
}

function parseItem(spec) {
  const parts = String(spec).trim().split(/\s+/);
  return { category: parts[0], storage: parts[1] };
}

function locateOne(item) {
  const { category, storage } = normalizeItem(item);
  if (category === "dairy") {
    if (storage === "cold") {
      return "aisle four refrigerated";
    }
  } else if (category === "produce") {
    if (storage === "cold") {
      return "front of store misting display";
    }
    if (storage === "ambient") {
      return "front of store bins";
    }
  } else if (category === "meat") {
    if (storage === "frozen") {
      return "aisle five frozen";
    }
  } else if (category === "bakery") {
    if (storage === "ambient") {
      return "aisle one fresh";
    }
  }
  return "ask store associate";
}

function locate(items) {
  if (!Array.isArray(items)) {
    throw new TypeError("locate expects a list of grocery item objects");
  }
  return items.map(locateOne);
}

function describeItem(item) {
  const { category, storage } = normalizeItem(item);
  const name = category || "unknown";
  const kept = storage || "unspecified";
  return [name, kept].join(" / ");
}

function groupByLocation(items) {
  const groups = new Map();
  items.forEach((item) => {
    const where = locateOne(item);
    if (!groups.has(where)) {
      groups.set(where, []);
    }
    groups.get(where).push(describeItem(item));
  });
  return groups;
}

function formatReport(items) {
  const lines = [];
  groupByLocation(items).forEach((members, where) => {
    const listed = members.join(", ");
    lines.push(where + ": " + listed);
  });
  return lines.join("\n");
}

function main() {
  const specs = [
    "dairy cold",
    "Produce ambient",
    "produce cold",
    "meat frozen",
    "bakery ambient",
    "cleaning ambient"
  ];
  const cart = specs.map(parseItem);
  console.log(locate(cart).join(" | "));
  console.log(formatReport(cart));
}

main();

module.exports = { locate, locateOne, parseItem, groupByLocation, formatReport };

