const FAMILIES = {
  flute: "woodwind",
  clarinet: "woodwind",
  oboe: "woodwind",
  trumpet: "brass",
  trombone: "brass",
  tuba: "brass",
  violin: "string",
  cello: "string",
  harp: "string",
  snare: "percussion",
  timpani: "percussion",
  cymbal: "percussion"
};

function normalize(name) {
  if (typeof name !== "string") {
    return "";
  }
  return name.trim().toLowerCase();
}

function classifyOne(name) {
  const key = normalize(name);
  return FAMILIES[key] || "unknown";
}

function classify(instruments) {
  if (!Array.isArray(instruments)) {
    throw new TypeError("classify expects an array of instrument names");
  }
  return instruments.map(classifyOne);
}

function countByFamily(instruments) {
  const tally = {};
  for (const family of classify(instruments)) {
    tally[family] = (tally[family] || 0) + 1;
  }
  return tally;
}

function summarize(tally) {
  const parts = Object.keys(tally)
    .sort()
    .map(function (family) {
      return family + "=" + tally[family];
    });
  if (parts.length === 0) {
    return "none";
  }
  return parts.join(", ");
}

function formatReport(instruments) {
  const families = classify(instruments);
  const lines = instruments.map(function (name, index) {
    const label = normalize(name) || "(blank)";
    return label + " -> " + families[index];
  });
  lines.push("summary: " + summarize(countByFamily(instruments)));
  return lines.join("\n");
}

