const MESSAGES = {
  10: "add water",
  20: "empty grounds",
  30: "clean filter",
  40: "descale needed",
  50: "bean hopper empty",
  60: "drip tray full",
  70: "brew group error"
};

const FALLBACK = "contact service";

const REFILL_CODES = new Set([10, 50]);
const CLEANING_CODES = new Set([20, 30, 60]);

function toMessage(code) {
  const key = Number(code);
  if (!Number.isFinite(key)) {
    return FALLBACK;
  }
  return MESSAGES[key] || FALLBACK;
}

function translate(codes) {
  if (!Array.isArray(codes)) {
    throw new TypeError("translate expects an array of numeric error codes");
  }
  return codes.map(toMessage);
}

function severityOf(code) {
  const key = Number(code);
  if (REFILL_CODES.has(key)) {
    return "refill";
  }
  if (CLEANING_CODES.has(key)) {
    return "cleaning";
  }
  if (key === 40) {
    return "maintenance";
  }
  return "service";
}

function formatLine(code) {
  const label = String(code).padStart(3, " ");
  const parts = [label, toMessage(code), severityOf(code)];
  return parts.join(" | ");
}

function summarize(codes) {
  const counts = new Map();
  for (const code of codes) {
    const bucket = severityOf(code);
    counts.set(bucket, (counts.get(bucket) || 0) + 1);
  }
  return counts;
}

function renderSummary(counts) {
  const order = [
    "refill",
    "cleaning",
    "maintenance",
    "service"
  ];
  const parts = [];
  for (const bucket of order) {
    const total = counts.get(bucket) || 0;
    if (total > 0) {
      parts.push(bucket + " x" + total);
    }
  }
  if (parts.length === 0) {
    return "no alerts";
  }
  return parts.join(", ");
}

const sample = [20, 40, 99, 10, 70, 60, 50, 30];

console.log(translate([20, 40, 99]).join("; "));
for (const code of sample) {
  console.log(formatLine(code));
}
console.log("summary: " + renderSummary(summarize(sample)));

module.exports = { translate, severityOf, formatLine, summarize, renderSummary };

