const OPEN_GAME = "open game";
const CLOSED_GAME = "closed game";
const SICILIAN = "sicilian defense";
const FRENCH = "french defense";
const INDIAN = "indian defense";
const CARO_KANN = "caro kann";
const BIRD = "bird opening";
const STANDARD_PLAY = "standard play";

const TABLE = new Map();
TABLE.set("e4 e5", OPEN_GAME);
TABLE.set("d4 d5", CLOSED_GAME);
TABLE.set("e4 c5", SICILIAN);
TABLE.set("e4 e6", FRENCH);
TABLE.set("d4 Nf6", INDIAN);
TABLE.set("e4 c6", CARO_KANN);
TABLE.set("f4 d5", BIRD);

function normalizeMove(move) {
  const lower = move.toLowerCase();
  if (/^[nbrqk]/.test(lower)) {
    return lower.charAt(0).toUpperCase() + lower.slice(1);
  }
  return lower;
}

function normalize(entry) {
  if (typeof entry !== "string") {
    throw new TypeError("each opening must be given as a string of two moves");
  }
  const moves = entry.trim().split(/\s+/);
  if (moves.length !== 2) {
    throw new Error("expected exactly two moves but got: " + entry);
  }
  return moves.map(normalizeMove).join(" ");
}

function nameFor(entry) {
  const key = normalize(entry);
  if (TABLE.has(key)) {
    return TABLE.get(key);
  }
  return STANDARD_PLAY;
}

function identify(openings) {
  if (!Array.isArray(openings)) {
    throw new TypeError("identify expects a list of first move pairs");
  }
  return openings.map(nameFor);
}

function report(openings) {
  const names = identify(openings);
  const lines = openings.map(function (entry, index) {
    return entry.trim() + " => " + names[index];
  });
  return lines.join("\n");
}

function main() {
  const games = [
    "e4 e5",
    "d4 Nf6",
    "a3 a6",
    "E4 C5",
    " f4   d5 ",
    "e4 e6",
    "d4 d5",
    "e4 c6"
  ];
  console.log(report(games));
  try {
    identify(["e4"]);
  } catch (err) {
    console.log("rejected input: " + err.message);
  }
}

main();

module.exports = { identify, report, nameFor };

