const DEFAULT_ADVICE = "consult packaging";

const STEEP_TIMES = {
  white: "two minutes at eighty degrees",
  green: "three minutes at eighty degrees",
  oolong: "four minutes at ninety degrees",
  black: "five minutes at boiling",
  herbal: "seven minutes at boiling",
  rooibos: "six minutes at boiling",
  matcha: "whisking not steeping"
};

const SUFFIX = " tea";

const SEPARATOR = "  ";

const PAD = " ";

function normalize(tea) {
  const cleaned = tea.toLowerCase().trim().replace(/\s+/g, PAD);
  if (cleaned.endsWith(SUFFIX)) {
    return cleaned.slice(0, cleaned.length - SUFFIX.length);
  }
  return cleaned;
}

function instructionFor(tea) {
  if (typeof tea !== "string") {
    throw new TypeError("tea type must be a string, received " + typeof tea);
  }
  const key = normalize(tea);
  if (Object.prototype.hasOwnProperty.call(STEEP_TIMES, key)) {
    return STEEP_TIMES[key];
  }
  return DEFAULT_ADVICE;
}

function steep(teas) {
  if (!Array.isArray(teas)) {
    throw new TypeError("steep expects an array of tea types");
  }
  return teas.map(instructionFor);
}

function formatGuide(teas) {
  const instructions = steep(teas);
  const width = teas.reduce((max, tea) => Math.max(max, tea.length), 0);
  const lines = teas.map(function (tea, index) {
    return tea.padEnd(width, PAD) + SEPARATOR + instructions[index];
  });
  return lines.join("\n");
}

function unknownTeas(teas) {
  return teas.filter((tea) => instructionFor(tea) === DEFAULT_ADVICE);
}

function main() {
  const order = [
    "green tea",
    "matcha",
    "chai",
    "Oolong Tea",
    "  black tea  ",
    "rooibos",
    "herbal tea",
    "white tea"
  ];
  console.log("Steeping guide");
  console.log(formatGuide(order));
  const puzzling = unknownTeas(order);
  if (puzzling.length > 0) {
    const names = puzzling.join(", ");
    console.log("No recipe on file for: " + names);
  }
}

main();

module.exports = { steep, instructionFor, formatGuide, unknownTeas };

