  return DEFAULT_ADVICE;
}

function steep(teas) {
  if (!Array.isArray(teas)) {
    throw new TypeError('steep expects an array of tea types');
  }
  return teas.map(instructionFor);
}

function formatGuide(teas) {
  const instructions = steep(teas);
  const width = teas.reduce((max, tea) => Math.max(max, tea.length), 0);
  const lines = teas.map(function (tea, index) {
    return tea.padEnd(width, PAD) + SEPARATOR + instructions[index];
  });
  return lines.join('\n');
}

function unknownTeas(teas) {
  return teas.filter((tea) => instructionFor(tea) === DEFAULT_ADVICE);
}

function main() {
  const order = [
    'green tea',
    'matcha',
    'chai',
    'Oolong Tea',
    '  black tea  ',
    'rooibos',
    'herbal tea',
    'white tea'
  ];
  console.log('Steeping guide');
  console.log(formatGuide(order));
  const puzzling = unknownTeas(order);
  if (puzzling.length > 0) {
    const names = puzzling.join(', ');
    console.log('No recipe on file for: ' + names);
  }
}

main();

module.exports = { steep, instructionFor, formatGuide, unknownTeas };

