const BATTERY_USES = {
  "double a":
    "tv remotes",
  "triple a":
    "small toys",
  "c":
    "medium flashlights",
  "d":
    "large radios",
  "nine volt":
    "smoke alarms",
  "cr twenty thirty two":
    "watches",
  "lr forty four":
    "laser pointers"
};

const FALLBACK_USE = "specialized electronics";

const ALIASES = {
  "aa":
    "double a",
  "aaa":
    "triple a",
  "9v":
    "nine volt",
  "cr2032":
    "cr twenty thirty two",
  "lr44":
    "lr forty four"
};

function normalize(size) {
  if (typeof size !== "string") {
    throw new TypeError("battery size must be a string");
  }
  const cleaned = size.trim().toLowerCase().replace(/[\s_-]+/g, " ");
  const compact = cleaned.replace(/ /g, "");
  if (Object.prototype.hasOwnProperty.call(ALIASES, compact)) {
    return ALIASES[compact];
  }
  if (Object.prototype.hasOwnProperty.call(ALIASES, cleaned)) {
    return ALIASES[cleaned];
  }
  return cleaned;
}

function usage(batteries) {
  if (!Array.isArray(batteries)) {
    throw new TypeError("usage expects a list of battery sizes");
  }
  return batteries.map(function (size) {
    const key = normalize(size);
    if (Object.prototype.hasOwnProperty.call(BATTERY_USES, key)) {
      return BATTERY_USES[key];
    }
    return FALLBACK_USE;
  });
}

function describe(batteries) {
  const uses = usage(batteries);
  return batteries.map(function (size, index) {
    return size + " -> " + uses[index];
  }).join("\n");
}

function main() {
  const stock = [
    "double a",
    "nine volt",
    "a23",
    "AAA",
    "cr2032",
    "LR-44",
    "d"
  ];
  console.log(describe(stock));
}

main();

