const ROLES = {
  aircraftCarrier: "fleet air support",
  destroyer: "anti submarine warfare",
  cruiser: "multi role combat",
  frigate: "escort duties",
  submarine: "stealth operations",
  minesweeper: "hazard clearance",
  patrolBoat: "coastal defense",
  amphibiousAssault: "troop transport"
};

const DEFAULT_ROLE = "auxiliary support";

function splitWords(name) {
  if (typeof name !== "string") {
    throw new TypeError("every ship classification must be a string");
  }
  return name.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
}

function normalizeKey(name) {
  const words = splitWords(name);
  const camel = words.map(function (word, index) {
    if (index === 0) {
      return word;
    }
    return word.charAt(0).toUpperCase() + word.slice(1);
  });
  return camel.join("");
}

function displayName(name) {
  const words = splitWords(name);
  if (words.length === 0) {
    return "unclassified";
  }
  return words.join(" ");
}

function role(ships) {
  if (!Array.isArray(ships)) {
    throw new TypeError("role expects an array of ship classifications");
  }
  return ships.map(function (ship) {
    const key = normalizeKey(ship);
    if (Object.prototype.hasOwnProperty.call(ROLES, key)) {
      return ROLES[key];
    }
    return DEFAULT_ROLE;
  });
}

function formatFleetReport(ships) {
  const roles = role(ships);
  const labels = ships.map(displayName);
  const width = labels.reduce(function (max, label) {
    return Math.max(max, label.length);
  }, 0);
  const lines = labels.map(function (label, index) {
    return label.padEnd(width) + " -> " + roles[index];
  });
  return lines.join("\n");
}

function shipCount(count) {
  if (count === 1) {
    return count + " ship";
  }
  return count + " ships";
}

function formatRoleSummary(ships) {
  const tally = new Map();
  role(ships).forEach(function (assignment) {
    tally.set(assignment, (tally.get(assignment) || 0) + 1);
  });
  const entries = Array.from(tally.entries()).sort(function (a, b) {
    return b[1] - a[1] || a[0].localeCompare(b[0]);
  });
  return entries.map(function (entry) {
    return entry[0] + ": " + shipCount(entry[1]);
  }).join("\n");
}

const fleet = [
  "Aircraft Carrier",
  "destroyer",
  "cruiser",
  "frigate",
  "submarine",
  "mine-sweeper",
  "patrol boat",
  "amphibious assault",
  "tugboat",
  "hospital ship"
];

console.log("Fleet role assignments");
console.log(formatFleetReport(fleet));
console.log("\nRole distribution");
console.log(formatRoleSummary(fleet));

