const COLLECTIVE_NOUNS = {
  lion: "pride",
  crow: "murder",
  owl: "parliament",
  fish: "school",
  wolf: "pack",
  bee: "swarm",
  ant: "colony",
  sheep: "flock",
  cow: "herd",
  elephant: "parade",
  rhino: "crash"
};

const DEFAULT_NOUN = "group";

const IRREGULAR_SINGULARS = {
  wolves: "wolf",
  mice: "mouse",
  geese: "goose",
  oxen: "ox"
};

const ARTICLE = "a ";
const CONNECTOR = " of ";
const TALLY_SEPARATOR = ": ";

function normalize(name) {
  if (typeof name !== "string") {
    throw new TypeError("animal names must be strings");
  }
  const cleaned = name.trim().toLowerCase();
  if (IRREGULAR_SINGULARS[cleaned]) {
    return IRREGULAR_SINGULARS[cleaned];
  }
  if (cleaned.endsWith("es") && COLLECTIVE_NOUNS[cleaned.slice(0, -2)]) {
    return cleaned.slice(0, -2);
  }
  if (cleaned.endsWith("s") && COLLECTIVE_NOUNS[cleaned.slice(0, -1)]) {
    return cleaned.slice(0, -1);
  }
  return cleaned;
}

function collectiveNoun(animal) {
  const key = normalize(animal);
  return COLLECTIVE_NOUNS[key] || DEFAULT_NOUN;
}

function group(animals) {
  if (!Array.isArray(animals)) {
    throw new TypeError("group expects an array of animal names");
  }
  return animals.map(collectiveNoun);
}

function formatReport(animals) {
  const nouns = group(animals);
  const lines = animals.map(function (animal, index) {
    const label = normalize(animal);
    return ARTICLE + nouns[index] + CONNECTOR + label;
  });
  return lines.join("\n");
}

function countByNoun(animals) {
  return group(animals).reduce(function (tally, noun) {
    tally[noun] = (tally[noun] || 0) + 1;
    return tally;
  }, {});
}

const sample = [
  "crow",
  "bee",
  "dog",
  "Wolves",
  "elephant",
  "rhino",
  "sheep",
  "owl"
];

console.log(formatReport(sample));

const tally = countByNoun(sample);
Object.keys(tally).sort().forEach(function (noun) {
  console.log(noun + TALLY_SEPARATOR + tally[noun]);
});

module.exports = { group, collectiveNoun, formatReport, countByNoun };

