const BELT_SCALE = [
  { minMonths: 24, color: "black belt" },
  { minMonths: 21, color: "red belt" },
  { minMonths: 18, color: "brown belt" },
  { minMonths: 15, color: "purple belt" },
  { minMonths: 12, color: "blue belt" },
  { minMonths: 9, color: "green belt" },
  { minMonths: 6, color: "orange belt" },
  { minMonths: 3, color: "yellow belt" },
  { minMonths: 0, color: "white belt" }
];

const DISQUALIFIED = "disqualified";

function beltFor(months) {
  if (!Number.isFinite(months)) {
    throw new TypeError("each duration must be a finite number of months");
  }
  if (months < 0) {
    return DISQUALIFIED;
  }
  const grade = BELT_SCALE.find(entry => months >= entry.minMonths);
  return grade.color;
}

function rank(months) {
  if (!Array.isArray(months)) {
    throw new TypeError("rank expects an array of training durations");
  }
  return months.map(beltFor);
}

function monthLabel(count) {
  if (count === 1) {
    return "1 month";
  }
  return count + " months";
}

function formatStudent(index, months, belt) {
  const who = "student " + (index + 1);
  const trained = monthLabel(months) + " trained";
  return [who, trained, belt].join(" | ");
}

function report(months) {
  const belts = rank(months);
  return belts.map((belt, index) => formatStudent(index, months[index], belt));
}

function summarize(months) {
  const tally = new Map();
  for (const belt of rank(months)) {
    tally.set(belt, (tally.get(belt) || 0) + 1);
  }
  const order = BELT_SCALE.map(entry => entry.color).concat([DISQUALIFIED]);
  const parts = order
    .filter(belt => tally.has(belt))
    .map(belt => tally.get(belt) + " x " + belt);
  return parts.join(", ");
}

function main() {
  const durations = [1, 13, -5, 0, 7, 24, 16, 22, 10, 19, 3];
  console.log(JSON.stringify(rank([1, 13, -5])));
  for (const line of report(durations)) {
    console.log(line);
  }
  console.log("dojo summary: " + summarize(durations));
}

main();

module.exports = { rank, beltFor, report, summarize };

