    case "perfect bound":
      return "flat glued spine";
    case "leather bound":
      return "premium hide cover";
    case "board book":
      return "thick cardboard pages";
    default:
      return FALLBACK;
  }
}

function describe(bindings) {
  if (!Array.isArray(bindings)) {
    throw new TypeError("bindings must be an array");
  }
  return bindings.map(describeOne);
