"use strict";

const CLASS_A = "class a water";
const CLASS_B = "class b foam";
const CLASS_C = "class c carbon dioxide";
const CLASS_D = "class d dry powder";
const CLASS_K = "class k wet chemical";
const FALLBACK = "evacuate immediately";
const HEADER = "hazard";
const SEPARATOR = " | ";

const HAZARD_RULES = new Map([
  ["wood", CLASS_A],
  ["paper", CLASS_A],
  ["flammable liquid", CLASS_B],
  ["gasoline", CLASS_B],
  ["electrical", CLASS_C],
  ["wiring", CLASS_C],
  ["combustible metal", CLASS_D],
  ["magnesium", CLASS_D],
  ["cooking oil", CLASS_K],
  ["deep fryer", CLASS_K]
]);

function normalize(material) {
  if (typeof material !== "string") {
    throw new TypeError("each material must be described by a string");
  }
  return material.trim().toLowerCase().replace(/\s+/g, " ");
}

function classify(material) {
  const hazard = normalize(material);
  for (const [keyword, extinguisher] of HAZARD_RULES) {
    if (hazard.includes(keyword)) {
      return extinguisher;
    }
  }
  return FALLBACK;
}

function extinguish(materials) {
  if (!Array.isArray(materials)) {
    throw new TypeError("extinguish expects a list of materials");
  }
  return materials.map(classify);
}

function formatReport(materials) {
  const responses = extinguish(materials);
  const width = materials.reduce((max, item) => Math.max(max, normalize(item).length), HEADER.length);
  const lines = [HEADER.padEnd(width) + SEPARATOR + "response"];
  lines.push("-".repeat(width + SEPARATOR.length + FALLBACK.length));
  materials.forEach((item, index) => {
    lines.push(normalize(item).padEnd(width) + SEPARATOR + responses[index]);
  });
  return lines.join("\n");
}

function countEvacuations(materials) {
  return extinguish(materials).filter((response) => response === FALLBACK).length;
}

const hazards = [
  "gasoline",
  "wiring",
  "plastic",
  "Deep Fryer",
  "magnesium shavings",
  "  old newspaper  ",
  "flammable liquids"
];

console.log(formatReport(hazards));
console.log("hazards needing evacuation: " + countEvacuations(hazards));

module.exports = { extinguish, classify, formatReport, countEvacuations };

