const PHILADELPHIA = "philadelphia";
const DENVER = "denver";
const SAN_FRANCISCO = "san francisco";
const WEST_POINT = "west point";
const NEW_ORLEANS = "new orleans";
const CARSON_CITY = "carson city";
const CHARLOTTE = "charlotte";
const BLANK_MARK = "philadelphia standard";
const UNKNOWN_MARK = "counterfeit or foreign";
const BLANK_LABEL = "(blank)";
const ARROW = " -> ";

const MINT_MARKS = new Map();
MINT_MARKS.set("p", PHILADELPHIA);
MINT_MARKS.set("d", DENVER);
MINT_MARKS.set("s", SAN_FRANCISCO);
MINT_MARKS.set("w", WEST_POINT);
MINT_MARKS.set("o", NEW_ORLEANS);
MINT_MARKS.set("cc", CARSON_CITY);
MINT_MARKS.set("c", CHARLOTTE);

function normalize(mark) {
  if (mark === null || mark === undefined) {
    return "";
  }
  return String(mark).trim().toLowerCase();
}

function locateOne(mark) {
  const key = normalize(mark);
  if (key.length === 0) {
    return BLANK_MARK;
  }
  if (MINT_MARKS.has(key)) {
    return MINT_MARKS.get(key);
  }
  return UNKNOWN_MARK;
}

function locate(marks) {
  if (!Array.isArray(marks)) {
    throw new TypeError("locate expects a list of mint mark letters");
  }
  return marks.map(locateOne);
}

function formatRow(mark, city) {
  const key = normalize(mark);
  const shown = key.length === 0 ? BLANK_LABEL : key;
  return shown.padEnd(8) + ARROW + city;
}

function report(marks) {
  const cities = locate(marks);
  const lines = marks.map((mark, index) => formatRow(mark, cities[index]));
  return lines.join("\n");
}

function tally(marks) {
  const counts = new Map();
  for (const city of locate(marks)) {
    counts.set(city, (counts.get(city) || 0) + 1);
  }
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([city, count]) => count + " x " + city)
    .join(", ");
}

function main() {
  const sample = [
    "d",
    "w",
    "x"
  ];
  console.log(locate(sample).join(", "));
  const batch = [
    "CC",
    " s ",
    "",
    "o",
    "c",
    "p",
    "q"
  ];
  console.log(report(batch));
  console.log(tally(batch));
}

main();

module.exports = { locate, locateOne, report, tally };

