const SHOE_BY_ACTIVITY = {
  running: 'cushioned sneakers',
  hiking: 'ankle support boots',
  weightlifting: 'flat rigid shoes',
  soccer: 'spiked cleats',
  tennis: 'lateral support court shoes',
  swimming: 'waterproof sandals',
  ballet: 'soft pointe shoes',
  snowboarding: 'stiff thermal boots'
};

const DEFAULT_SHOE = 'casual trainers';

const ALIASES = {
  jogging: 'running',
  trekking: 'hiking',
  lifting: 'weightlifting',
  football: 'soccer',
  snowboard: 'snowboarding'
};

function normalize(activity) {
  if (typeof activity !== 'string') {
    throw new TypeError('each activity must be a string');
  }
  const key = activity.trim().toLowerCase().replace(/\s+/g, ' ');
  return ALIASES[key] || key;
}

function footwear(activities) {
  if (!Array.isArray(activities)) {
    throw new TypeError('activities must be an array');
  }
  return activities.map(function (activity) {
    const key = normalize(activity);
    if (Object.prototype.hasOwnProperty.call(SHOE_BY_ACTIVITY, key)) {
      return SHOE_BY_ACTIVITY[key];
    }
    return DEFAULT_SHOE;
  });
}

function pluralize(count) {
  if (count === 1) {
    return 'pair';
  }
  return 'pairs';
}

function packingList(activities) {
  const counts = new Map();
  footwear(activities).forEach(function (shoe) {
    counts.set(shoe, (counts.get(shoe) || 0) + 1);
  });
  const items = [];
  counts.forEach(function (count, shoe) {
    items.push(`${count} ${pluralize(count)} of ${shoe}`);
  });
  return items;
}

function report(name, activities) {
  const shoes = footwear(activities);
  const lines = [`${name} needs:`];
  activities.forEach(function (activity, index) {
    lines.push(`  ${activity} -> ${shoes[index]}`);
  });
  const suitcase = packingList(activities).join('; ');
  lines.push(`Suitcase: ${suitcase}`);
  return lines.join('\n');
}

const athlete = [
  'hiking',
  'soccer',
  'walking',
  'Swimming',
  'football',
  'snowboard'
];

console.log(report('Dana', athlete));

module.exports = { footwear, packingList, report };

