]);

const DEFAULT_MEANING = "natural beauty";

function normalizeName(name) {
  if (typeof name !== "string") {
    throw new TypeError("every flower type must be given as a string");
  }
  const cleaned = name.trim().toLowerCase().replace(/\s+/g, " ");
  if (cleaned.length === 0) {
    throw new Error("a flower type must not be blank");
  }
  return cleaned;
}

function meaning(flowers) {
  if (!Array.isArray(flowers)) {
    throw new TypeError("meaning() expects a list of flower types");
  }
  return flowers.map(function (flower) {
    const key = normalizeName(flower);
    return MEANINGS.has(key) ? MEANINGS.get(key) : DEFAULT_MEANING;
  });
}

function describe(flowers) {
  const senses = meaning(flowers);
  return flowers.map(function (flower, index) {
