const ZIGZAG = "zigzag stitch";
const OVERLOCK = "overlock stitch";
const BLIND_HEM = "blind hem stitch";
const STRAIGHT = "straight stitch";
const SCALLOP = "scallop stitch";
const SADDLE = "saddle stitch";
const BASTING = "basting stitch";
const BUTTONHOLE = "buttonhole stitch";
const FALLBACK = "standard straight stitch";
const SPECIAL_FOOT_NOTE = " (fit the special presser foot)";
const INDENT = "  ";
const ARROW = " -> ";
const EMPTY = "";

const STITCH_BY_GOAL = {
  "stretchy knits": ZIGZAG,
  "finishing raw edges": OVERLOCK,
  "hemming pants": BLIND_HEM,
  "quilting layers": STRAIGHT,
  "decorative borders": SCALLOP,
  "joining thick leather": SADDLE,
  "gathering fabric": BASTING,
  "applique work": BUTTONHOLE
};

function normalizeGoal(goal) {
  if (typeof goal !== "string") {
    throw new TypeError("each fabric handling goal must be a string");
  }
  const words = goal.toLowerCase().split(" ").filter(function (word) {
    return word.length > 0;
  });
  return words.join(" ");
}

function stitch(fabrics) {
  if (!Array.isArray(fabrics)) {
    throw new TypeError("fabrics must be an array of goals");
  }
  return fabrics.map(function (goal) {
    const key = normalizeGoal(goal);
    return Object.prototype.hasOwnProperty.call(STITCH_BY_GOAL, key)
      ? STITCH_BY_GOAL[key]
      : FALLBACK;
  });
}

function needsSpecialFoot(stitchName) {
  return stitchName === BLIND_HEM || stitchName === BUTTONHOLE;
}

function planProject(name, fabrics) {
  const stitches = stitch(fabrics);
  const lines = ["Project: " + name];
  let unknowns = 0;
  for (let i = 0; i < fabrics.length; i += 1) {
    const chosen = stitches[i];
    const note = needsSpecialFoot(chosen) ? SPECIAL_FOOT_NOTE : EMPTY;
    lines.push(INDENT + normalizeGoal(fabrics[i]) + ARROW + chosen + note);
    if (chosen === FALLBACK) {
      unknowns += 1;
    }
  }
  if (unknowns > 0) {
    lines.push(INDENT + unknowns + " goal(s) fell back to the default setting");
  }
  return lines.join("\n");
}

const jacketGoals = [
  "stretchy knits",
  "Hemming Pants",
  "finishing raw edges",
  "joining thick leather",
  "patching"
];

const quiltGoals = [
  "quilting layers",
  "decorative borders",
  "gathering fabric"
];

console.log(planProject("Summer jacket refit", jacketGoals));
console.log(planProject("Quilt top", quiltGoals));
console.log(stitch(jacketGoals).join(", "));

