function lensFor(subject) {
  switch (subject) {
    case "landscape":
      return "wide angle fourteen millimeter";
    case "architecture":
      return "tilt shift twenty four millimeter";
    case "street photography":
      return "prime thirty five millimeter";
    case "portrait":
      return "prime eighty five millimeter";
    case "sports":
      return "telephoto two hundred millimeter";
    case "wildlife":
      return "super telephoto four hundred millimeter";
    case "macro":
      return "dedicated one hundred millimeter";
    case "astrophotography":
      return "ultra wide fourteen millimeter";
    default:
      return "standard fifty millimeter";
  }
}

function normalize(subject) {
  if (typeof subject !== "string") {
    throw new TypeError("each subject must be a string");
  }
  return subject.trim().toLowerCase().replace(/\s+/g, " ");
}

function lens(subjects) {
  if (!Array.isArray(subjects)) {
    throw new TypeError("subjects must be an array");
  }
  return subjects.map(function (subject) {
    return lensFor(normalize(subject));
  });
}

function packingList(subjects) {
  const counts = new Map();
  lens(subjects).forEach(function (focal) {
    counts.set(focal, (counts.get(focal) || 0) + 1);
  });
  return Array.from(counts.entries()).map(function (entry) {
    return entry[0] + " x" + entry[1];
  });
}

function shootReport(title, subjects) {
  const recommendations = lens(subjects);
  const lines = [title.toUpperCase()];
  subjects.forEach(function (subject, index) {
    lines.push([subject, recommendations[index]].join(" -> "));
  });
  const bag = packingList(subjects).join(", ");
  lines.push("Bag: " + bag);
  return lines.join("\n");
}

