const BUTT_JOINT = "butt joint";
const DOVETAIL_JOINT = "dovetail joint";
const SCARF_JOINT = "scarf joint";
const EDGE_JOINT = "edge joint";
const MITER_JOINT = "miter joint";
const MORTISE_TENON_JOINT = "mortise and tenon joint";
const DADO_JOINT = "dado joint";
const RAIL_AND_STILE_JOINT = "rail and stile joint";
const SIMPLE_SCREW_JOINT = "simple screw joint";

function normalizePurpose(purpose) {
  if (typeof purpose !== "string") {
    throw new TypeError("each purpose must be a string");
  }
  return purpose.trim().toLowerCase().replace(/\s+/g, " ");
}

function lookupJoint(key) {
  switch (key) {
    case "framing a box":
      return BUTT_JOINT;
    case "making a drawer":
      return DOVETAIL_JOINT;
    case "extending a board":
      return SCARF_JOINT;
    case "joining tabletop panels":
      return EDGE_JOINT;
    case "right angle corners":
      return MITER_JOINT;
    case "heavy structural beams":
      return MORTISE_TENON_JOINT;
    case "concealed shelving":
      return DADO_JOINT;
    case "cabinet doors":
      return RAIL_AND_STILE_JOINT;
    default:
      return SIMPLE_SCREW_JOINT;
  }
}

function joint(purposes) {
  if (!Array.isArray(purposes)) {
    throw new TypeError("purposes must be an array of strings");
  }
  return purposes.map(function (purpose) {
    return lookupJoint(normalizePurpose(purpose));
  });
}

function describePlan(purposes) {
  const joints = joint(purposes);
  return purposes.map(function (purpose, index) {
    return normalizePurpose(purpose) + " -> " + joints[index];
  }).join("\n");
}

function summarizeTooling(joints) {
  const tally = {};
  joints.forEach(function (name) {
    tally[name] = (tally[name] || 0) + 1;
  });
  return Object.keys(tally).sort().map(function (name) {
    return name + " x" + tally[name];
  }).join(", ");
}

function main() {
  const plan = [
    "making a drawer",
    "right angle corners",
    "attaching legs",
    "Heavy Structural Beams"
  ];
  const joints = joint(plan);
  console.log(describePlan(plan));
  console.log("joints: " + JSON.stringify(joints));
  console.log("tooling summary: " + summarizeTooling(joints));
}
main();
module.exports = { joint, describePlan, summarizeTooling };

