const BIRTHSTONES = {
  january: "garnet",
  february: "amethyst",
  march: "aquamarine",
  april: "diamond",
  may: "emerald",
  june: "pearl",
  july: "ruby",
  august: "peridot",
  september: "sapphire",
  october: "opal",
  november: "topaz",
  december: "turquoise"
};

const DEFAULT_STONE = "synthetic crystal";
const MONTH_NAMES = Object.keys(BIRTHSTONES);

function normalizeMonth(value) {
  if (typeof value !== "string") {
    return "";
  }
  return value.trim().toLowerCase().replace(/[.,;]+$/, "");
}

function gemstone(months) {
  if (!Array.isArray(months)) {
    throw new TypeError("gemstone expects an array of month names");
  }
  return months.map(function (month) {
    const key = normalizeMonth(month);
    return Object.prototype.hasOwnProperty.call(BIRTHSTONES, key)
      ? BIRTHSTONES[key]
      : DEFAULT_STONE;
  });
}

function monthFromBirthday(birthday) {
  const text = String(birthday).trim();
  const isoParts = text.split("-");
  if (isoParts.length === 3) {
    const index = Number(isoParts[1]) - 1;
    return MONTH_NAMES[index] || isoParts[1];
  }
  return text.split(/[\s,]+/)[0];
}

function formatReport(birthdays) {
  const months = birthdays.map(monthFromBirthday);
  const stones = gemstone(months);
  const width = birthdays.reduce((max, entry) => Math.max(max, entry.length), 0);
  return birthdays.map(function (birthday, i) {
    const label = birthday.padEnd(width, " ");
    return label + "  ->  " + stones[i];
  });
}

const birthdays = [
  "1990-03-15",
  "1972-10-02",
  "2001-13-09",
  "August 4, 1988",
  "December 31, 1999"
];

console.log("Birthday gemstone report");
formatReport(birthdays).forEach(function (line) {
  console.log(line);
});

module.exports = { gemstone, monthFromBirthday, formatReport };

