function parseTriple(text) {
  const parts = text.split(",");
  if (parts.length !== 3) {
    throw new Error("expected three comma-separated values");
  }
  return parts.map(function (part) {
    const value = Number(part.trim());
    if (!Number.isFinite(value)) {
      throw new Error("not a number: " + part.trim());
    }
    return value;
  });
}

const COMPONENT_NAMES = [
  "sand",
  "silt",
  "clay"
];

function validate(percentages) {
  if (!Array.isArray(percentages)) {
    throw new TypeError("percentages must be an array of three numbers");
  }
  if (percentages.length !== 3) {
    throw new RangeError("percentages must hold sand, silt and clay only");
  }
  percentages.forEach(function (value, index) {
    if (!Number.isFinite(value) || value < 0 || value > 100) {
      throw new RangeError(COMPONENT_NAMES[index] + " must be in 0..100");
    }
  });
  const total = percentages[0] + percentages[1] + percentages[2];
  if (Math.abs(total - 100) > 1) {
    throw new RangeError("components must add up to about 100, got " + total);
  }
}

function classify(percentages) {
  validate(percentages);
  const [sand, silt, clay] = percentages;
  if (sand > 85) {
    return "sand";
  }
  if (silt > 80) {
    return "silt";
  }
  if (clay > 40) {
    return "clay";
  }
  if (clay >= 28) {
    if (sand >= 45 && clay <= 35) {
      return "sandy clay loam";
    }
    if (silt >= 50) {
      return "silty clay loam";
    }
    return "clay loam";
  }
  if (sand > 70) {
    return "loamy sand";
  }
  if (sand > 50) {
    return "sandy loam";
  }
  if (silt > 50) {
    return "silt loam";
  }
  return "loam";
}

function describe(text) {
  const triple = parseTriple(text);
  const columns = triple.map(function (value, index) {
    return COMPONENT_NAMES[index] + " " + value.toFixed(0);
  });
  const header = columns.join(", ");
  return header + " -> " + classify(triple);
}

function main() {
  const samples = [
    "10, 10, 80",
    "90, 5, 5",
    "75, 15, 10",
    "60, 25, 15",
    "35, 35, 30",
    "20, 60, 20",
    "5, 85, 10",
    "25, 45, 30",
    "15, 55, 30"
  ];
  samples.forEach(function (sample) {
    console.log(describe(sample));
  });
}

main();

