function parseWeights(weights) {
  if (!Array.isArray(weights)) {
    throw new TypeError("weights must be an array of [flour, water]");
  }
  if (weights.length !== 2) {
    throw new RangeError("weights must contain exactly two numbers");
  }
  const parsed = weights.map(function (value) {
    const num = typeof value === "string" ? Number(value.trim()) : value;
    if (typeof num !== "number" || !Number.isFinite(num)) {
      throw new TypeError("each weight must be a finite number");
    }
    return num;
  });
  const [flour, water] = parsed;
  if (flour <= 0) {
    throw new RangeError("flour weight must be greater than zero");
  }
  if (water < 0) {
    throw new RangeError("water weight cannot be negative");
  }
  return { flour: flour, water: water };
}

function hydration(weights) {
  const { flour, water } = parseWeights(weights);
  return (water / flour) * 100;
}

function evaluate(weights) {
  const percent = hydration(weights);
  if (percent < 50) {
    return "very stiff dough";
  }
  if (percent < 60) {
    return "stiff dough";
  }
  if (percent < 65) {
    return "standard dough";
  }
  if (percent < 70) {
    return "rustic dough";
  }
  if (percent < 75) {
    return "wet dough";
  }
  if (percent < 80) {
    return "ciabatta dough";
  }
  if (percent < 90) {
    return "focaccia dough";
  }
  return "batter";
}

function describe(weights) {
  const { flour, water } = parseWeights(weights);
  const percent = hydration(weights).toFixed(1);
  const parts = [
    flour + "g flour",
    water + "g water",
    percent + "% hydration",
    evaluate(weights)
  ];
  return parts.join(" | ");
}

function report(batches) {
  return batches.map(function (batch) {
    return describe(batch);
  }).join("\n");
}

function main(args) {
  if (args.length >= 2) {
    console.log(describe(args.slice(0, 2)));
    return;
  }
  const batches = [
    [1000, 400],
    [500, 275],
    [1000, 620],
    [100, 65],
    [800, 576],
    [250, 250]
  ];
  console.log(report(batches));
}

main(process.argv.slice(2));

