const ERUPTION_TYPES = [
  "hawaiian",
  "strombolian",
  "vulcanian",
  "pelean",
  "plinian",
  "paroxysmal",
  "colossal",
  "super colossal",
  "mega colossal"
];

const WORD_NUMBERS = {
  zero: 0,
  one: 1,
  two: 2,
  three: 3,
  four: 4,
  five: 5,
  six: 6,
  seven: 7,
  eight: 8
};

function determine(index) {
  if (typeof index !== "number" || !Number.isInteger(index)) {
    throw new TypeError("volcanic explosivity index must be an integer");
  }
  if (index < 0 || index >= ERUPTION_TYPES.length) {
    throw new RangeError("volcanic explosivity index must be between 0 and 8");
  }
  return ERUPTION_TYPES[index];
}

function parseIndex(text) {
  const trimmed = String(text).trim();
  const lowered = trimmed.toLowerCase();
  if (Object.prototype.hasOwnProperty.call(WORD_NUMBERS, lowered)) {
    return WORD_NUMBERS[lowered];
  }
  if (!/^[+-]?\d+$/.test(trimmed)) {
    throw new SyntaxError("cannot read an explosivity index from " + JSON.stringify(trimmed));
  }
  return Number.parseInt(trimmed, 10);
}

function describe(text) {
  try {
    const index = parseIndex(text);
    const label = "VEI " + index;
    return label + ": " + determine(index);
  } catch (error) {
    return "invalid input: " + error.message;
  }
}

function report(inputs) {
  return inputs.map(describe).join("\n");
}

function main() {
  const samples = [
    "0",
    "four",
    " 7 ",
    "8",
    "9",
    "two point five"
  ];
  console.log(report(samples));
  console.log("an eruption rated four is " + determine(4));
}

main();

module.exports = { determine, parseIndex, describe, report };

