const HIGH_CLOUDS = {
  wispy: "cirrus",
  patch: "cirrocumulus",
  sheet: "cirrostratus"
};

const MIDDLE_CLOUDS = {
  patch: "altocumulus",
  sheet: "altostratus",
  dark: "nimbostratus"
};

const LOW_CLOUDS = {
  patch: "stratocumulus",
  sheet: "stratus",
  puffy: "cumulus",
  towering: "cumulonimbus"
};

const UNKNOWN = "unknown cloud";

function layerName(altitude) {
  if (altitude > 6000) {
    return "high";
  }
  if (altitude >= 2000) {
    return "middle";
  }
  return "low";
}

function layerTable(altitude) {
  const layer = layerName(altitude);
  if (layer === "high") {
    return HIGH_CLOUDS;
  }
  return layer === "middle" ? MIDDLE_CLOUDS : LOW_CLOUDS;
}

function identify(attributes) {
