function grade(weight) {
  if (typeof weight !== "number" || Number.isNaN(weight)) {
    throw new TypeError("egg weight must be a number of grams");
  }
  if (weight < 0) {
    throw new RangeError("egg weight cannot be negative");
  }
  if (weight < 42) {
    return "peewee";
  }
  if (weight < 49) {
    return "small";
  }
  if (weight < 56) {
    return "medium";
  }
  if (weight < 63) {
    return "large";
  }
  if (weight < 70) {
    return "extra large";
  }
  if (weight < 77) {
    return "jumbo";
  }
  if (weight < 84) {
    return "super jumbo";
  }
  return "ostrich size";
}

function parseWeight(text) {
  const cleaned = String(text).trim().replace(/\s*(g|grams?)$/i, "");
  const value = Number(cleaned);
  if (cleaned === "" || Number.isNaN(value)) {
    throw new SyntaxError("cannot read a weight from " + JSON.stringify(text));
  }
  return value;
}

function describe(text) {
  const weight = parseWeight(text);
  return weight.toFixed(1) + " g -> " + grade(weight);
}

function tallyGrades(weights) {
  const counts = new Map();
  for (const weight of weights) {
    const name = grade(weight);
    counts.set(name, (counts.get(name) || 0) + 1);
  }
  return counts;
}

function report(entries) {
  const lines = [];
  const weights = [];
  for (const entry of entries) {
    try {
      const weight = parseWeight(entry);
      weights.push(weight);
      lines.push(describe(entry));
    } catch (error) {
      lines.push(String(entry) + " -> " + error.message);
    }
  }
  for (const [name, count] of tallyGrades(weights)) {
    lines.push(count + " x " + name);
  }
  return lines.join("\n");
}

