const BANDS = [
  { max: 3, name: "light air" },
  { max: 7, name: "light breeze" },
  { max: 12, name: "gentle breeze" },
  { max: 18, name: "moderate breeze" },
  { max: 24, name: "fresh breeze" },
  { max: 31, name: "strong breeze" },
  { max: 38, name: "near gale" },
  { max: 46, name: "gale" },
  { max: 54, name: "strong gale" },
  { max: 63, name: "storm" }
];

function assess(speed) {
  if (typeof speed !== "number" || Number.isNaN(speed)) {
    throw new TypeError("wind speed must be a number");
  }
  if (speed < 0) {
    throw new RangeError("wind speed cannot be negative");
  }
  if (speed < 1) {
    return "calm";
  }
  const band = BANDS.find(entry => speed <= entry.max);
  if (!band) {
    throw new RangeError("wind speed is off the top of the Beaufort scale");
  }
  return band.name;
}

function parseSpeed(text) {
  const trimmed = String(text).trim();
  if (trimmed === "") {
    throw new SyntaxError("no wind speed was supplied");
  }
  const value = Number(trimmed);
  if (Number.isNaN(value)) {
    throw new SyntaxError("cannot read a wind speed from: " + trimmed);
  }
  return value;
}

function formatSpeed(speed) {
  if (speed === 1) {
    return speed + " knot";
  }
  return speed + " knots";
}

function describe(speed) {
  return formatSpeed(speed) + " => " + assess(speed);
}

function report(readings) {
  const lines = readings.map(reading => {
    try {
      return describe(parseSpeed(reading));
    } catch (error) {
      const subject = "skipped " + String(reading).trim();
      return subject + ": " + error.message;
    }
  });
  return lines.join("\n");
}

function main() {
  const readings = [
    "0.4",
    "1",
    "6",
    "10",
    " 37 ",
    "58",
    "gusty"
  ];
  console.log(report(readings));
}

main();

module.exports = { assess, parseSpeed, formatSpeed, describe, report };

