const SHAKING_LEVELS = [
  { limit: 0.0017, label: "instrumental" },
  { limit: 0.014, label: "weak" },
  { limit: 0.039, label: "slight" },
  { limit: 0.092, label: "moderate" },
  { limit: 0.18, label: "rather strong" },
  { limit: 0.34, label: "strong" },
  { limit: 0.65, label: "very strong" },
  { limit: 1.24, label: "severe" },
  { limit: 2.2, label: "violent" }
];

const TOP_LEVEL = "extreme";

function measure(acceleration) {
  if (typeof acceleration !== "number" || Number.isNaN(acceleration)) {
    throw new TypeError("acceleration must be a numeric value in g");
  }
  for (const level of SHAKING_LEVELS) {
    if (acceleration < level.limit) {
      return level.label;
    }
  }
  return TOP_LEVEL;
}

function parseAcceleration(text) {
  const cleaned = String(text).trim().toLowerCase().replace(/\s*g$/, "");
  const value = Number(cleaned);
  if (cleaned === "" || Number.isNaN(value)) {
    throw new Error("cannot read a peak ground acceleration from " + text);
  }
  return value;
}

function describe(acceleration) {
  const label = measure(acceleration);
  const formatted = acceleration.toFixed(4);
  return formatted + " g -> " + label;
}

function report(readings) {
  const lines = readings.map(function (reading) {
    try {
      return describe(parseAcceleration(reading));
    } catch (error) {
      return "skipped: " + error.message;
    }
  });
  return lines.join("\n");
}

function summarise(readings) {
  const values = readings.map(parseAcceleration);
  const worst = measure(Math.max.apply(null, values));
  const counts = new Map();
  for (const label of values.map(measure)) {
    counts.set(label, (counts.get(label) || 0) + 1);
  }
  const parts = [];
  for (const [label, count] of counts) {
    parts.push(label + " x" + count);
  }
  const tally = parts.join(", ");
  const head = "strongest: " + worst;
  return head + "; tally: " + tally;
}

function main() {
  const readings = [
    "0.0005",
    "0.01 g",
    "0.05",
    "0.15 g",
    "0.5",
    "1.0 g",
    "3.4"
  ];
  console.log(report(readings));
  console.log(summarise(readings));
  console.log(report(["not-a-number"]));
}

main();

