function evaluate(days) {
  if (typeof days !== "number" || !Number.isFinite(days)) {
    throw new TypeError("age in days must be a finite number");
  }
  if (days < 0) {
    throw new RangeError("age in days cannot be negative");
  }
  if (days < 7) {
    return "fresh cheese";
  }
  if (days <= 20) {
    return "soft ripened";
  }
  if (days <= 60) {
    return "semi soft";
  }
  if (days <= 120) {
    return "medium firm";
  }
  if (days <= 240) {
    return "firm";
  }
  if (days <= 400) {
    return "hard cheese";
  }
  if (days <= 700) {
    return "extra hard";
  }
  return "vintage";
}

function parseDays(text) {
  const cleaned = text.trim();
  if (cleaned === "") {
    throw new Error("no age supplied");
  }
  const value = Number(cleaned);
  if (!Number.isFinite(value)) {
    throw new Error("could not read age: " + cleaned);
  }
  return value;
}

function parseEntry(line) {
  const fields = line.split(",");
  if (fields.length !== 2) {
    throw new Error("expected a name and an age separated by a comma");
  }
  return { name: fields[0].trim(), days: parseDays(fields[1]) };
}

function pluralize(days) {
  if (days === 1) {
    return "day";
  }
  return "days";
}

function describe(name, days) {
  const parts = [name];
  parts.push("aged");
  parts.push(String(days));
  parts.push(pluralize(days));
  parts.push("is");
  parts.push(evaluate(days));
  return parts.join(" ");
}

function report(lines) {
  return lines
    .map(function (line) {
