const A_SERIES = [
  { width: 841, height: 1189, word: "zero" },
  { width: 594, height: 841, word: "one" },
  { width: 420, height: 594, word: "two" },
  { width: 297, height: 420, word: "three" },
  { width: 210, height: 297, word: "four" },
  { width: 148, height: 210, word: "five" },
  { width: 105, height: 148, word: "six" },
  { width: 74, height: 105, word: "seven" }
];

const CUSTOM = "custom size";

function name(dimensions) {
  if (!Array.isArray(dimensions) || dimensions.length !== 2) {
    throw new TypeError("dimensions must be a list of width and height");
  }
  const [width, height] = dimensions.map(Number);
  if (!Number.isFinite(width) || !Number.isFinite(height)) {
    throw new RangeError("width and height must be numeric millimetres");
  }
  const match = A_SERIES.find(function (sheet) {
    return sheet.width === width && sheet.height === height;
  });
  return match ? match.word : CUSTOM;
}

function parseDimensions(text) {
  const parts = String(text).toLowerCase().split("x");
  if (parts.length !== 2) {
    throw new SyntaxError("expected a size written as WIDTHxHEIGHT");
  }
  return parts.map(function (part) {
    return Number(part.trim());
  });
}

function formatDimensions(dimensions) {
  const separator = " x ";
  return dimensions[0] + separator + dimensions[1] + " mm";
}

function label(word) {
  if (word === CUSTOM) {
    return CUSTOM;
  }
  return "A" + word;
}

function describe(text) {
  const dimensions = parseDimensions(text);
  const word = name(dimensions);
  const arrow = " -> ";
  return formatDimensions(dimensions) + arrow + label(word);
}

function report(sizes) {
  return sizes.map(describe).join("\n");
}

function main() {
  const requested = [
    "841x1189",
    "594 x 841",
    "420x594",
    "297x420",
    "210x297",
    "148x210",
    "105x148",
    "74x105",
    "200x300"
  ];
  console.log(report(requested));
}

main();

module.exports = { name, parseDimensions, formatDimensions, label, describe, report };

