const CAR_TYPES = {
  1: "boxcar",
  2: "flatcar",
  3: "hopper car",
  4: "covered hopper",
  5: "gondola",
  6: "tank car",
  7: "refrigerator car",
  8: "autorack",
  9: "caboose"
};

function classify(code) {
  const digit = normalizeCode(code);
  return CAR_TYPES[digit];
}

function normalizeCode(code) {
  if (typeof code === "string") {
    const trimmed = code.trim();
    if (!/^[1-9]$/.test(trimmed)) {
      throw new RangeError("code must be a single digit from 1 to 9");
    }
    return Number(trimmed);
  }
  if (typeof code !== "number" || !Number.isInteger(code)) {
    throw new TypeError("code must be an integer or a digit string");
  }
  if (code < 1 || code > 9) {
    throw new RangeError("code must be a single digit from 1 to 9");
  }
  return code;
}

function parseConsist(manifest) {
  return manifest
    .split(",")
    .map(function (field) {
      return field.trim();
    })
    .filter(function (field) {
      return field.length > 0;
    })
    .map(normalizeCode);
}

function describeConsist(manifest) {
  const codes = parseConsist(manifest);
  if (codes.length === 0) {
    return "empty train";
  }
  return codes
    .map(function (digit, index) {
      return String(index + 1) + ". " + classify(digit);
    })
    .join("\n");
}

function countByType(manifest) {
  const tally = new Map();
  parseConsist(manifest).forEach(function (digit) {
    const name = classify(digit);
    tally.set(name, (tally.get(name) || 0) + 1);
  });
  return tally;
}

