const ATTRIBUTE_NAMES = [
  "luster",
  "surface",
  "shape"
];

const GRADE_THRESHOLDS = [
  [9, "hanadama"],
  [8, "triple a"],
  [7, "double a plus"],
  [6, "double a"],
  [5, "single a plus"],
  [4, "single a"]
];

const SEPARATOR = ", ";

function validateScores(attributes) {
  if (!Array.isArray(attributes)) {
    throw new TypeError("attributes must be an array of scores");
  }
  if (attributes.length !== ATTRIBUTE_NAMES.length) {
    throw new RangeError("expected scores for " + ATTRIBUTE_NAMES.join(SEPARATOR));
  }
  return attributes.map((score, index) => {
    const name = ATTRIBUTE_NAMES[index];
    if (typeof score !== "number" || !Number.isFinite(score)) {
      throw new TypeError(name + " must be a finite number");
    }
    if (score < 0 || score > 10) {
      throw new RangeError(name + " must be between 0 and 10");
    }
    return score;
  });
}

function average(scores) {
  const total = scores.reduce((sum, score) => sum + score, 0);
  return total / scores.length;
}

function evaluate(attributes) {
  const scores = validateScores(attributes);
  if (scores.every(score => score === 10)) {
    return "flawless gem";
  }
  const mean = average(scores);
  for (const [minimum, grade] of GRADE_THRESHOLDS) {
    if (mean > minimum) {
      return grade;
    }
  }
  return "commercial quality";
}

function parseAttributes(text) {
  const parts = String(text).split(",");
  return parts.map(part => {
    const trimmed = part.trim();
    const score = Number(trimmed);
    if (trimmed === "" || Number.isNaN(score)) {
      throw new SyntaxError("cannot read a score from " + JSON.stringify(part));
    }
    return score;
  });
}

function formatReport(attributes) {
  const scores = validateScores(attributes);
  const listed = scores.map((score, index) => ATTRIBUTE_NAMES[index] + ": " + score);
  const mean = average(scores).toFixed(2);
  const heading = listed.join(SEPARATOR);
  const summary = " | average " + mean;
  return heading + summary + " -> " + evaluate(scores);
}

