function parseSpeed(raw) {
  if (typeof raw === "number") {
    return raw;
  }
  if (typeof raw !== "string") {
    throw new TypeError("wind speed must be a number or a numeric string");
  }
  const trimmed = raw.trim().replace(/\s*(kt|kts|mph)$/i, "");
  const value = Number(trimmed);
  if (!Number.isFinite(value)) {
    throw new TypeError("unable to parse wind speed from " + raw);
  }
  return value;
}

function categorize(speed) {
  const value = parseSpeed(speed);
  if (value < 0) {
    throw new RangeError("wind speed cannot be negative");
  }
  const labels = [];
  if (value === 0) {
    labels.push("tropical disturbance");
  } else if (value < 39) {
    labels.push("tropical depression");
  } else if (value <= 73) {
    labels.push("tropical storm");
  } else if (value <= 95) {
    labels.push("category one");
  } else if (value <= 110) {
    labels.push("category two");
  } else if (value <= 129) {
    labels.push("category three");
  } else if (value <= 156) {
    labels.push("category four");
  } else {
    labels.push("category five");
  }
  if (value > 111) {
    labels.push("major hurricane");
  }
  return labels;
}

function describe(speed) {
  return categorize(speed).join(" / ");
}

function formatReading(reading) {
  const value = parseSpeed(reading);
  const column = String(value).padStart(4, " ");
  const unit = " kt -> ";
  return column + unit + describe(value);
}

function report(readings) {
  return readings.map(formatReading).join("\n");
}

function main() {
  const readings = [
    0,
    25,
    "55 kt",
    80,
    100,
    "120 mph",
    140,
    180
  ];
  console.log(report(readings));
  const strongest = readings.reduce(function (best, reading) {
    return Math.max(best, parseSpeed(reading));
  }, 0);
  console.log("strongest reading: " + describe(strongest));
}

main();

