const SOLVENT_TAGS = [
  "pomace",
  "solvent",
  "solvents"
];
const REFINED_TAGS = [
  "refined",
  "treated"
];
const BLENDED_TAGS = [
  "blend",
  "blended"
];

function parseAcidity(value) {
  const text = String(value).trim();
  const acidity = Number(text);
  if (text === "" || !Number.isFinite(acidity) || acidity < 0) {
    throw new Error("invalid acidity: " + text);
  }
  return acidity;
}

function hasTag(tags, group) {
  return tags.some(function (tag) { return group.includes(tag); });
}

function certify(acidity) {
  const fields = String(acidity).split("|");
  const tags = fields.slice(1).map(function (field) { return field.trim().toLowerCase(); });
  const level = parseAcidity(fields[0]);
  const refined = hasTag(tags, REFINED_TAGS) && level <= 0.3;
  const blended = hasTag(tags, BLENDED_TAGS) && level <= 1.0;
  if (hasTag(tags, SOLVENT_TAGS)) {
    if (refined) {
      return "refined pomace";
    }
    if (blended) {
      return "pomace blend";
    }
    return "raw pomace";
  }
  if (refined) {
    return "refined olive oil";
  }
  if (blended) {
    return "olive oil blend";
  }
  if (level <= 0.8) {
    return "extra virgin";
  }
  if (level <= 2.0) {
    return "virgin";
  }
  if (level <= 3.3) {
    return "ordinary virgin";
  }
  return "lampante";
}

function main() {
  const batch = [
    0.45,
    1.5,
    "2.7 | raw",
    4.1,
    "0.2 | treated",
    "0.9 | blended",
