const SIZES = [
  { minLength: 23.6, name: "full size" },
  { minLength: 23, name: "seven eighths" },
  { minLength: 22, name: "three quarters" },
  { minLength: 20, name: "one half" },
  { minLength: 18.5, name: "one quarter" },
  { minLength: 17.1, name: "one eighth" },
  { minLength: 16.5, name: "one tenth" },
  { minLength: 15.3, name: "one sixteenth" },
  { minLength: 0, name: "one thirty second" }
];

function validateLength(length) {
  if (typeof length !== "number" || Number.isNaN(length)) {
    throw new TypeError("arm length must be a number of inches");
  }
  if (length <= 0) {
    throw new RangeError("arm length must be greater than zero");
  }
  return length;
}

function size(length) {
  validateLength(length);
  const match = SIZES.find(function (entry) {
    return length >= entry.minLength;
  });
  return match.name;
}

function parseLength(text) {
  const cleaned = String(text).trim().toLowerCase();
  let trimmed = cleaned;
  if (trimmed.endsWith("inches")) {
    trimmed = trimmed.slice(0, -6);
  } else if (trimmed.endsWith("in")) {
    trimmed = trimmed.slice(0, -2);
  }
  const value = Number(trimmed.trim());
  if (Number.isNaN(value)) {
    throw new SyntaxError("cannot read an arm length from: " + text);
  }
  return value;
}

function describe(length) {
  const inches = length.toFixed(1);
  return inches + " in needs a " + size(length);
}

function report(measurements) {
  const lines = measurements.map(function (measurement) {
    const length = typeof measurement === "number" ? measurement : parseLength(measurement);
    return describe(length);
  });
  return lines.join("\n");
}

function main() {
  const measurements = [
    "14",
    "15.3 in",
    "16.5 inches",
    17.1,
    "18.5",
    20,
    "22",
    23,
    "25 in"
  ];
  console.log("violin size chart");
  console.log(report(measurements));
  try {
    size(parseLength("about a foot"));
  } catch (error) {
    console.log("rejected input: " + error.message);
  }
}

main();

module.exports = { size, parseLength, describe, report };

