"use strict";

function rank(carbon) {
  if (typeof carbon !== "number" || Number.isNaN(carbon)) {
    throw new TypeError("carbon content must be a number");
  }
  if (carbon < 0 || carbon > 100) {
    throw new RangeError("carbon content must be a percentage from 0 to 100");
  }
  if (carbon < 60) {
    return "peat";
  }
  if (carbon < 70) {
    return "lignite";
  }
  if (carbon < 76) {
    return "sub bituminous";
  }
  if (carbon < 86) {
    return "high volatile bituminous";
  }
  if (carbon < 89) {
    return "medium volatile bituminous";
  }
  if (carbon < 90) {
    return "low volatile bituminous";
  }
  if (carbon <= 92) {
    return "semi anthracite";
  }
  return "anthracite";
}

function parseCarbon(text) {
  const trimmed = String(text).trim();
  const cleaned = trimmed.endsWith("%")
    ? trimmed.slice(0, -1)
    : trimmed;
  const value = Number(cleaned);
  if (cleaned.length === 0 || Number.isNaN(value)) {
    throw new TypeError("cannot read a carbon percentage from " + JSON.stringify(text));
  }
  return value;
}

function family(carbon) {
  if (rank(carbon) === "peat") {
    return "pre-coal deposit";
  }
  return "coal";
}

function describe(text) {
  const carbon = parseCarbon(text);
  let line = carbon.toFixed(1);
  line += "% carbon -> ";
  line += rank(carbon);
  line += " (";
  line += family(carbon);
  return line + ")";
}

function report(samples) {
  const lines = [];
  for (const sample of samples) {
    try {
      lines.push(describe(sample));
    } catch (error) {
      lines.push("skipped: " + error.message);
    }
  }
  return lines.join("\n");
}

function main() {
  const samples = [
    "52",
    "65",
    "73.5 %",
    "80",
    "87",
    "89.5",
    "91",
    "95",
    "ash"
  ];
  console.log(report(samples));
}

main();

module.exports = { rank, parseCarbon, family, describe, report };

