const RAPID_CLASSES = {
  1: "flat water",
  2: "novice",
  3: "intermediate",
  4: "advanced",
  5: "expert",
  6: "extreme and exploratory",
  7: "unrunnable",
  8: "absolute hazard"
};

const ROMAN_RATINGS = {
  I: 1,
  II: 2,
  III: 3,
  IV: 4,
  V: 5,
  VI: 6,
  VII: 7,
  VIII: 8
};

function classify(difficulty) {
  if (typeof difficulty !== "number" || !Number.isFinite(difficulty)) {
    throw new TypeError("difficulty must be a finite number");
  }
  if (!Number.isInteger(difficulty)) {
    throw new RangeError("difficulty must be a whole number from 1 to 8");
  }
  const phrase = RAPID_CLASSES[difficulty];
  if (phrase === undefined) {
    throw new RangeError("difficulty must be between 1 and 8");
  }
  return phrase;
}

function parseRating(text) {
  const trimmed = String(text).trim();
  if (trimmed === "") {
    throw new SyntaxError("no rating supplied");
  }
  const upper = trimmed.toUpperCase();
  if (Object.prototype.hasOwnProperty.call(ROMAN_RATINGS, upper)) {
    return ROMAN_RATINGS[upper];
  }
  const numeric = Number(trimmed);
  if (Number.isNaN(numeric)) {
    throw new SyntaxError("cannot read a rating from " + trimmed);
  }
  return numeric;
}

function describe(text) {
  const label = "Class ";
  try {
    const rating = parseRating(text);
    return label + rating + ": " + classify(rating);
  } catch (error) {
    return label + "?: " + error.message;
  }
}

function report(inputs) {
  const header = "Whitewater rapid classification";
  const rule = "-".repeat(header.length);
  return [header, rule].concat(inputs.map(describe)).join("\n");
}

function main() {
  const samples = [1, 4, 8];
  samples.push("2");
  samples.push("III");
  samples.push("VII");
  samples.push("9");
  samples.push("class");
  console.log(report(samples));
}

main();

module.exports = { classify, parseRating, describe, report };

