const GRADE_BANDS = [
  { min: 12, max: 36, label: "macro grit extra coarse" },
  { min: 40, max: 50, label: "macro grit coarse" },
  { min: 60, max: 80, label: "macro grit medium" },
  { min: 100, max: 120, label: "macro grit fine" },
  { min: 150, max: 220, label: "macro grit very fine" },
  { min: 240, max: 360, label: "micro grit very fine" },
  { min: 400, max: 600, label: "micro grit extra fine" },
  { min: 800, max: 1200, label: "micro grit super fine" }
];

const ULTRA_FINE = "micro grit ultra fine";

const HEADER = "  grit  |  grade";

const DIVIDER = "--------+------------------------";

const SEPARATOR = "  |  ";

function parseGrit(value) {
  const number = typeof value === "string" ? Number(value.trim()) : value;
  if (typeof number !== "number" || !Number.isFinite(number)) {
    throw new TypeError("grit must be a finite number: " + JSON.stringify(value));
  }
  if (number <= 0) {
    throw new RangeError("grit must be greater than zero: " + number);
  }
  return number;
}

function grade(grit) {
  const number = parseGrit(grit);
  if (number > 1200) {
    return ULTRA_FINE;
  }
  for (const band of GRADE_BANDS) {
    if (number >= band.min && number <= band.max) {
      return band.label;
    }
  }
  throw new RangeError("no standard grade covers grit " + number);
}

function describe(grit) {
  try {
    return grade(grit);
  } catch (error) {
    return "unrated: " + error.message;
  }
}

function formatRow(grit) {
  const left = String(grit).padStart(6, " ");
  return left + SEPARATOR + describe(grit);
}

function report(grits) {
  const lines = [HEADER, DIVIDER];
  for (const grit of grits) {
    lines.push(formatRow(grit));
  }
  return lines.join("\n");
}

function coarsestFirst(grits) {
  return grits
    .map(function (grit) {
      return parseGrit(grit);
    })
    .sort(function (a, b) {
      return a - b;
    });
}

function main() {
  const samples = [24, 40, 70, "120", 180, 320, 500, 1000, 2400, 95];
  console.log(report(samples));
  const ranked = coarsestFirst([600, 80, 1200, 150]);
  console.log("sorted stock: " + ranked.join(SEPARATOR));
  console.log("finest of the stock is " + grade(ranked[ranked.length - 1]));
}

main();

module.exports = { grade, describe, report, parseGrit, coarsestFirst };

