const MARKERS = {
  1: "* ",
  2: "  - ",
  3: "    > "
};

const FALLBACK_TEXT = "Untitled";

function normalizeText(text) {
  if (typeof text !== "string") {
    throw new TypeError("heading text must be a string");
  }
  const trimmed = text.trim();
  return trimmed.length === 0 ? FALLBACK_TEXT : trimmed;
}

function normalizeLevel(level) {
  if (!Number.isInteger(level)) {
    throw new TypeError("heading level must be an integer");
  }
  if (!Object.prototype.hasOwnProperty.call(MARKERS, level)) {
    throw new RangeError("heading level must be 1, 2 or 3");
  }
  return level;
}

function formatHeading(heading) {
  const level = normalizeLevel(heading.level);
  return MARKERS[level] + normalizeText(heading.text);
}

function outline(headings) {
  if (!Array.isArray(headings)) {
    throw new TypeError("headings must be an array");
  }
  const lines = ["Table of Contents"];
  for (const heading of headings) {
    lines.push(formatHeading(heading));
  }
  return lines.join("\n");
}

function parseMarkdownHeadings(markdown) {
  const headings = [];
  for (const rawLine of markdown.split("\n")) {
    const match = /^(#{1,3})\s*(.*)$/.exec(rawLine.trim());
    if (match !== null) {
      headings.push({ level: match[1].length, text: match[2] });
    }
  }
  return headings;
}

function countByLevel(headings) {
  const counts = { 1: 0, 2: 0, 3: 0 };
  for (const heading of headings) {
    counts[normalizeLevel(heading.level)] += 1;
  }
  return counts;
}

function summarize(headings) {
  const counts = countByLevel(headings);
  const parts = [];
  parts.push(counts[1] + " chapter(s)");
  parts.push(counts[2] + " section(s)");
  parts.push(counts[3] + " subsection(s)");
  return parts.join(", ");
}

function main() {
  const document = [
    "# Getting Started",
    "## Installation",
    "### Requirements",
    "###",
    "## Configuration",
    "# Reference"
  ].join("\n");
  const headings = parseMarkdownHeadings(document);
  console.log(outline(headings));
  console.log("");
  console.log("Summary: " + summarize(headings));
}

main();

module.exports = { outline, parseMarkdownHeadings, summarize };

