"use strict";

function validateTask(task, location, position) {
  const where = location + ", task #" + (position + 1);
  if (typeof task !== "object" || task === null) {
    throw new TypeError(where + " must be an object");
  }
  if (typeof task.description !== "string") {
    throw new TypeError(where + " needs a description string");
  }
  if (typeof task.completed !== "boolean") {
    throw new TypeError(where + " needs a boolean completed flag");
  }
}

function validateList(list, index) {
  const location = "list #" + (index + 1);
  if (typeof list !== "object" || list === null) {
    throw new TypeError(location + " must be an object");
  }
  if (typeof list.title !== "string" || list.title.trim().length === 0) {
    throw new TypeError(location + " needs a non-empty title");
  }
  if (!Array.isArray(list.tasks)) {
    throw new TypeError(location + " needs an array of tasks");
  }
  list.tasks.forEach(function (task, position) {
    validateTask(task, location, position);
  });
}

function checkbox(completed) {
  if (completed) {
    return "[x]";
  }
  return "[ ]";
}

function renderTask(task) {
  const parts = ["-", checkbox(task.completed), task.description.trim()];
  return parts.join(" ");
}

function renderList(list) {
  const heading = "## " + list.title;
  return [heading].concat(list.tasks.map(renderTask));
}

function board(lists) {
  if (!Array.isArray(lists)) {
    throw new TypeError("board expects an array of lists");
  }
  const lines = ["Board"];
  lists.forEach(function (list, index) {
    validateList(list, index);
    renderList(list).forEach(function (line) {
      lines.push(line);
    });
  });
  return lines.join("\n");
}

function summarize(lists) {
  let done = 0;
  let total = 0;
  lists.forEach(function (list) {
    list.tasks.forEach(function (task) {
      total += 1;
      if (task.completed) {
        done += 1;
      }
    });
  });
  const ratio = done + "/" + total;
  return ratio + " tasks completed";
}

const sprint = [
  {
