const CONTENT_TYPE_VALUE = "text/plain";
const PROTOCOL = "HTTP/1.1";
const NEWLINE = "\n";
const ROOT_PATH = "/";

function normalizeMethod(method) {
  if (typeof method !== "string") {
    throw new TypeError("method must be a string");
  }
  const cleaned = method.trim();
  if (cleaned.length === 0) {
    throw new RangeError("method must not be empty");
  }
  return cleaned.toUpperCase();
}

function normalizePath(path) {
  if (typeof path !== "string") {
    throw new TypeError("path must be a string");
  }
  const cleaned = path.trim();
  if (cleaned.length === 0) {
    return ROOT_PATH;
  }
  if (cleaned.startsWith(ROOT_PATH)) {
    return cleaned;
  }
  return ROOT_PATH + cleaned;
}

function normalizeBody(body) {
  if (typeof body !== "string") {
    return "empty";
  }
  return body.trim().length === 0 ? "empty" : body;
}

function header(name, value) {
  return name + ": " + value + NEWLINE;
}

function request(options) {
  if (typeof options !== "object" || options === null) {
    throw new TypeError("options must be an object");
  }
  const requestLine = [normalizeMethod(options.method), normalizePath(options.path), PROTOCOL];
