function formatValue(value) {
  if (value === true) {
    return "yes";
  }
  if (value === false) {
    return "no";
  }
  if (value === undefined || value === null) {
    return "NONE";
  }
  return String(value);
}

function formatPair(pair) {
  const key = String(pair.key).trim();
  if (key === "") {
    throw new Error("a key value pair is missing its key");
  }
  return key + " = " + formatValue(pair.value);
}

function formatSection(section) {
  const name = String(section.name).trim();
  if (name === "") {
    throw new Error("a section is missing its name");
  }
  const lines = [
    "[" +
    name +
    "]"
  ];
  for (const pair of section.pairs || []) {
    lines.push(formatPair(pair));
  }
  return lines;
}

function ini(sections) {
  if (!Array.isArray(sections)) {
    throw new TypeError("ini expects a list of section objects");
  }
  const lines = [];
  for (const section of sections) {
    lines.push(...formatSection(section));
  }
  return lines.join("\n");
}

function main() {
  const config = [
    {
      name: "server",
      pairs: [
        {
          key: "host",
          value: "127.0.0.1"
        },
        { key: "port", value: 8080 },
        { key: "tls", value: true },
        { key: "verbose logging", value: false },
        { key: "certificate" }
      ]
    },
    {
      name: "database",
      pairs: [
        {
          key: "driver",
          value: "postgres"
        },
        { key: "pool size", value: 12 },
        { key: "replica", value: null }
      ]
    }
  ];
  console.log(ini(config));
}

main();

