const FLAG_PREFIX = " --";
const ASSIGN = "=";
const NULL_VALUE = "null";
const EMPTY = "";
const INDENT = "  ";
const ARROW = " -> ";
const SKIPPED = "skipped";

function validateOptions(options) {
  if (options === null || typeof options !== "object") {
    throw new TypeError("command() requires an options object");
  }
  if (typeof options.executable !== "string") {
    throw new TypeError("options.executable must be a string");
  }
  const args = options.arguments === undefined ? [] : options.arguments;
  if (!Array.isArray(args)) {
    throw new TypeError("options.arguments must be an array");
  }
  return args;
}

function formatArgument(arg) {
  const value = arg.value;
  if (value === false) {
    return EMPTY;
  }
  const head = FLAG_PREFIX + arg.flag;
  if (value === true) {
    return head;
  }
  if (value === null || value === undefined || value === EMPTY) {
    return head + ASSIGN + NULL_VALUE;
  }
  if (typeof value !== "string") {
    throw new TypeError("argument value must be a string or a boolean");
  }
  return head + ASSIGN + value;
}

function command(options) {
  const args = validateOptions(options);
  let line = options.executable;
  for (const arg of args) {
    line += formatArgument(arg);
  }
  return line;
}

function describe(options) {
  const args = validateOptions(options);
  const report = [options.executable + ":"];
  for (const arg of args) {
    const segment = formatArgument(arg);
    const state = segment === EMPTY ? SKIPPED : segment.trim();
    report.push(INDENT + arg.flag + ARROW + state);
  }
  return report.join("\n");
}

function main() {
  const options = {
    executable: "ffmpeg",
    arguments: [
      { flag: "verbose", value: true },
      { flag: "dry-run", value: false },
      {
        flag: "input",
        value: "clip.mov"
      },
      {
        flag: "preset",
        value: ""
      }
    ]
  };
  console.log(command(options));
  console.log(describe(options));
}
main();

