const QUOTE = "\"";
const NEWLINE = "\n";
const SEPARATOR = ",";
const MISSING = "unknown";
const DEFAULT_STATUS = "inactive";

const HEADER = [
  "name",
  "age",
  "location",
  "status"
];

function isMissing(value) {
  return value === undefined || value === null || String(value).trim() === "";
}

function escapeField(value) {
  const text = String(value);
  if (!/[",\r\n]/.test(text)) {
    return text;
  }
  const doubled = text.replace(/"/g, QUOTE + QUOTE);
  return QUOTE + doubled + QUOTE;
}

function pickField(record, key, fallback) {
  if (!record || typeof record !== "object") {
    throw new TypeError("each record must be an object");
  }
  return isMissing(record[key]) ? fallback : String(record[key]).trim();
}

function formatAge(record) {
  const raw = pickField(record, "age", MISSING);
  if (raw === MISSING) {
    return MISSING;
  }
  const age = Number(raw);
  if (!Number.isFinite(age) || age < 0) {
    return MISSING;
  }
  return String(Math.trunc(age));
}

const exporter = {
  export(records) {
    if (!Array.isArray(records)) {
      throw new TypeError("export expects an array of records");
    }
    let output = HEADER.join(SEPARATOR) + NEWLINE;
    for (const record of records) {
      const row = [
        pickField(record, "name", MISSING),
        formatAge(record),
        pickField(record, "location", MISSING),
        pickField(record, "status", DEFAULT_STATUS)
      ];
      output += row.map(escapeField).join(SEPARATOR) + NEWLINE;
    }
    return output;
  }
};

const people = [
  {
    name: "Ada Lovelace",
    age: 36,
    location: "London",
    status: "active"
  },
  {
    name: "Grace Hopper",
    age: 85,
    location: "Arlington, VA"
  },
  {
    name: "Alan Turing",
    location: "Wilmslow",
    status: "archived"
  },
  {
    age: "not a number",
    location: "",
    status: "active"
  }
];

process.stdout.write(exporter.export(people));

