const ANONYMOUS = "Anonymous Scholar";

function normalizeAuthor(author) {
  if (typeof author !== "string") {
    return ANONYMOUS;
  }
  const trimmed = author.trim();
  return trimmed.length === 0 ? ANONYMOUS : trimmed;
}

function normalizeField(value, fallback) {
  if (value === null || value === undefined) {
    return fallback;
  }
  const text = String(value).trim();
  return text.length === 0 ? fallback : text;
}

function formatCitation(source) {
  const parts = [];
  parts.push(normalizeAuthor(source.author));
  parts.push(". (");
  parts.push(normalizeField(source.year, "n.d."));
  parts.push("). ");
  parts.push(normalizeField(source.title, "Untitled"));
  parts.push(". ");
  parts.push(normalizeField(source.publisher, "Self-published"));
  parts.push(".");
  return parts.join("");
}

function cite(sources) {
  if (!Array.isArray(sources)) {
    throw new TypeError("cite expects an array of reference objects");
  }
  return sources.map(formatCitation).join("\n\n");
}

function sortByAuthor(sources) {
  return sources.slice().sort(function (left, right) {
    const a = normalizeAuthor(left.author);
    const b = normalizeAuthor(right.author);
    return a.localeCompare(b);
  });
}

function buildBibliography(title, sources) {
  const heading = normalizeField(title, "References");
  const lines = [heading];
  lines.push("=".repeat(heading.length));
  lines.push("");
  lines.push(cite(sortByAuthor(sources)));
  return lines.join("\n");
}

