const ECHO = "echo ";
const QUOTE = "\"";
const RUNNER = "npm run ";
const NEWLINE = "\n";
const STARTING = "Starting ";
const DONE = "Done";
const SPACE = " ";
const LIST_SEPARATOR = ", ";
const SUMMARY_SEPARATOR = ": ";
const SINGULAR = "task";
const PLURAL = "tasks";
const RULE = "---";
const SAFE_TASK = /^[A-Za-z0-9][A-Za-z0-9:._-]*$/;

function normalizeTask(task) {
  if (typeof task !== "string") {
    throw new TypeError("each task must be a string");
  }
  const trimmed = task.trim();
  if (!SAFE_TASK.test(trimmed)) {
    throw new Error("invalid task name: " + trimmed);
  }
  return trimmed;
}

function echoLine(message) {
  return ECHO + QUOTE + message + QUOTE;
}

function build(tasks) {
  if (!Array.isArray(tasks)) {
    throw new TypeError("tasks must be an array");
  }
  const lines = [SHEBANG, STRICT_MODE];
  for (const task of tasks) {
    const name = normalizeTask(task);
    lines.push(echoLine(STARTING + name));
    lines.push(RUNNER + name);
  }
  lines.push(echoLine(DONE));
  return lines.join(NEWLINE) + NEWLINE;
}

