const SPACES = "  ";
const BRANCH = "|- ";

function label(name) {
  if (name.endsWith("/")) {
    return " (folder)";
  }
  return " (file)";
}

function validateNodes(nodes) {
  if (!Array.isArray(nodes)) {
    throw new TypeError("tree expects an array of nodes");
  }
  for (const node of nodes) {
    if (typeof node.name !== "string" || node.name.length === 0) {
      throw new TypeError("every node needs a non-empty name");
    }
    if (!Number.isInteger(node.depth) || node.depth < 0) {
      throw new RangeError("every node needs a non-negative integer depth");
    }
  }
}

function formatNode(node) {
  if (node.depth === 0) {
    return node.name + label(node.name);
  }
  return SPACES.repeat(node.depth) + BRANCH + node.name + label(node.name);
}

function tree(nodes) {
  validateNodes(nodes);
  return nodes.map(formatNode).join("\n");
}

function parseSpec(text) {
  const nodes = [];
  for (const line of text.split("\n")) {
    const name = line.trim();
    if (name.length === 0) {
      continue;
    }
    const indent = line.length - line.trimStart().length;
    if (indent % SPACES.length !== 0) {
      throw new Error("indentation must be a multiple of two spaces: " + line);
    }
    nodes.push({ name: name, depth: indent / SPACES.length });
  }
  return nodes;
}

function summarize(nodes) {
  let folders = 0;
  let files = 0;
  for (const node of nodes) {
    if (node.name.endsWith("/")) {
      folders += 1;
    } else {
      files += 1;
    }
  }
  const parts = [folders + " folder(s)"];
  parts.push(files + " file(s)");
  return parts.join(", ");
}

const SPEC = [
  "project/",
  "  README.md",
  "  src/",
  "    main.js",
  "    lib/",
  "      parser.js",
  "  test/",
  "    parser.test.js"
].join("\n");

function main() {
  const nodes = parseSpec(SPEC);
  console.log(tree(nodes));
  console.log(summarize(nodes));
}

main();

module.exports = { tree, parseSpec, summarize };

