const FIELD_SEPARATOR = ";";
const SPACE = " ";
const PLUS = "+";

function escapeValue(value) {
  return String(value)
    .replace(/\\/g, "\\\\")
    .replace(/;/g, "\\;")
    .replace(/,/g, "\\,")
    .replace(/\r?\n/g, "\\n");
}

function normalizePhone(raw) {
  const cleaned = String(raw).replace(/[^0-9+]/g, "");
  const digits = cleaned.replace(/\+/g, "");
  if (cleaned.startsWith(PLUS)) {
    return PLUS + digits;
  }
  return digits;
}

function validatePerson(person) {
  const problems = [];
  if (!person || typeof person !== "object") {
    problems.push("person must be an object");
    return problems;
  }
  const fields = [
    "firstName",
    "lastName",
    "email",
    "phone"
  ];
  for (const field of fields) {
    const value = person[field];
    if (typeof value !== "string") {
      problems.push(field + " must be a string");
    } else if (value.trim().length === 0) {
      problems.push(field + " must not be empty");
    }
  }
  const email = person.email;
  if (typeof email === "string" && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email.trim())) {
    problems.push("email is not a valid address");
  }
  return problems;
}

function vcard(person) {
  const problems = validatePerson(person);
  if (problems.length > 0) {
    const details = problems.join("; ");
    throw new Error("Invalid contact: " + details);
  }
  const first = escapeValue(person.firstName.trim());
  const last = escapeValue(person.lastName.trim());
  const parts = [
    "BEGIN:VCARD",
    "VERSION:3.0",
    "N:" + last + FIELD_SEPARATOR + first,
    "FN:" + first + SPACE + last,
    "TEL:" + normalizePhone(person.phone),
    "EMAIL:" + person.email.trim(),
    "END:VCARD"
  ];
  return parts.join(NEWLINE);
}

