const ALLOWED_METHODS = new Set([
  "GET",
  "POST"
]);

const ERROR_STATUS_PREFIXES = "45";

function parseEntry(line) {
  if (typeof line !== "string") {
    throw new TypeError("each log entry must be a string");
  }
  const fields = line.trim().split(" ");
  if (fields.length < 6) {
    throw new Error("malformed log entry: " + line);
  }
  return {
    ip: fields[0],
    method: fields[3],
    path: fields[4],
    status: fields[5]
  };
}

function resultLabel(status) {
  if (ERROR_STATUS_PREFIXES.includes(status.charAt(0))) {
    return "error";
  }
  return "success";
}

function describe(entry) {
  return [
    entry.ip,
    "requested",
    entry.path,
    "with result",
    resultLabel(entry.status)
  ].join(" ");
}

function analyze(logs) {
  if (!Array.isArray(logs)) {
    throw new TypeError("analyze expects an array of log lines");
  }
  const sentences = [];
  logs.forEach(function (line) {
    const entry = parseEntry(line);
    if (ALLOWED_METHODS.has(entry.method)) {
      sentences.push(describe(entry));
    }
  });
  return sentences;
}

function summarize(sentences) {
  const failures = sentences.filter(function (sentence) {
    return sentence.endsWith("error");
  });
  return [
    "described",
    String(sentences.length),
    "requests,",
    String(failures.length),
    "ended in error"
  ].join(" ");
}

