function isFilled(text) {
  if (typeof text !== "string") {
    return false;
  }
  return text.trim().length > 0;
}

function sanitizeKey(key) {
  if (typeof key !== "string") {
    return "";
  }
  return key.trim().replace(/[^A-Za-z0-9_]/g, "_");
}

function formatValue(value) {
  if (value === null || value === undefined) {
    return "NULL";
  }
  const text = String(value);
  if (!isFilled(text)) {
    return "NULL";
  }
  if (/\s/.test(text)) {
    const quote = "\"";
    return quote + text + quote;
  }
  return text;
}

function commentLine(comment) {
  return "# " + comment.trim();
}

function exportLine(key, value) {
  const assignment = key + "=" + formatValue(value);
  return "export " + assignment;
}

function config(settings) {
  if (!Array.isArray(settings)) {
    throw new TypeError("config expects an array of setting objects");
  }
  const lines = [];
  for (const entry of settings) {
    if (entry === null || typeof entry !== "object") {
      continue;
    }
    const key = sanitizeKey(entry.key);
    if (key === "") {
      continue;
    }
    if (isFilled(entry.comment)) {
      lines.push(commentLine(entry.comment));
    }
    lines.push(exportLine(key, entry.value));
  }
  return lines.join("\n");
}

const settings = [
  {
    key: "FOO",
    value: "BAR",
    comment: "Foo, the interesting one"
  },
  {
    key: "",
    value: "BAZ",
    comment: "This entry has no name and is dropped"
  },
  {
    key: "EMPTY",
    value: "  ",
    comment: null
  },
  {
    key: "app path",
    value: "/opt/my app/bin",
    comment: "Spaces are normalised and quoted"
  }
];

