function formatValue(value) {
  if (value === null || value === undefined) {
    return 'NULL';
  }
  const text = String(value);
  if (!isFilled(text)) {
    return 'NULL';
  }
  if (/\s/.test(text)) {
    const quote = '"';
    return quote + text + quote;
  }
  return text;
}

function commentLine(comment) {
  return '# ' + comment.trim();
}

function exportLine(key, value) {
  const assignment = key + '=' + formatValue(value);
  return 'export ' + assignment;
}

function config(settings) {
  if (!Array.isArray(settings)) {
    throw new TypeError('config expects an array of setting objects');
  }
  const lines = [];
  for (const entry of settings) {
    if (entry === null || typeof entry !== 'object') {
      continue;
    }
    const key = sanitizeKey(entry.key);
    if (key === '') {
      continue;
    }
    if (isFilled(entry.comment)) {
      lines.push(commentLine(entry.comment));
    }
    lines.push(exportLine(key, entry.value));
  }
  return lines.join('\n');
}

const settings = [
