  b: "backward",
  l: "left",
  r: "right",
  s: "stop"
};

const ERROR_WORD = "error";

const SEPARATOR = ", ";

const TERMINATOR = ".";

const SPACE = " ";

const DEFAULT_PROGRAMS = [
  "fblrs",
  "ffrb",
  "fbx?s"
];

function isKnown(character) {
  return Object.prototype.hasOwnProperty.call(MOVES, character);
}

function translate(character) {
  return isKnown(character) ? MOVES[character] : ERROR_WORD;
