"use strict";

const NAME_OPEN = "[";
const NAME_CLOSE = "]: ";
const ARROW = " -> ";
const TERMINAL = "end";
const LINE_BREAK = "\n";
const FIELD_SEPARATOR = "|";

function requireString(value, field) {
  if (typeof value !== "string") {
    throw new TypeError("Dialogue node field must be a string: " + field);
  }
  return value;
}

function normalizeNode(node) {
  if (node === null || typeof node !== "object") {
    throw new TypeError("Each dialogue node must be an object");
  }
  const speaker = requireString(node.speaker, "speaker").trim();
  const prompt = requireString(node.prompt, "prompt").trim();
  const rawTarget = node.target === undefined ? "" : node.target;
  const target = requireString(rawTarget, "target").trim();
  if (speaker.length === 0) {
    throw new Error("A dialogue node cannot have an empty speaker");
  }
  return { speaker: speaker, prompt: prompt, target: target };
}

function formatNode(node) {
  const clean = normalizeNode(node);
  const destination = clean.target.length === 0 ? TERMINAL : clean.target;
  return NAME_OPEN + clean.speaker + NAME_CLOSE + clean.prompt + ARROW + destination;
}

function compile(nodes) {
  if (!Array.isArray(nodes)) {
    throw new TypeError("compile expects an array of dialogue nodes");
  }
  return nodes.map(formatNode).join(LINE_BREAK);
}

function parseScript(lines) {
  return lines.map(function (line) {
    const parts = line.split(FIELD_SEPARATOR);
    if (parts.length !== 3) {
      throw new Error("Script line needs speaker, prompt and target: " + line);
    }
    return normalizeNode({ speaker: parts[0], prompt: parts[1], target: parts[2] });
  });
}

function summarize(nodes) {
  const clean = nodes.map(normalizeNode);
  const endings = clean.filter(function (node) {
    return node.target.length === 0;
  });
  const speakers = clean.map(function (node) {
    return node.speaker;
  });
  const unique = speakers.filter(function (name, index) {
    return speakers.indexOf(name) === index;
  });
  const head = clean.length + " nodes, ";
  const middle = unique.length + " speakers, ";
  return head + middle + endings.length + " endings";
}

