const PREFIXES = {
  added: "+ ",
  removed: "- ",
  unchanged: "  ",
  modified: "* "
};

function normalizeType(type) {
  if (typeof type !== "string") {
    throw new TypeError("change type must be a string");
  }
  const key = type.trim().toLowerCase();
  if (!Object.prototype.hasOwnProperty.call(PREFIXES, key)) {
    throw new RangeError("unsupported change type: " + key);
  }
  return key;
}

function patch(changes) {
  if (!Array.isArray(changes)) {
    throw new TypeError("changes must be an array");
  }
  const lines = ["diff output"];
  for (const change of changes) {
    const type = normalizeType(change.type);
    const text = change.line === undefined ? "" : String(change.line);
    lines.push(PREFIXES[type] + text);
  }
  return lines.join("\n");
}

function parseChanges(source) {
  return source.split("\n").map((raw) => {
    if (raw.startsWith("+")) {
      return { type: "added", line: raw.slice(1).trim() };
    }
    if (raw.startsWith("-")) {
      return { type: "removed", line: raw.slice(1).trim() };
    }
    if (raw.startsWith("!")) {
      return { type: "modified", line: raw.slice(1).trim() };
    }
    return { type: "unchanged", line: raw.trim() };
  });
}

function summarize(changes) {
  const counts = { added: 0, removed: 0, unchanged: 0, modified: 0 };
  for (const change of changes) {
    counts[normalizeType(change.type)] += 1;
  }
  const parts = Object.keys(counts).map((key) => key + "=" + counts[key]);
  return parts.join(", ");
}

function main() {
  const source = [
    " function greet(name) {",
    "-  return 'hi ' + name;",
    "+  return `hello ${name}`;",
    "!  // greeting helper",
    " }"
  ].join("\n");
  const changes = parseChanges(source);
  console.log(patch(changes));
  console.log("summary: " + summarize(changes));
}

main();

module.exports = { patch, parseChanges, summarize };

