const HEADER = "#EXTM3U";
const INFO_PREFIX = "#EXTINF:";
const ARTIST_SEPARATOR = " - ";
const UNKNOWN_ARTIST = "Unknown Artist";

function readText(value) {
  if (typeof value === "string") {
    return value.trim();
  }
  return "";
}

function trackLabel(index) {
  return "Track #" + index;
}

function formatDuration(seconds) {
  const total = Math.round(seconds);
  const mins = Math.floor(total / 60);
  const secs = String(total % 60).padStart(2, "0");
  return mins + ":" + secs;
}

function normalizeTrack(track, index) {
  if (track === null || typeof track !== "object") {
    throw new TypeError(trackLabel(index) + " is not an object");
  }
  const title = readText(track.title);
  const artist = readText(track.artist);
  const path = readText(track.path);
  if (title.length === 0) {
    throw new Error(trackLabel(index) + " is missing a title");
  }
  if (path.length === 0) {
    throw new Error(trackLabel(index) + " is missing a path");
  }
  const duration = Number(track.duration);
  if (!Number.isFinite(duration) || duration < 0) {
    throw new Error(trackLabel(index) + " has an invalid duration");
  }
  return {
    title: title,
    artist: artist.length === 0 ? UNKNOWN_ARTIST : artist,
    duration: Math.round(duration),
    path: path
  };
}

function playlist(tracks) {
  if (!Array.isArray(tracks)) {
    throw new TypeError("playlist expects an array of tracks");
  }
  const lines = [HEADER];
  for (let i = 0; i < tracks.length; i += 1) {
    const track = normalizeTrack(tracks[i], i + 1);
    const info = INFO_PREFIX + track.duration;
    const credit = track.artist + ARTIST_SEPARATOR + track.title;
    lines.push(info + "," + credit);
    lines.push(track.path);
  }
  return lines.join("\n");
}

function summarize(tracks) {
  const normalized = tracks.map((track, i) => normalizeTrack(track, i + 1));
  const seconds = normalized.reduce((sum, track) => sum + track.duration, 0);
  let noun = " tracks";
  if (normalized.length === 1) {
    noun = " track";
  }
  return normalized.length + noun + ", total time " + formatDuration(seconds);
}

function main() {
  const tracks = [
    {
      title: "Blue Monday",
      artist: "New Order",
      duration: 448,
      path: "music/blue-monday.mp3"
    },
    {
      title: "Field Recording",
      duration: 92,
      path: "/home/sam/audio/field.flac"
    },
    {
      title: "Teardrop",
      artist: "Massive Attack",
      duration: 330,
      path: "music/teardrop.ogg"
    }
  ];
  console.log(playlist(tracks));
  console.log(summarize(tracks));
}

main();

module.exports = { playlist, summarize, formatDuration };

