"use strict";

function assertWords(words) {
    if (!Array.isArray(words)) {
        throw new TypeError("border expects an array of strings");
    }
    for (const word of words) {
        if (typeof word !== "string") {
            throw new TypeError("every entry must be a string, found " + typeof word);
        }
    }
}

function longestLength(words) {
    return words.reduce((widest, word) => Math.max(widest, word.length), 0);
}

function border(words) {
    assertWords(words);
    const width = longestLength(words);
    const rule = "*".repeat(width + 4);
    const rows = [rule];
    for (const word of words) {
        const padded = word + " ".repeat(width - word.length);
        let line = "* ";
        line += padded;
        line += " *";
        rows.push(line);
    }
    rows.push(rule);
    return rows.join("\n");
}

function readWords(text) {
    if (typeof text !== "string") {
        throw new TypeError("readWords expects a string of text");
    }
    return text
        .split("\n")
        .map((line) => line.trim())
        .filter((line) => line.length > 0);
}

function describe(words) {
    assertWords(words);
    const width = longestLength(words);
    let label = "lines";
    if (words.length === 1) {
        label = "line";
    }
    let summary = words.length + " ";
    summary += label + ", widest ";
    summary += width + " characters";
    return summary;
}

function defaultWords() {
    const sample = [];
    sample.push("Rosetta");
    sample.push("Code");
    sample.push("ASCII borders");
    return sample;
}

function main(argv) {
    const chosen = argv.length > 0 ? argv : defaultWords();
    console.log(border(chosen));
    console.log(describe(chosen));
    const document = "  alpha\n beta \n\n gamma delta \nepsilon";
    const parsed = readWords(document);
    console.log(border(parsed));
    console.log(describe(parsed));
}

module.exports = { border, readWords, describe };

if (require.main === module) {
    main(process.argv.slice(2));
}

