const INSTRUCTIONS = {
  1: "Cook thoroughly before serving",
  2: "Keep refrigerated until use",
  3: "Wash well before chopping",
  4: "Boil in salted water"
};

const CATEGORY_NAMES = {
  1: "meat",
  2: "dairy",
  3: "vegetable",
  4: "grain"
};

function validateEntry(entry, index) {
  if (!Array.isArray(entry) || entry.length !== 2) {
    throw new Error("Malformed ingredient at index " + index);
  }
  const category = entry[0];
  const weight = entry[1];
  if (!Object.prototype.hasOwnProperty.call(INSTRUCTIONS, category)) {
    throw new Error("Unknown food category: " + category);
  }
  if (typeof weight !== "number" || !Number.isFinite(weight) || weight < 0) {
    throw new Error("Weight must be a non-negative number at index " + index);
  }
}

function modify(ingredients) {
  if (!Array.isArray(ingredients)) {
    throw new Error("Ingredient list must be an array");
  }
  const instructions = [];
  let totalWeight = 0;
  const seen = new Set();
  ingredients.forEach(function (entry, index) {
    validateEntry(entry, index);
    instructions.push(INSTRUCTIONS[entry[0]]);
    totalWeight += entry[1];
    seen.add(entry[0]);
  });
  if (totalWeight > 1000) {
    instructions.push("Yields multiple portions");
  }
  if (totalWeight < 500) {
    instructions.push("Single serving size");
  }
  if (!seen.has(1)) {
    instructions.push("Vegetarian friendly meal");
  }
  if (seen.has(1) && seen.has(2)) {
    instructions.push("Rich and heavy dish");
  }
  return instructions;
}

function describeIngredients(ingredients) {
  return ingredients.map(function (entry) {
    const amount = entry[1] + " grams";
    return CATEGORY_NAMES[entry[0]] + ": " + amount;
  }).join(", ");
}

function report(ingredients) {
  const lines = ["Recipe: " + describeIngredients(ingredients)];
  modify(ingredients).forEach(function (step, index) {
    const label = index + 1 + ". ";
    lines.push("  " + label + step);
  });
  return lines.join("\n");
}

function main() {
  const recipes = [[[3, 200], [4, 150]], [[1, 700], [2, 250], [3, 400]]];
  recipes.forEach(function (recipe) {
    console.log(report(recipe));
    console.log("");
  });
}

main();

module.exports = { modify, report, describeIngredients };

