function validateReading(reading, index) {
  const label = "Reading " + index;
  if (!Array.isArray(reading)) {
    throw new TypeError(label + " must be an array");
  }
  if (reading.length !== 3) {
    throw new RangeError(label + " must hold exactly three numbers");
  }
  for (const value of reading) {
    if (typeof value !== "number" || Number.isNaN(value)) {
      throw new TypeError(label + " contains a non numeric value");
    }
  }
}

function plant(seeds) {
  if (!Array.isArray(seeds)) {
    throw new TypeError("seeds must be an array of readings");
  }
  const advice = [];
  seeds.forEach(function (reading, index) {
    validateReading(reading, index);
    const acidity = reading[0];
    const sunlight = reading[1];
    const water = reading[2];
    if (acidity < 6) {
      advice.push("Add lime to soil");
    } else if (acidity > 8) {
      advice.push("Add sulfur to soil");
    }
    if (sunlight < 4) {
      advice.push("Choose shade tolerant varieties");
    } else if (sunlight > 8) {
      advice.push("Ensure frequent watering");
    }
    if (water < 10) {
      advice.push("Install drip irrigation");
    } else if (water > 20) {
      advice.push("Ensure proper drainage");
    }
  });
  if (seeds.length > 5) {
    advice.push("Large garden plot");
  } else if (seeds.length < 3) {
    advice.push("Small container garden");
  }
  return advice;
}

function formatAdvice(advice) {
  if (advice.length === 0) {
    return "  conditions are ideal, no action required";
  }
  return advice
    .map(function (item, index) {
      const bullet = index + 1 + ". ";
      return "  " + bullet + item;
    })
    .join("\n");
}

function buildReport(label, seeds) {
  const advice = plant(seeds);
  const summary = seeds.length + " beds";
  const header = label + ": ";
  const lines = [header + summary];
  lines.push(formatAdvice(advice));
  return lines.join("\n");
}

function main() {
  const plots = [
    ["Back terrace", [[5, 3, 8], [9, 9, 25]]],
    ["Balanced allotment", [[7, 6, 15], [6.5, 5, 12], [8, 7, 18]]],
    ["Community field", [[4, 2, 5], [10, 10, 30], [7, 6, 14], [5, 9, 22], [8, 4, 11], [6, 6, 16]]]
  ];
  for (const entry of plots) {
    console.log(buildReport(entry[0], entry[1]));
    console.log("");
  }
}

main();

