function validate(applicant) {
  if (!Array.isArray(applicant)) {
    throw new TypeError("applicant must be an array of five numbers");
  }
  if (applicant.length !== 5) {
    throw new RangeError("applicant must contain exactly five values");
  }
  applicant.forEach(function (value, index) {
    if (typeof value !== "number" || !Number.isFinite(value)) {
      throw new TypeError("field is not a finite number: index " + index);
    }
    if (value < 0) {
      throw new RangeError("field may not be negative: index " + index);
    }
  });
}

function evaluate(applicant) {
  validate(applicant);
  const score = applicant[0];
  const income = applicant[1];
  const debt = applicant[2];
  const years = applicant[3];
  const inquiries = applicant[4];
  const notes = [];

  if (score < 600) {
    notes.push("High risk profile");
  }
  if (score > 750) {
    notes.push("Excellent credit history");
  }
  if (income < 30000) {
    notes.push("Income does not meet minimum requirements");
  }
  if (income > 100000) {
    notes.push("High income applicant");
  }
  if (debt > income / 2) {
    notes.push("Debt to income ratio too high");
  }
  if (debt === 0) {
    notes.push("No outstanding debt");
  }
  if (years < 1) {
    notes.push("Unstable employment history");
  }
  if (inquiries > 3) {
    notes.push("Too many recent credit requests");
  }

  const approved =
    score > 650 && income > 40000 && debt < income / 3 && years > 2 && inquiries < 2;
  if (approved) {
    notes.push("Application approved");
  } else {
    notes.push("Application requires manual review");
  }
  return notes;
}

function report(label, applicant) {
  const lines = [label + ":"];
  evaluate(applicant).forEach(function (note) {
    lines.push("  - " + note);
  });
  return lines.join("\n");
}

function main() {
  const cases = [
    ["Applicant A", [550, 25000, 15000, 0, 4]],
    ["Applicant B", [780, 120000, 20000, 6, 1]],
    ["Applicant C", [700, 55000, 0, 3, 0]]
  ];
  const sections = cases.map(function (entry) {
    return report(entry[0], entry[1]);
  });
  console.log(sections.join("\n\n"));
}

main();

