const FIELD_LABELS = [
  "hours slept",
  "caffeine cups",
  "screen minutes",
  "exercise minutes"
];

function parseHabits(text) {
  const parts = text.split(",").map(function (piece) {
    return piece.trim();
  });
  if (parts.length !== FIELD_LABELS.length) {
    throw new Error("Expected four comma separated values");
  }
  return parts.map(function (piece, index) {
    const value = Number(piece);
    if (piece === "" || Number.isNaN(value)) {
      throw new Error("Invalid number for " + FIELD_LABELS[index]);
    }
    return value;
  });
}

function assess(habits) {
  const [hours, caffeine, screen, exercise] = habits;
  const notes = [];
  if (hours < 6) {
    notes.push("Consider going to bed earlier");
  }
  if (hours > 9) {
    notes.push("Oversleeping detected");
  }
  if (caffeine > 3) {
    notes.push("Reduce coffee intake");
  }
  if (caffeine === 0) {
    notes.push("Good caffeine management");
  }
  if (screen > 100) {
    notes.push("Limit device usage before bed");
  }
  if (screen < 30) {
    notes.push("Excellent pre sleep routine");
  }
  if (exercise < 20) {
    notes.push("Increase physical activity during the day");
  }
  if (exercise > 60) {
    notes.push("Great daily activity level");
  }
  if (hours >= 7 && hours <= 8 && caffeine < 2 && screen < 60 && exercise > 30) {
    notes.push("Optimal sleep habits");
  }
  return notes;
}

function formatReport(habits, notes) {
  const lines = ["Daily routine assessment"];
  habits.forEach(function (value, index) {
    lines.push(FIELD_LABELS[index] + ": " + value);
  });
  if (notes.length === 0) {
    lines.push("Nothing worth reporting");
  } else {
    notes.forEach(function (note) {
      lines.push("- " + note);
    });
  }
  return lines.join("\n");
}

function main() {
  const samples = [
    "5, 4, 120, 10",
    "7.5, 1, 45, 40",
    "10, 0, 20, 90"
  ];
  samples.forEach(function (sample) {
    const habits = parseHabits(sample);
    console.log(formatReport(habits, assess(habits)));
    console.log("");
  });
}

main();

