const FIELD_NAMES = [
  "distance to city center",
  "building age",
  "room count",
  "plot size"
];

function parseProperty(property) {
  if (!Array.isArray(property) || property.length !== FIELD_NAMES.length) {
    throw new TypeError("A property must be a list of four numbers");
  }
  return property.map(function (raw, index) {
    const number = typeof raw === "string" ? Number(raw.trim()) : raw;
    if (typeof number !== "number" || !Number.isFinite(number)) {
      throw new TypeError(
        "Not a valid number for "
          .concat(FIELD_NAMES[index], ": ")
          .concat(String(raw))
      );
    }
    if (number < 0) {
      throw new RangeError(
        FIELD_NAMES[index].concat(" cannot be negative")
      );
    }
    return number;
  });
}

function value(property) {
  const [distance, age, rooms, plot] = parseProperty(property);
  const observations = [];
  if (distance < 5) {
    observations.push("Prime central location");
  }
  if (distance > 20) {
    observations.push("Suburban or rural setting");
  }
  if (age < 5) {
    observations.push("Modern construction");
  }
  if (age > 50) {
    observations.push("Historic property charm");
  }
  if (rooms < 3) {
    observations.push("Suitable for singles or couples");
  }
  if (rooms > 6) {
    observations.push("Ideal for large families");
  }
  if (plot < 200) {
    observations.push("Low maintenance yard");
  }
  if (plot > 1000) {
    observations.push("Extensive outdoor space");
  }
  if (distance < 10 && age < 10) {
    observations.push("Premium market value expected");
  } else {
    observations.push("Standard market valuation");
  }
  return observations;
}

function describeProperty(property) {
  const values = parseProperty(property);
  const summary = values
    .map(function (number, index) {
      return FIELD_NAMES[index].concat(": ", String(number));
    })
    .join(", ");
  const bullets = value(property).map(function (note) {
    return "  - ".concat(note);
  });
  return [summary].concat(bullets).join("\n");
}

