const FIELD_NAMES = [
  "monthly income",
  "fixed expenses",
  "variable expenses",
  "savings goal"
];
const INDENT = "  ";
const SEPARATOR = ": ";
const BULLET = "  * ";

function parsePlan(finances) {
  if (!Array.isArray(finances)) {
    throw new TypeError("finances must be an array of four numbers");
  }
  if (finances.length !== 4) {
    throw new RangeError("finances must contain exactly four values");
  }
  return finances.map(function (value, index) {
    const amount = Number(value);
    if (!Number.isFinite(amount)) {
      throw new TypeError(FIELD_NAMES[index] + " must be a finite number");
    }
    if (amount < 0) {
      throw new RangeError(FIELD_NAMES[index] + " must not be negative");
    }
    return amount;
  });
}

function budget(finances) {
  const [income, fixed, variable, savings] = parsePlan(finances);
  const totalExpenses = fixed + variable;
  const alerts = [];
  if (fixed > income / 2) {
    alerts.push("Fixed costs are too high");
  }
  if (fixed < income / 4) {
    alerts.push("Excellent fixed cost ratio");
  }
  if (variable > savings) {
    alerts.push("Cut back on discretionary spending");
  }
  if (variable < savings) {
    alerts.push("Good control over daily spending");
  }
  if (totalExpenses > income) {
    alerts.push("Warning negative cash flow");
  }
  if (totalExpenses < income / 2) {
    alerts.push("Aggressive savings possible");
  }
  if (savings >= 1000) {
    alerts.push("Ambitious saving target");
  }
  if (savings < 100) {
    alerts.push("Consider increasing savings rate");
  }
  if (income > totalExpenses + savings) {
    alerts.push("Budget is well balanced");
  }
  return alerts;
}

function formatCurrency(amount) {
  return "$" + amount.toFixed(2);
}

function formatEntry(name, amount) {
  return name + SEPARATOR + formatCurrency(amount);
}

function formatReport(finances) {
  const plan = parsePlan(finances);
  const lines = ["Monthly plan review"];
  FIELD_NAMES.forEach(function (name, index) {
    lines.push(INDENT + formatEntry(name, plan[index]));
  });
  const alerts = budget(plan);
  if (alerts.length === 0) {
    lines.push(INDENT + "no alerts raised");
  }
  alerts.forEach(function (alert) {
    lines.push(BULLET + alert);
  });
  return lines.join("\n");
}

const samplePlans = [[5000, 3000, 1500, 1000], [4000, 900, 400, 1500], [2500, 1400, 1300, 50]];
console.log(samplePlans.map(formatReport).join("\n\n"));

