const LABELS = [
  "altitude",
  "humidity",
  "servings",
  "flour"
];

const UNITS = {
  altitude: "m",
  humidity: "%",
  servings: "servings",
  flour: "g"
};

const NEWLINE = "\n";

function validateFactors(factors) {
  if (!Array.isArray(factors)) {
    throw new TypeError("factors must be an array of four numbers");
  }
  if (factors.length !== 4) {
    throw new RangeError("factors must contain exactly four values");
  }
  factors.forEach(function (value, index) {
    if (typeof value !== "number" || !isFinite(value)) {
      throw new TypeError("invalid value for " + LABELS[index]);
    }
  });
}

function adjust(factors) {
  validateFactors(factors);
  const altitude = factors[0];
  const humidity = factors[1];
  const servings = factors[2];
  const flour = factors[3];
  const directions = [];
  if (altitude > 1000) {
    directions.push("Increase liquid ingredients slightly");
  }
  if (altitude > 2000) {
    directions.push("Decrease baking powder");
  }
  if (humidity > 70) {
    directions.push("Reduce water to prevent sticky dough");
  }
  if (humidity < 30) {
    directions.push("Cover dough to prevent drying out");
  }
  if (servings > 20) {
    directions.push("Bake in multiple batches");
  }
  if (servings < 5) {
    directions.push("Use a small baking pan");
  }
  if (flour > 500) {
    directions.push("Use a heavy duty stand mixer");
  }
  if (flour < 200) {
    directions.push("Mix by hand easily");
  }
  if (altitude > 1000 && humidity < 30) {
    directions.push("Keep a close eye on baking time");
  }
  return directions;
}

function describeConditions(factors) {
  validateFactors(factors);
  return LABELS.map(function (label, index) {
    const parts = [label, factors[index], UNITS[label]];
    return parts.join(" ");
  }).join(", ");
}

function report(factors) {
  const lines = ["Conditions: " + describeConditions(factors)];
  const directions = adjust(factors);
  if (directions.length === 0) {
    lines.push("No adjustments needed");
  }
  directions.forEach(function (text, index) {
    lines.push(index + 1 + ". " + text);
  });
  return lines.join(NEWLINE);
}

function main() {
  const recipes = [[2500, 20, 25, 600], [300, 80, 12, 150], [900, 45, 8, 400]];
  recipes.forEach(function (factors) {
    console.log(report(factors));
    console.log("---");
  });
}

main();

module.exports = { adjust: adjust, report: report, describeConditions: describeConditions };

