function validateSoil(soil) {
  if (!Array.isArray(soil) || soil.length !== 4) {
    throw new TypeError("soil must be a list of four numbers");
  }
  const labels = [
    "clay",
    "sand",
    "silt",
    "organic matter"
  ];
  soil.forEach(function (value, index) {
    if (typeof value !== "number" || Number.isNaN(value)) {
      throw new TypeError(labels[index] + " percentage must be a number");
    }
    if (value < 0 || value > 100) {
      throw new RangeError(labels[index] + " percentage must be within 0 and 100");
    }
  });
  return soil;
}

function analyze(soil) {
  const [clay, sand, silt, organic] = validateSoil(soil);
  const properties = [];
  if (clay > 40) {
    properties.push("Heavy soil requires aeration");
  }
  if (clay < 10) {
    properties.push("Low clay content");
  }
  if (sand > 50) {
    properties.push("Fast draining soil");
  }
  if (sand < 20) {
    properties.push("Poor drainage expected");
  }
  if (silt > 50) {
    properties.push("High erosion risk");
  }
  if (silt <= 20) {
    properties.push("Stable aggregate structure");
  }
  if (organic < 3) {
    properties.push("Incorporate compost immediately");
  }
  if (organic > 10) {
    properties.push("Rich fertile ground");
  }
  if (clay + sand + silt === 100) {
    properties.push("Valid mineral composition");
  } else {
    properties.push("Invalid percentage totals");
  }
  return properties;
}

function formatReport(soil) {
  const mixture = soil.join("/");
  const header = "Sample " + mixture;
  const body = analyze(soil).map(function (item) {
    return "  - " + item;
  });
  return [header].concat(body).join("\n");
}

function main() {
  const samples = [
    [50, 30, 20, 2],
    [5, 60, 35, 12],
    [25, 15, 55, 4]
  ];
  const reports = samples.map(formatReport);
  console.log(reports.join("\n\n"));
}

main();

module.exports = { analyze, validateSoil, formatReport };

