function parseSpec(text) {
  const parts = text.split(",").map((piece) => piece.trim());
  if (parts.length !== 4) {
    throw new Error("A specification needs exactly four numbers");
  }
  return parts.map((piece) => {
    const value = Number(piece);
    if (!Number.isFinite(value)) {
      throw new Error("Invalid numeric component: " + piece);
    }
    return value;
  });
}

