const LABELS = [
  "chlorine",
  "acidity",
  "total alkalinity",
  "calcium hardness"
];

const RANGES = {
  "chlorine": [2, 5],
  "acidity": [7, 8],
  "total alkalinity": [80, 120],
  "calcium hardness": [200, 400]
};

function validate(readings) {
  if (!Array.isArray(readings) || readings.length !== 4) {
    throw new TypeError("readings must be a list of four numbers");
  }
  readings.forEach(function (value, index) {
    if (typeof value !== "number" || !Number.isFinite(value)) {
      throw new TypeError("invalid measurement for " + LABELS[index]);
    }
  });
}

function balance(readings) {
  validate(readings);
  const [chlorine, acidity, alkalinity, calcium] = readings;
  const actions = [];
  if (chlorine < 2) {
    actions.push("Add chlorine shock");
  } else if (chlorine > 5) {
    actions.push("Wait before swimming");
  }
  if (acidity < 7) {
    actions.push("Broadcast soda ash");
  } else if (acidity > 8) {
    actions.push("Pour muriatic acid");
  }
  if (alkalinity < 80) {
    actions.push("Add baking soda");
  } else if (alkalinity > 120) {
    actions.push("Add dry acid");
  }
  if (calcium < 200) {
    actions.push("Dissolve calcium chloride");
  } else if (calcium > 400) {
    actions.push("Partially drain and refill pool");
  }
  if (actions.length === 0) {
    actions.push("Water is perfectly balanced");
  }
  return actions;
}

function statusOf(value, low, high) {
  if (value < low) {
    return "below target";
  }
  if (value > high) {
    return "above target";
  }
  return "normal";
}

function formatReading(label, value) {
  const [low, high] = RANGES[label];
  const target = low + " to " + high;
  const status = statusOf(value, low, high);
  return [label, value, status, target].join(" | ");
}

function describe(readings) {
  validate(readings);
  const lines = readings.map(function (value, index) {
    return formatReading(LABELS[index], value);
  });
  const steps = balance(readings).map(function (action) {
    return "-> " + action;
  });
  return lines.concat(steps).join("\n");
}

const samples = [
  [1, 6, 70, 150],
  [3, 7.5, 95, 280],
  [6, 8.4, 130, 460]
];

console.log(samples.map(describe).join("\n\n"));

module.exports = { balance, describe };

