function parseGuitar(spec) {
  if (typeof spec === "string") {
    spec = spec.split(",").map(function (part) {
      return Number(part.trim());
    });
  }
  if (!Array.isArray(spec)) {
    throw new TypeError("guitar must be an array or a comma separated string");
  }
  if (spec.length !== 4) {
    throw new RangeError("guitar must hold exactly four measurements");
  }
  spec.forEach(function (value, index) {
    if (typeof value !== "number" || !isFinite(value)) {
      throw new TypeError(`measurement ${index} is not a finite number`);
    }
  });
  return spec;
}

function select(guitar) {
  const [scale, tuning, strength, wear] = parseGuitar(guitar);
  const suggestions = [];
  if (scale < 24) {
    suggestions.push("Use thicker strings for tension");
  }
  if (scale > 26) {
    suggestions.push("Consider lighter gauge strings");
  }
  if (tuning < 0) {
    suggestions.push("Heavy bottom strings needed");
  }
  if (tuning > 0) {
    suggestions.push("Extra light strings required");
  }
  if (strength < 5) {
    suggestions.push("Low tension silk and steel");
  }
  if (strength > 8) {
    suggestions.push("High tension bronze");
  }
  if (wear > 7) {
    suggestions.push("Use flatwound strings to reduce wear");
  }
  if (wear < 3) {
    suggestions.push("Roundwound strings are fine");
  }
  if (strength > 8 && tuning < 0) {
    suggestions.push("Custom hybrid set recommended");
  }
  return suggestions;
}

function describe(guitar) {
  const suggestions = select(guitar);
  const header = parseGuitar(guitar).join(" / ");
  if (suggestions.length === 0) {
    return `${header}: a standard factory set will do`;
  }
  const lines = suggestions.map(function (line) {
    return `  - ${line}`;
  });
  return `${header}:\n${lines.join("\n")}`;
}

function main() {
  const workshop = [[23, -1, 9, 8], [25, 0, 6, 5], "27, 1, 3, 2"];
  workshop.forEach(function (guitar) {
    console.log(describe(guitar));
  });
  try {
    select([25, 0, 6]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { select: select, describe: describe, parseGuitar: parseGuitar };

