    throw new TypeError("weather must be an array of four numbers");
  }
  if (weather.length !== 4) {
    throw new RangeError("weather must contain exactly four readings");
  }
  const labels = [
    "cloud cover",
    "seeing",
    "moon phase",
    "light pollution"
  ];
  weather.forEach((value, index) => {
    if (typeof value !== "number" || Number.isNaN(value)) {
      throw new TypeError("invalid reading for " + labels[index]);
    }
  });
  return weather;
}

function observe(weather) {
  const [clouds, seeing, moon, pollution] = validate(weather);
  const notes = [];
  if (clouds > 50) {
    notes.push("Too cloudy for observation");
  }
  if (clouds < 10) {
    notes.push("Clear skies for astronomy");
  }
  if (seeing < 4) {
    notes.push("Poor atmospheric stability");
  }
  if (seeing > 8) {
    notes.push("Crisp planetary views possible");
  }
  if (moon > 10) {
    notes.push("Moonlight will wash out deep sky objects");
  }
  if (moon < 4) {
    notes.push("Dark sky ideal for galaxies");
  }
  if (pollution > 7) {
    notes.push("Use narrowband filters");
  }
  if (pollution < 3) {
    notes.push("Pristine dark sky site");
  }
  if (clouds < 10 && seeing > 8 && moon < 4 && pollution < 3) {
    notes.push("Perfect night for astrophotography");
  }
  return notes;
}

