  const [clouds, seeing, moon, pollution] = validate(weather);
  const parts = [
    "clouds " + clouds,
    "seeing " + seeing,
    "moon day " + moon,
    "pollution " + pollution
  ];
  return parts.join(", ");
}

function report(weather) {
  const notes = observe(weather);
  const header = "Site conditions: " + describe(weather);
  const body = notes.length === 0 ? ["Nothing remarkable tonight"] : notes;
  const lines = body.map((note) => "  - " + note);
