const CHANNELS = [
  "red",
  "blue",
  "yellow",
  "white"
];

function validate(colors) {
  if (!Array.isArray(colors)) {
    throw new TypeError("mix expects an array of color amounts");
  }
  if (colors.length !== CHANNELS.length) {
    throw new RangeError("mix expects exactly four color amounts");
  }
  colors.forEach((amount) => {
    if (typeof amount !== "number" || Number.isNaN(amount)) {
      throw new TypeError("every color amount must be a number");
    }
    if (amount < 0 || amount > 100) {
      throw new RangeError("every color amount must lie between 0 and 100");
    }
  });
}

function mix(colors) {
  validate(colors);
  const [red, blue, yellow, white] = colors;
  const results = [];
  if (red > 50 && blue > 50) {
    results.push("Produces a dark purple");
  }
  if (red > 50 && yellow > 50) {
    results.push("Produces a bright orange");
  }
  if (blue > 50 && yellow > 50) {
    results.push("Produces a vibrant green");
  }
  if (red > 50 && blue > 50 && yellow > 50) {
    results.push("Results in a muddy brown");
  }
  if (red < 10 && blue < 10) {
    results.push("Lacks cool tones");
  }
  if (white > 80) {
    results.push("Creates a very pale pastel");
  }
  if (white < 10) {
    results.push("Deep saturated color");
  }
  if (red === 0 && blue === 0 && yellow === 0) {
    results.push("Pure white paint");
  }
  if (blue > 0 && red === 0 && yellow === 0) {
    results.push("Monochromatic blue scheme");
  }
  return results;
}

function describe(colors) {
  const parts = colors.map((amount, index) => CHANNELS[index] + "=" + amount);
  return parts.join(", ");
}

function report(colors) {
  const results = mix(colors);
  const lines = ["Mixture: " + describe(colors)];
  if (results.length === 0) {
    lines.push("  (no notable reaction)");
  }
  results.forEach((result) => lines.push("  - " + result));
  return lines.join("\n");
}

