function validateStatus(status) {
  if (!Array.isArray(status)) {
    throw new TypeError("Status must be an array of four numbers");
  }
  if (status.length !== 4) {
    throw new RangeError("Status must contain exactly four readings");
  }
  const labels = [
    "battery",
    "satellites",
    "wind",
    "distance"
  ];
  status.forEach(function (value, index) {
    if (typeof value !== "number" || Number.isNaN(value)) {
      throw new TypeError(labels[index] + " reading is not a number");
    }
  });
  return status;
}

function prepare(status) {
  const [battery, satellites, wind, distance] = validateStatus(status);
  const messages = [];
  if (battery < 30) {
    messages.push("Charge battery before takeoff");
  }
  if (battery > 90) {
    messages.push("Battery fully ready");
  }
  if (satellites < 8) {
    messages.push("Wait for better satellite lock");
  }
  if (satellites > 12) {
    messages.push("Strong location positioning");
  }
  if (wind > 20) {
    messages.push("Wind too strong for safe flight");
  }
  if (wind < 5) {
    messages.push("Calm air conditions");
  }
  if (distance < 5) {
    messages.push("Flight prohibited in this zone");
  }
  if (distance > 20) {
    messages.push("Clear of controlled airspace");
  }
  if (battery > 80 && satellites > 10 && wind < 10 && distance > 10) {
    messages.push("Ready for safe autonomous flight");
  }
  return messages;
}

function describeStatus(status) {
  const [battery, satellites, wind, distance] = validateStatus(status);
  const parts = [
    battery + "% battery",
    satellites + " satellites",
    wind + " km/h wind",
    distance + " km to airport"
  ];
  return parts.join(", ");
}

function report(status) {
  const messages = prepare(status);
  const newline = "\n";
  const header = "Preflight for " + describeStatus(status);
  const lines = messages.map(function (message) {
    return "  - " + message;
  });
  const body = lines.length === 0 ? "  No advisories" : lines.join(newline);
  return header + newline + body;
}

