const READING_SEPARATOR = ", ";
const HEADING_SEPARATOR = ": ";
const NEWLINE = "\n";
const INDENT = "  ";
const BULLET = "  - ";
const ON_TRACK = "Fermentation is on track";

const READING_LABELS = [
  "temperature",
  "yeast",
  "hydration",
  "resting time"
];

function validateDough(dough) {
  if (!Array.isArray(dough)) {
    throw new TypeError("dough must be an array of four numbers");
  }
  if (dough.length !== READING_LABELS.length) {
    throw new RangeError("dough must contain exactly four readings");
  }
  dough.forEach(function (value, index) {
    if (typeof value !== "number" || !Number.isFinite(value)) {
      throw new TypeError(READING_LABELS[index] + " must be a finite number");
    }
  });
  return dough;
}

function ferment(dough) {
  const [temperature, yeast, hydration, resting] = validateDough(dough);
  const updates = [];
  if (temperature < 18) {
    updates.push("Fermentation will be sluggish");
  }
  if (temperature > 28) {
    updates.push("Watch for overproofing");
  }
  if (yeast < 2) {
    updates.push("Requires a long cold proof");
  }
  if (yeast > 5) {
    updates.push("Fast rise expected");
  }
  if (hydration < 60) {
    updates.push("Stiff dough for shaping");
  }
  if (hydration > 80) {
    updates.push("Sticky dough requires folding");
  }
  if (resting < 2) {
    updates.push("Insufficient gluten development");
  }
  if (resting > 12) {
    updates.push("Complex flavors developed");
  }
  if (temperature > 25 && yeast > 4) {
    updates.push("Punch down dough soon");
  }
  return updates;
}

function describeBatch(name, dough) {
  const updates = ferment(dough);
  const heading = name + HEADING_SEPARATOR + dough.join(READING_SEPARATOR);
  if (updates.length === 0) {
    return heading + NEWLINE + INDENT + ON_TRACK;
  }
  const bullets = updates.map(function (update) {
    return BULLET + update;
  });
  return heading + NEWLINE + bullets.join(NEWLINE);
}

function main() {
  const batches = [
    ["Cold rye", [15, 1, 55, 1]],
    ["Summer ciabatta", [30, 6, 85, 14]],
    ["Overnight sourdough", [26, 4.5, 72, 10]],
    ["Standard loaf", [22, 3, 65, 4]]
  ];
  const report = batches.map(function (entry) {
    return describeBatch(entry[0], entry[1]);
  });
  console.log(report.join(NEWLINE + NEWLINE));
}

main();

