function validateRecord(record) {
    if (!Array.isArray(record)) {
        throw new TypeError("Record must be an array");
    }
    if (record.length !== 3) {
        throw new Error("Record must have exactly three fields");
    }
    if (typeof record[0] !== "string") {
        throw new TypeError("Name must be a string");
    }
    if (typeof record[1] !== "string") {
        throw new TypeError("Email must be a string");
    }
    if (typeof record[2] !== "number") {
        throw new TypeError("Age must be a number");
    }
}

function escapeString(str) {
    const quote = "'";
    const doubleQuoteEscaped = "''";
    return str.split(quote).join(doubleQuoteEscaped);
}

function buildInsertStatement(name, email, age) {
    const prefix = "insert into users values (";
    const singleQuote = "'";
    const commaSpace = ", ";
    const suffix = ");";

    let stmt = prefix;
    stmt += singleQuote;
    stmt += escapeString(name);
    stmt += singleQuote;
    stmt += commaSpace;
    stmt += singleQuote;
    stmt += escapeString(email);
    stmt += singleQuote;
    stmt += commaSpace;
    stmt += age;
    stmt += suffix;

    return stmt;
}

function insert(records) {
    if (!Array.isArray(records)) {
        throw new TypeError("Records must be an array");
    }

    const statements = [];

    for (let i = 0; i < records.length; i++) {
        const record = records[i];
        validateRecord(record);

        const name = record[0];
        const email = record[1];
        const age = record[2];

        const stmt = buildInsertStatement(name, email, age);
        statements.push(stmt);
    }

    return statements;
}

