const TAG_PATTERN = /\[(\/?)(b|i|u|quote)\]/gi;

function openTagFor(name) {
  switch (name) {
    case "b":
      return "<strong>";
    case "i":
      return "<em>";
    case "u":
      return "<span style=\"text-decoration: underline;\">";
    case "quote":
      return "<blockquote>";
    default:
      throw new Error("unsupported forum tag: " + name);
  }
}

function closeTagFor(name) {
  switch (name) {
    case "b":
      return "</strong>";
    case "i":
      return "</em>";
    case "u":
      return "</span>";
    case "quote":
      return "</blockquote>";
    default:
      throw new Error("unsupported closing forum tag: " + name);
  }
}

function format(posts) {
  if (!Array.isArray(posts)) {
    throw new TypeError("format expects an array of forum posts");
  }
  return posts.map(function (post, index) {
    if (typeof post !== "string") {
      const where = "post at index " + index;
      throw new TypeError(where + " is not a text string");
    }
    return post.replace(TAG_PATTERN, function (match, slash, name) {
      const tag = name.toLowerCase();
      return slash === "/" ? closeTagFor(tag) : openTagFor(tag);
    });
  });
}

function report(posts) {
  const converted = format(posts);
  const lines = converted.map(function (html, index) {
    const label = "post " + (index + 1);
    return label + ": " + html;
  });
  return lines.join("\n");
}

function main() {
  const posts = [
    "This is [b]bold[/b]",
    "Some [i]italic[/i] and some [u]underlined[/u] text",
    "[quote]I never said that[/quote] -- anonymous",
    "Nested markup: [b]very [i]strongly[/i] stated[/b]",
    "Tags may be written as [B]uppercase[/B] too",
    "Unmatched brackets such as [code] stay untouched"
  ];
  console.log(report(posts));
}

main();

module.exports = { format: format, report: report };

