const HEADER = "DATA START";
const FOOTER = "DATA END";
const FIELD_SEPARATOR = " | ";
const ROW_SEPARATOR = "\n";
const STRING_WRAPPER = "**";

function formatValue(value) {
  if (value === true) {
    return "YES";
  }
  if (value === false) {
    return "NO";
  }
  if (value === null) {
    return "EMPTY";
  }
  if (typeof value === "string") {
    return STRING_WRAPPER + value + STRING_WRAPPER;
  }
  if (typeof value === "number" && Number.isFinite(value)) {
    return String(value);
  }
  throw new TypeError("unsupported value in row: " + String(value));
}

function formatRow(row) {
  if (!Array.isArray(row)) {
    throw new TypeError("each row must be an array");
  }
  return row.map(formatValue).join(FIELD_SEPARATOR);
}

function kindOf(value) {
  if (value === null) {
    return "empty";
  }
  if (typeof value === "boolean") {
    return "flag";
  }
  if (typeof value === "string") {
    return "text";
  }
  return "number";
}

function summarize(rows) {
  const counts = {};
  rows.forEach(function (row) {
    row.forEach(function (value) {
      const kind = kindOf(value);
      counts[kind] = (counts[kind] || 0) + 1;
    });
  });
  const parts = Object.keys(counts).sort().map(function (kind) {
    return kind + "=" + counts[kind];
  });
  return parts.join(", ");
}

const exporter = {
  export: function (rows) {
    if (!Array.isArray(rows)) {
      throw new TypeError("rows must be an array of arrays");
    }
    const body = rows.map(formatRow).join(ROW_SEPARATOR);
    return HEADER + ROW_SEPARATOR + body + ROW_SEPARATOR + FOOTER;
  }
};

const sampleRows = [
  [true, null, "text"],
  [false, 42, "hello world"],
  [null, true, -3.5, "last field"]
];

console.log(exporter.export(sampleRows));
console.log("summary: " + summarize(sampleRows));

module.exports = { exporter: exporter, formatValue: formatValue, summarize: summarize };

