const DAY_NAMES = [
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
  "Sunday"
];

const DAYS_PER_WEEK = DAY_NAMES.length;

function assertInteger(value, label) {
  if (!Number.isInteger(value)) {
    throw new TypeError(label + " must be an integer");
  }
}

function assertRange(value, label, low, high) {
  if (value < low || value > high) {
    throw new RangeError(label + " is out of range");
  }
}

function headerRow() {
  return DAY_NAMES.join("|");
}

function alignmentRow() {
  return DAY_NAMES.map(function () {
    return "---";
  }).join("|");
}

function calendar(start, days) {
  assertInteger(start, "start");
  assertRange(start, "start", 0, DAYS_PER_WEEK - 1);
  assertInteger(days, "days");
