const HEADER_TEXT = "TOP SCORES";
const SEPARATOR = " - ";
const GAP = " ";

function medalPrefix(index) {
  if (index === 0) {
    return "GOLD MEDAL";
  }
  if (index === 1) {
    return "SILVER MEDAL";
  }
  if (index === 2) {
    return "BRONZE MEDAL";
  }
  if (index < 5) {
    return "HONORABLE MENTION";
  }
  return "RANK " + (index + 1);
}

function validatePlayers(players) {
  if (!Array.isArray(players)) {
    throw new TypeError("scoreboard expects an array of [name, score] pairs");
  }
  return players.map(function (entry) {
    const name = Array.isArray(entry) ? entry[0] : undefined;
    const score = Array.isArray(entry) ? entry[1] : undefined;
    if (typeof name !== "string" || name.trim().length === 0) {
      throw new TypeError("every player needs a non-empty name");
    }
    if (typeof score !== "number" || !Number.isFinite(score)) {
      throw new TypeError("every player needs a finite numeric score");
    }
    return { name: name.trim(), score: score };
  });
}

function formatPoints(score) {
  const grouped = String(Math.trunc(score)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  return grouped + " points";
}

function headerLine(width) {
  const room = Math.max(width - HEADER_TEXT.length - 2, 2);
  const left = "*".repeat(Math.ceil(room / 2));
  const right = "*".repeat(Math.floor(room / 2));
  return left + GAP + HEADER_TEXT + GAP + right;
}

function scoreboard(players) {
  const roster = validatePlayers(players);
  const body = roster.map(function (player, index) {
    const label = medalPrefix(index) + GAP;
    return label + player.name + SEPARATOR + formatPoints(player.score);
  });
  const width = body.reduce(function (widest, line) {
    return Math.max(widest, line.length);
  }, HEADER_TEXT.length + 4);
  return [headerLine(width)].concat(body);
}

function main() {
  const players = [
    ["Aurora", 128450],
    ["Basil", 99120],
    ["Cressida", 87005],
    ["Dmitri", 64300],
    ["Elowen", 51990],
    ["Fenwick", 43110],
    ["Giselle", 22075]
  ];
  console.log(scoreboard(players).join("\n"));
}

main();

module.exports = { scoreboard: scoreboard, medalPrefix: medalPrefix };

