const ADVICE = {
  cardio: "keep your heart rate up",
  strength: "lift heavy",
  flexibility: "stretch deeply",
  balance: "stay focused"
};

const REST_PHRASE = "take a day off";
const FIELD_SEPARATOR = "|";

function capitalizeDay(day) {
  const trimmed = String(day).trim();
  if (trimmed.length === 0) {
    throw new Error("a routine entry is missing its day name");
  }
  return trimmed[0].toUpperCase() + trimmed.slice(1).toLowerCase();
}

function normalizeType(type) {
  return String(type).trim().toLowerCase();
}

function describeLine(day, type, exercise) {
  const name = capitalizeDay(day);
  const label = name + ":";
  if (type === "rest") {
    return [label, REST_PHRASE].join(" ");
  }
  const advice = ADVICE[type];
  if (advice === undefined) {
    throw new Error("unknown activity type: " + type);
  }
  const move = String(exercise).trim();
  if (move.length === 0) {
    throw new Error(name + " needs an exercise name");
  }
  return [label, move, advice].join(" ");
}

function workout(routines) {
  if (!Array.isArray(routines)) {
    throw new TypeError("workout expects a list of routine arrays");
  }
  const lines = routines.map(function (entry) {
    if (!Array.isArray(entry) || entry.length < 2) {
      throw new TypeError("each routine needs a day and an activity type");
    }
    const type = normalizeType(entry[1]);
    return describeLine(entry[0], type, entry.length > 2 ? entry[2] : "");
  });
  return lines.join("\n");
}

function parseRoutines(records) {
  return records.map(function (record) {
    return record.split(FIELD_SEPARATOR).map(function (field) {
      return field.trim();
    });
  });
}

function countActive(routines) {
  return routines.filter(function (entry) {
    return normalizeType(entry[1]) !== "rest";
  }).length;
}

const WEEK_PLAN = [
  "monday | cardio | morning run",
  "tuesday | strength | deadlifts",
  "wednesday | flexibility | yoga flow",
  "thursday | balance | single-leg stands",
  "friday | strength | bench press",
  "saturday | cardio | cycling",
  "sunday | rest"
];

const week = parseRoutines(WEEK_PLAN);
console.log(workout(week));
console.log("Active training days: " + countActive(week));

module.exports = { workout, describeLine, parseRoutines, countActive };

