const SEPARATOR = ",";
const FIELD_SEPARATOR = "|";

function coerceDefault(raw) {
  if (raw === "true") {
    return true;
  }
  if (raw === "false") {
    return false;
  }
  if (/^-?\d+(\.\d+)?$/.test(raw)) {
    return Number(raw);
  }
  if (raw.includes(SEPARATOR)) {
    return raw.split(SEPARATOR).map((item) => item.trim());
  }
  return raw;
}

function parseFlagSpec(spec) {
  const parts = spec.split(FIELD_SEPARATOR);
  if (parts.length !== 4) {
    throw new SyntaxError("spec must hold four pipe separated fields: " + spec);
  }
  const raw = parts[3].trim();
  const defaultValue = raw.length === 0 ? null : coerceDefault(raw);
  return [parts[0].trim(), parts[1].trim(), parts[2].trim(), defaultValue];
}

function formatDefault(value) {
  if (Array.isArray(value)) {
    return value.join(SEPARATOR);
  }
  return String(value);
}

function validateFlag(flag, index) {
  const position = " at index " + index;
  if (!Array.isArray(flag) || flag.length !== 4) {
    throw new TypeError("flag must be an array of four items" + position);
  }
  const [short, long, description] = flag;
  if (typeof short !== "string" || short.length !== 1) {
    throw new TypeError("short flag must be a single letter" + position);
  }
  if (typeof long !== "string" || long.length === 0) {
    throw new TypeError("long flag must be a non-empty word" + position);
  }
  if (typeof description !== "string") {
    throw new TypeError("description must be text" + position);
  }
}

function formatFlagLine(flag) {
  const [short, long, description, defaultValue] = flag;
  let line = "  -" + short;
  line += ", --" + long;
  line += " " + description;
  if (defaultValue !== null && defaultValue !== undefined) {
    line += " [default: " + formatDefault(defaultValue);
    line += "]";
  }
  return line;
}

function help(flags) {
  if (!Array.isArray(flags)) {
    throw new TypeError("flags must be a list of flag arrays");
  }
  flags.forEach(validateFlag);
  const lines = ["USAGE options"];
  for (const flag of flags) {
    lines.push(formatFlagLine(flag));
  }
  return lines.join("\n");
}

function main() {
  const specs = [
    "h|help|Show this help text and exit|",
    "v|verbose|Print progress for every processed file|false",
    "o|output|Write the generated report to this path|report.txt",
    "j|jobs|Number of worker threads to start|4",
    "t|tags|Tags to include when scanning sources|all,changed"
  ];
  console.log(help(specs.map(parseFlagSpec)));
}

main();

