const HEADER = "PORTFOLIO SUMMARY";
const LINE_BREAK = "\n";
const FIELD_GAP = " ";
const GAIN_LABEL = "UP PROFIT";
const LOSS_LABEL = "DOWN LOSS";
const EVEN_LABEL = "FLAT BREAKEVEN";
const NET_GAIN_LABEL = "NET GAIN";
const NET_LOSS_LABEL = "NET LOSS";
const NET_FLAT_LABEL = "NET FLAT";
const ARGUMENT_DELIMITER = ":";

function parseEntry(entry) {
  if (!Array.isArray(entry) || entry.length !== 3) {
    throw new TypeError("each stock must be [ticker, buyPrice, currentPrice]");
  }
  const ticker = String(entry[0]).trim().toUpperCase();
  if (ticker.length === 0) {
    throw new TypeError("ticker symbol must not be empty");
  }
  const buy = Number(entry[1]);
  const current = Number(entry[2]);
  if (!Number.isFinite(buy) || !Number.isFinite(current)) {
    throw new TypeError(
      "prices must be finite numbers for "
      + ticker
    );
  }
  return { ticker, buy, current };
}

function formatAmount(value) {
  const rounded = Math.round(Math.abs(value) * 100) / 100;
  return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(2);
}

function describe(entry) {
  const { ticker, buy, current } = parseEntry(entry);
  const difference = current - buy;
  if (difference > 0) {
    return [ticker, GAIN_LABEL, formatAmount(difference)].join(FIELD_GAP);
  }
  if (difference < 0) {
    return [ticker, LOSS_LABEL, formatAmount(difference)].join(FIELD_GAP);
  }
  return [ticker, EVEN_LABEL].join(FIELD_GAP);
}

function portfolio(stocks) {
  if (!Array.isArray(stocks)) {
    throw new TypeError("portfolio expects a list of stock entries");
  }
  const body = stocks.map(describe).join(LINE_BREAK);
  return HEADER + LINE_BREAK + body;
}

function netChange(stocks) {
  return stocks.reduce((total, entry) => {
    const { buy, current } = parseEntry(entry);
    return total + (current - buy);
  }, 0);
}

function report(stocks) {
  const net = netChange(stocks);
  if (net === 0) {
    return portfolio(stocks) + LINE_BREAK + NET_FLAT_LABEL;
  }
  const label = net > 0 ? NET_GAIN_LABEL : NET_LOSS_LABEL;
  const footer = [label, formatAmount(net)].join(FIELD_GAP);
  return portfolio(stocks) + LINE_BREAK + footer;
}

function main(argv) {
  const stocks = argv.map((text) => text.split(ARGUMENT_DELIMITER));
  return report(stocks);
}

if (require.main === module) {
  process.stdout.write(main(process.argv.slice(2)) + LINE_BREAK);
}

module.exports = { portfolio, report, netChange, describe, formatAmount, main };

