const UNIT_ABBREVIATIONS = {
  grams: "g",
  kilograms: "kg",
  milliliters: "ml",
  liters: "L",
  pieces: ""
};

const WHITESPACE = /\s+/;
const TRAILING_ZEROS = /0+$/;
const TRAILING_DOT = /\.$/;

function normalizeUnit(unit) {
  const key = String(unit).trim().toLowerCase();
  if (Object.prototype.hasOwnProperty.call(UNIT_ABBREVIATIONS, key)) {
    return UNIT_ABBREVIATIONS[key];
  }
  return key;
}

function formatQuantity(quantity) {
  if (typeof quantity !== "number" || Number.isNaN(quantity)) {
    throw new TypeError("quantity must be a number");
  }
  if (Number.isInteger(quantity)) {
    return String(quantity);
  }
  const fixed = quantity.toFixed(2);
  const withoutZeros = fixed.replace(TRAILING_ZEROS, "");
  return withoutZeros.replace(TRAILING_DOT, "");
}

function recipe(ingredients) {
  if (!Array.isArray(ingredients)) {
    throw new TypeError("ingredients must be an array");
  }
  return ingredients.map(function (entry) {
    if (!Array.isArray(entry) || entry.length !== 3) {
      throw new TypeError("each ingredient needs a quantity, a unit and a name");
    }
    const quantity = formatQuantity(entry[0]);
    const unit = normalizeUnit(entry[1]);
    const name = String(entry[2]).trim();
    if (name === "") {
      throw new Error("ingredient name must not be empty");
    }
    const checkbox = "- [ ] " + quantity + unit;
    return [checkbox, name].join(" ");
  });
}

function parseIngredient(text) {
  const parts = String(text).trim().split(WHITESPACE);
  if (parts.length < 3) {
    throw new Error("expected a quantity, a unit and a name in: " + text);
  }
  const quantity = Number(parts[0]);
  if (Number.isNaN(quantity)) {
    throw new Error("quantity is not numeric: " + parts[0]);
  }
  const name = parts.slice(2).join(" ");
  return [quantity, parts[1], name];
}

function shoppingList(title, ingredients) {
  const heading = "## " + String(title).trim();
  return [heading].concat(recipe(ingredients));
}

function main() {
  const lines = [
    "250 grams flour",
    "1.5 kilograms potatoes",
    "300 milliliters milk",
    "0.5 liters water",
    "3 pieces eggs",
    "1 tablespoon brown sugar"
  ];
  shoppingList("Pancake batter", lines.map(parseIngredient)).forEach(function (line) {
    console.log(line);
  });
}

main();

module.exports = { recipe, shoppingList, parseIngredient, normalizeUnit, formatQuantity };

