const STEP_ONE = "Step one: Place the main board in the center of the table.";
const STEP_TWO = "Step two: Shuffle the encounter deck and deal three cards.";

const ALLOCATIONS = {
  2: {
    gold: "fifty",
    tokens: "two"
  },
  3: {
    gold: "forty",
    tokens: "three"
  },
  4: {
    gold: "thirty",
    tokens: "four"
  }
};

function validatePlayers(players) {
  if (!Number.isInteger(players)) {
    throw new TypeError("The number of players must be an integer, received: " + players);
  }
  if (!Object.prototype.hasOwnProperty.call(ALLOCATIONS, players)) {
    throw new RangeError("This game supports only two, three or four players, received: " + players);
  }
  return players;
}

function thirdStep(players) {
  const allocation = ALLOCATIONS[players];
  const opening = "Step three: Give each player ";
  const connector = " gold coins and ";
  const ending = " tokens.";
  return opening + allocation.gold + connector + allocation.tokens + ending;
}

function setup(players) {
  validatePlayers(players);
  return [STEP_ONE, STEP_TWO, thirdStep(players)];
}

function numberedLines(steps) {
  const bullet = "  - ";
  return steps.map(function (step) {
    return bullet + step;
  });
}

function formatGuide(players) {
  const steps = setup(players);
  const header = "Setup guide for players: " + players;
  const lines = [header].concat(numberedLines(steps));
  return lines.join("\n");
}

function main() {
  const supported = Object.keys(ALLOCATIONS).map(Number);
  const guides = supported.map(formatGuide);
  console.log(guides.join("\n\n"));
}

if (require.main === module) {
  main();
}

module.exports = { setup, formatGuide };

