function classifyDepth(depth) {
  if (depth < 0) {
    return "above sea level";
  }
  if (depth === 0) {
    return "ocean surface";
  }
  if (depth < 200) {
    return "epipelagic";
  }
  if (depth < 1000) {
    return "mesopelagic";
  }
  if (depth < 4000) {
    return "bathypelagic";
  }
  if (depth < 6000) {
    return "abyssopelagic";
  }
  if (depth < 10000) {
    return "hadalpelagic";
  }
  return "trench bottom";
}

function parseDepth(value) {
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new RangeError("depth must be a finite number of meters");
    }
    return value;
  }
  if (typeof value === "string") {
    const cleaned = value.trim().replace(/\s*m(eters)?$/i, "");
    const parsed = Number(cleaned);
    if (cleaned.length === 0 || Number.isNaN(parsed)) {
      throw new TypeError("cannot read a depth from " + JSON.stringify(value));
    }
    return parsed;
  }
  throw new TypeError("depth must be a number or a numeric string");
}

function locate(depths) {
  if (!Array.isArray(depths)) {
    throw new TypeError("locate expects a list of depth values");
  }
  return depths.map(function (entry) {
    return classifyDepth(parseDepth(entry));
  });
}

function describeDistance(meters) {
  if (meters < 0) {
    return Math.abs(meters) + " m up";
  }
  return meters + " m down";
}

function formatReport(depths) {
  const zones = locate(depths);
  return depths
    .map(function (entry, index) {
      const label = describeDistance(parseDepth(entry));
      return label.padEnd(14) + zones[index];
    })
    .join("\n");
}

function main() {
  const samples = [-15, 0, 50, 999, 5200, 11000];
  samples.push("200");
  samples.push("3500 m");
  samples.push("9500 meters");
  console.log(formatReport(samples));
  const tally = locate(samples).reduce(function (counts, zone) {
    counts[zone] = (counts[zone] || 0) + 1;
    return counts;
  }, {});
  console.log("zones visited: " + Object.keys(tally).length);
  Object.keys(tally).forEach(function (zone) {
    console.log(zone + ": " + tally[zone]);
  });
}

main();

