const PAPER_GRADES = [
  { limit: 35, name: "tissue paper" },
  { limit: 55, name: "newsprint paper" },
  { limit: 90, name: "text paper" },
  { limit: 120, name: "heavy text" },
  { limit: 150, name: "light cardstock" },
  { limit: 200, name: "medium cardstock" },
  { limit: 300, name: "heavyweight cover" }
];

const HEAVIEST_GRADE = "rigid board";
const UNIT_SUFFIX = /\s*(?:gsm|g\/m2|g\/m²)$/i;
const NEWLINE = "\n";

function parseGrammage(value) {
  if (typeof value === "number") {
    return value;
  }
  if (typeof value !== "string") {
    throw new TypeError("weight must be a number or a numeric string");
  }
  const cleaned = value.trim().replace(UNIT_SUFFIX, "");
  const parsed = Number(cleaned);
  if (cleaned.length === 0 || Number.isNaN(parsed)) {
    throw new Error("unrecognised weight: " + value);
  }
  return parsed;
}

function classify(grams) {
  if (!Number.isFinite(grams) || grams <= 0) {
    throw new RangeError("grammage must be a positive finite number");
  }
  const grade = PAPER_GRADES.find((entry) => grams < entry.limit);
  return grade ? grade.name : HEAVIEST_GRADE;
}

function weigh(grams) {
  if (!Array.isArray(grams)) {
    throw new TypeError("weigh expects a list of paper weights");
  }
  return grams.map((entry) => classify(parseGrammage(entry)));
}

function formatRow(weight, type) {
  const measured = parseGrammage(weight);
  const label = measured.toFixed(0).padStart(4);
  return label + " gsm  ->  " + type;
}

function summarise(types) {
  const tally = types.reduce((counts, type) => {
    counts[type] = (counts[type] || 0) + 1;
    return counts;
  }, Object.create(null));
  return Object.keys(tally)
    .sort()
    .map((type) => type + " x" + tally[type])
    .join(", ");
}

function report(grams) {
  const types = weigh(grams);
  const lines = grams.map((weight, index) => formatRow(weight, types[index]));
  lines.push("totals: " + summarise(types));
  return lines.join(NEWLINE);
}

function main() {
  const samples = [12, 40, 100, 135, 180, 400];
  samples.push("80 gsm");
  samples.push("250");
  console.log(report(samples));
  console.log("single sheet of 40 gsm is " + classify(40));
}

main();

module.exports = { weigh, classify, parseGrammage, report };

