  { limit: 40, label: 'quiet whisper' },
  { limit: 60, label: 'normal conversation' },
  { limit: 80, label: 'city traffic' },
  { limit: 100, label: 'noisy factory' },
  { limit: 120, label: 'live concert' },
  { limit: 140, label: 'pain threshold' }
];

const DAMAGE = 'hearing damage';
const ARROW = ' dB  ->  ';
const PAD = ' ';

function describe(level) {
  for (const band of THRESHOLDS) {
    if (level < band.limit) {
      return band.label;
    }
  }
  return DAMAGE;
}

function parseLevel(value) {
  const level = typeof value === 'string' ? Number(value.trim()) : value;
  if (typeof level !== 'number' || Number.isNaN(level)) {
    throw new TypeError('sound level must be a number: ' + String(value));
  }
  if (!Number.isFinite(level)) {
    throw new RangeError('sound level must not be infinite');
  }
  return level;
}

function assess(decibels) {
  if (!Array.isArray(decibels)) {
    throw new TypeError('assess expects an array of sound levels');
  }
  return decibels.map(parseLevel).map(describe);
}

function report(decibels) {
  const descriptions = assess(decibels);
  const lines = descriptions.map(function (label, index) {
    const level = parseLevel(decibels[index]);
    const column = level.toFixed(1).padStart(7, PAD);
    return column + ARROW + label;
  });
  return lines.join('\n');
}

function summarize(decibels) {
  const counts = new Map();
  for (const label of assess(decibels)) {
    counts.set(label, (counts.get(label) || 0) + 1);
  }
  const parts = [];
  for (const [label, count] of counts) {
    parts.push(count + ' x ' + label);
  }
  return parts.join(', ');
}

function main() {
  const samples = [5, 30, '55', 70, 95, 118, 133, 150, 70];
  console.log('Sound level assessment');
  console.log(report(samples));
  console.log('Summary: ' + summarize(samples));
}

main();

module.exports = { assess, describe, report, summarize };

