const LEVELS = [
  "no data",
  "low danger",
  "moderate danger",
  "considerable danger",
  "high danger",
  "extreme danger"
];

const CRITICAL = [
  "high danger",
  "extreme danger"
];

function classify(score) {
  if (typeof score !== "number" || Number.isNaN(score)) {
    return "invalid reading";
  }
  if (!Number.isInteger(score) || score < 0) {
    return "invalid reading";
  }
  if (score > 5) {
    return "sensor error";
  }
  return LEVELS[score];
}

function warn(dangers) {
  if (!Array.isArray(dangers)) {
    throw new TypeError("warn expects a list of danger scores");
  }
  return dangers.map(classify);
}

function parseReadings(text) {
  return text
    .split(",")
    .map(function (field) {
      return field.trim();
    })
    .filter(function (field) {
      return field.length > 0;
    })
    .map(function (field) {
      const value = Number(field);
      return Number.isNaN(value) ? field : value;
    });
}

function formatLine(index, reading, level) {
  const label = "station " + (index + 1);
  const withReading = label + " (" + reading;
  return withReading + "): " + level;
}

function report(dangers) {
  const levels = warn(dangers);
  const lines = levels.map(function (level, index) {
    return formatLine(index, String(dangers[index]), level);
  });
  const critical = levels.filter(function (level) {
    return CRITICAL.indexOf(level) >= 0;
  });
  if (critical.length > 0) {
    const alert = "ALERT: " + critical.length;
    lines.push(alert + " station(s) above moderate");
  }
  return lines.join("\n");
}

function main() {
  const feed = "-1, 0, 1, 2, 3, 4, 5, 9, abc";
  console.log(report(parseReadings(feed)));
}

main();

