const STAGES = [
  { limit: 165, name: "drying phase" },
  { limit: 196, name: "cinnamon roast" },
  { limit: 205, name: "new england roast" },
  { limit: 210, name: "american roast" },
  { limit: 219, name: "city roast" },
  { limit: 225, name: "full city roast" },
  { limit: 230, name: "vienna roast" },
  { limit: 245, name: "french roast" }
];

const BURNT = "burnt carbon";

function classify(temperature) {
  if (typeof temperature !== "number" || Number.isNaN(temperature)) {
    throw new TypeError("temperature must be a number, got: " + String(temperature));
  }
  for (const stage of STAGES) {
    if (temperature < stage.limit) {
      return stage.name;
    }
  }
  return BURNT;
}

function roast(temperatures) {
  if (!Array.isArray(temperatures)) {
    throw new TypeError("roast expects an array of Celsius readings");
  }
  return temperatures.map(classify);
}

function parseReadings(text) {
  return text
    .split(/[,\s]+/)
    .filter((token) => token.length > 0)
    .map((token) => {
      const value = Number(token);
      if (Number.isNaN(value)) {
        throw new Error("unreadable probe value: " + token);
      }
      return value;
    });
}

function verdict(stages) {
  const final = stages[stages.length - 1];
  if (final === BURNT) {
    return "discard the batch";
  }
  return final;
}

function summarize(temperatures) {
  const stages = roast(temperatures);
  const counts = new Map();
  for (const stage of stages) {
    counts.set(stage, (counts.get(stage) || 0) + 1);
  }
  const lines = stages.map((stage, index) => {
    const reading = temperatures[index].toFixed(1).padStart(6, " ");
    return reading + " C  ->  " + stage;
  });
  const tally = [...counts.entries()]
    .map(([stage, count]) => stage + " x" + count)
    .join(", ");
  lines.push("tally: " + tally);
  lines.push("verdict: " + verdict(stages));
  return lines.join("\n");
}

function main() {
  const probeLog = "120, 164.5 170 200 207 219 228 240 260";
  const temperatures = parseReadings(probeLog);
  console.log(summarize(temperatures));
  console.log("single reading of 200: " + classify(200));
}

main();

module.exports = { roast, classify, parseReadings, verdict, summarize };

