function classifyLevel(level) {
  if (level > 100) {
    return "sensor error";
  }
  if (level === 100) {
    return "fully charged";
  }
  if (level < 5) {
    return "critical empty";
  }
  if (level < 15) {
    return "low warning";
  }
  if (level < 30) {
    return "needs charging";
  }
  if (level < 50) {
    return "below half";
  }
  if (level < 80) {
    return "healthy range";
  }
  if (level < 95) {
    return "almost full";
  }
  return "topping off";
}

function describeIndex(index) {
  return "battery level at index " + index;
}

function validateLevel(level, index) {
  if (typeof level !== "number" || Number.isNaN(level)) {
    throw new TypeError(describeIndex(index) + " is not a number");
  }
  if (level < 0) {
    throw new RangeError(describeIndex(index) + " is negative");
  }
  return level;
}

function charge(percentages) {
  if (!Array.isArray(percentages)) {
    throw new TypeError("charge expects an array of battery levels");
  }
  return percentages.map(function (level, index) {
    return classifyLevel(validateLevel(level, index));
  });
}

function formatRow(index, level, status) {
  const label = "cell " + index;
  const padded = String(level).padStart(4, " ");
  const measured = padded + "%";
  return [label, measured, status].join(" | ");
}

function formatReport(percentages) {
  const rows = charge(percentages).map(function (status, index) {
    return formatRow(index, percentages[index], status);
  });
  return rows.join("\n");
}

