function classifySalinity(ppt) {
  if (ppt < 0.5) return "fresh water";
  if (ppt < 5) return "oligohaline water";
  if (ppt < 18) return "mesohaline water";
  if (ppt < 30) return "polyhaline water";
  if (ppt < 40) return "euhaline water";
  if (ppt < 50) return "hypersaline water";
  if (ppt < 100) return "extreme brine";
  return "saturated salt";
}

function parseSalinity(value) {
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new RangeError("salinity must be a finite number");
    }
    return value;
  }
  if (typeof value === "string") {
    const trimmed = value.trim().replace(/\s*(ppt|‰)$/i, "");
    const parsed = Number(trimmed);
    if (trimmed === "" || Number.isNaN(parsed)) {
      throw new TypeError("cannot parse salinity from " + JSON.stringify(value));
    }
    return parsed;
  }
  throw new TypeError("salinity must be a number or numeric string");
}

function test(salinities) {
  if (!Array.isArray(salinities)) {
    throw new TypeError("expected a list of salinity levels");
  }
  return salinities.map(function (entry) {
    const ppt = parseSalinity(entry);
    if (ppt < 0) {
      throw new RangeError("salinity cannot be negative: " + ppt);
    }
    return classifySalinity(ppt);
  });
}

function formatReport(salinities) {
  const classes = test(salinities);
  return classes
    .map(function (label, index) {
      const ppt = parseSalinity(salinities[index]);
      const column = ppt.toFixed(2).padStart(7, " ");
      return column + " ppt -> " + label;
    })
    .join("\n");
}

function summarize(salinities) {
  const tally = new Map();
  for (const label of test(salinities)) {
    tally.set(label, (tally.get(label) || 0) + 1);
  }
  const parts = [];
  for (const [label, count] of tally) {
    parts.push(count + "x " + label);
  }
  return parts.join(", ");
}

function main() {
  const samples = [0.1, 1.2, 17, 25.5, 35, 78, 120, 0];
  samples.push("0.49");
  samples.push("4.9 ppt");
  samples.push("42");
  console.log(formatReport(samples));
  console.log("summary: " + summarize(samples));
  try {
    test([-3]);
  } catch (err) {
    console.log("rejected: " + err.message);
  }
}

main();

module.exports = { test, classifySalinity, parseSalinity, formatReport, summarize };

