const RISK_BANDS = [
  { limit: 3, label: "low risk" },
  { limit: 6, label: "moderate risk" },
  { limit: 8, label: "high risk" },
  { limit: 11, label: "very high risk" },
  { limit: 15, label: "extreme risk" },
  { limit: 20, label: "danger level" },
  { limit: 25, label: "shelter indoors" }
];

const MALFUNCTION = "sensor malfunction";

function parseIndex(value) {
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (trimmed === "") {
      throw new Error("empty UV reading");
    }
    value = Number(trimmed);
  }
  if (typeof value !== "number" || Number.isNaN(value)) {
    throw new Error("UV reading is not a number");
  }
  if (value < 0) {
    throw new Error("UV reading cannot be negative: " + value);
  }
  return value;
}

function classify(index) {
  const band = RISK_BANDS.find(function (entry) {
    return index < entry.limit;
  });
  return band ? band.label : MALFUNCTION;
}

function protect(indices) {
  if (!Array.isArray(indices)) {
    throw new TypeError("protect expects an array of UV index values");
  }
  return indices.map(function (raw) {
    return classify(parseIndex(raw));
  });
}

function advice(level) {
  switch (level) {
    case "low risk":
      return "no protection needed";
    case "moderate risk":
      return "wear sunglasses and a hat";
    case "high risk":
      return "apply sunscreen every two hours";
    case "very high risk":
      return "seek shade between 10am and 4pm";
    case "extreme risk":
      return "cover up and avoid the midday sun";
    case "danger level":
      return "stay inside unless fully covered";
    case "shelter indoors":
      return "remain indoors until dusk";
    default:
      return "recalibrate the sensor";
  }
}

function formatRow(reading, level) {
  const columns = [
    String(reading).padStart(3),
    level,
    advice(level)
  ];
  return columns.join(" | ");
}

function report(indices) {
  return protect(indices)
    .map(function (level, position) {
      return formatRow(indices[position], level);
    })
    .join("\n");
}

const readings = [1, 4, "7", 9.5, 13, 18, 22, 40];
console.log(report(readings));
console.log(protect(readings).join(", "));

