function classify(loft) {
  if (loft < 2) return "ultra thin";
  if (loft < 3) return "low loft";
  if (loft < 4) return "medium low";
  if (loft < 5) return "medium loft";
  if (loft < 6) return "medium high";
  if (loft < 7) return "high loft";
  if (loft < 8) return "extra high";
  return "wedge support";
}

function parseLoft(value) {
  if (typeof value === "number") {
    return value;
  }
  if (typeof value !== "string") {
    throw new TypeError("loft must be a number or a numeric string");
  }
  const trimmed = value.trim().replace(/\s*(in|inch|inches|")\s*$/i, "");
  const parsed = Number(trimmed);
  if (!Number.isFinite(parsed)) {
    throw new RangeError("unreadable loft measurement: " + value);
  }
  return parsed;
}

function sleep(lofts) {
  if (!Array.isArray(lofts)) {
    throw new TypeError("sleep expects an array of loft heights");
  }
  return lofts.map(function (entry) {
    const loft = parseLoft(entry);
    if (loft < 0) {
      throw new RangeError("a pillow cannot have a negative loft");
    }
    return classify(loft);
  });
}

function formatInches(loft) {
  const rounded = Math.round(loft * 100) / 100;
  const digits = rounded.toFixed(2).replace(/\.?0+$/, "");
  if (rounded === 1) {
    return digits + " inch";
  }
  return digits + " inches";
}

function report(lofts) {
  const profiles = sleep(lofts);
  const lines = profiles.map(function (profile, index) {
    return formatInches(parseLoft(lofts[index])) + " -> " + profile;
  });
  return lines.join("\n");
}

function tally(lofts) {
  const counts = new Map();
  for (const profile of sleep(lofts)) {
    counts.set(profile, (counts.get(profile) || 0) + 1);
  }
  return [...counts.entries()]
    .sort(function (a, b) { return b[1] - a[1] || a[0].localeCompare(b[0]); })
    .map(function (pair) { return pair[0] + ": " + pair[1]; })
    .join(", ");
}

