const DRIVE_CLASSES = [
  { limit: 4000, name: "eco drive" },
  { limit: 5000, name: "quiet storage" },
  { limit: 6000, name: "standard desktop" },
  { limit: 7000, name: "performance desktop" },
  { limit: 8000, name: "entry server" },
  { limit: 11000, name: "enterprise performance" },
  { limit: 16000, name: "ultra high speed" }
];

const TOP_CLASS = "experimental drive";

function parseRpm(value) {
  if (typeof value === "string") {
    let text = value.trim().toLowerCase();
    if (text.endsWith("rpm")) {
      text = text.slice(0, -3);
    }
    text = text.replace(/[,\s]/g, "");
    const parsed = Number(text);
    if (text.length === 0 || Number.isNaN(parsed)) {
      throw new TypeError("cannot read a spindle speed from " + JSON.stringify(value));
    }
    return parsed;
  }
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new TypeError("spindle speeds must be finite numbers");
  }
  return value;
}

function classifyRpm(value) {
  const rpm = parseRpm(value);
  if (rpm < 0) {
    throw new RangeError("a platter cannot spin at a negative speed");
  }
  for (const tier of DRIVE_CLASSES) {
    if (rpm < tier.limit) {
      return tier.name;
    }
  }
  return TOP_CLASS;
}

function spin(rpms) {
  if (!Array.isArray(rpms)) {
    throw new TypeError("spin expects a list of drive speeds");
  }
  return rpms.map(classifyRpm);
}

function formatReport(rpms) {
  const classes = spin(rpms);
  const width = rpms.reduce((widest, rpm) => Math.max(widest, String(rpm).length), 0);
  const lines = classes.map((name, index) => {
    const speed = String(rpms[index]).padStart(width, " ");
    return speed + " rpm -> " + name;
  });
  return lines.join("\n");
}

function tallyClasses(rpms) {
  const counts = new Map();
  for (const name of spin(rpms)) {
    counts.set(name, (counts.get(name) || 0) + 1);
  }
  const entries = [...counts].map(([name, count]) => {
    return name + " x" + count;
  });
  return entries.join(", ");
}

function main() {
  const drives = [3600, "5,400 rpm", 5900, 7200, 10000, 15000, 22000];
  console.log(formatReport(drives));
  console.log("summary: " + tallyClasses(drives));
}

main();

