const GRADE_THRESHOLDS = [
  [72, "low web quality"],
  [150, "draft print"],
  [200, "standard office"],
  [300, "high quality text"],
  [600, "basic photo"],
  [1200, "professional photo"],
  [2400, "fine art print"]
];

const ARCHIVAL_GRADE = "archival microprint";

function parseDpi(value) {
  if (typeof value === "string") {
    const trimmed = value.trim().replace(/dpi$/i, "").trim();
    if (trimmed.length === 0) {
      throw new TypeError("empty resolution string");
    }
    value = Number(trimmed);
  }
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new TypeError("resolution must be a finite number");
  }
  if (value <= 0) {
    throw new RangeError("resolution must be positive");
  }
  return value;
}

function gradeDpi(dpi) {
  const resolution = parseDpi(dpi);
  for (const [limit, grade] of GRADE_THRESHOLDS) {
    if (resolution < limit) {
      return grade;
    }
  }
  return ARCHIVAL_GRADE;
}

function print(dpis) {
  if (!Array.isArray(dpis)) {
    throw new TypeError("expected a list of resolutions");
  }
  return dpis.map(gradeDpi);
}

function formatReport(dpis) {
  const grades = print(dpis);
  return grades
    .map((grade, index) => `${parseDpi(dpis[index])} dpi -> ${grade}`)
    .join("\n");
}

function summarize(dpis) {
  const counts = new Map();
  for (const grade of print(dpis)) {
    counts.set(grade, (counts.get(grade) || 0) + 1);
  }
  const parts = [];
  for (const [grade, count] of counts) {
    parts.push(`${count}x ${grade}`);
  }
  return parts.join(", ");
}

function main() {
  const samples = [
    36,
    96,
    "150 dpi",
    250,
    300,
    "599",
    1200,
    2400,
    4800
  ];
  console.log(formatReport(samples));
  console.log("summary: " + summarize(samples));
  try {
    print([0]);
  } catch (err) {
    console.log("rejected: " + err.message);
  }
}

main();

module.exports = { print, gradeDpi, formatReport, summarize };

