const CATEGORIES = [
  { limit: 20, label: "hunt and peck" },
  { limit: 30, label: "casual typist" },
  { limit: 40, label: "average office" },
  { limit: 50, label: "productive typist" },
  { limit: 60, label: "fast professional" },
  { limit: 80, label: "highly advanced" },
  { limit: 100, label: "competitive speed" },
  { limit: Infinity, label: "elite level" }
];

function parseSpeed(value) {
  const speed = typeof value === "string" ? Number(value.trim()) : value;
  if (typeof speed !== "number" || !Number.isFinite(speed)) {
    throw new TypeError("typing speed must be a finite number, got: " + String(value));
  }
  if (speed < 0) {
    throw new RangeError("typing speed cannot be negative: " + speed);
  }
  return speed;
}

function categorize(wpm) {
  const speed = parseSpeed(wpm);
  const match = CATEGORIES.find(entry => speed < entry.limit);
  return match.label;
}

function type(wpms) {
  if (!Array.isArray(wpms)) {
    throw new TypeError("type() expects an array of words-per-minute values");
  }
  return wpms.map(categorize);
}

function summarize(wpms) {
  const labels = type(wpms);
  const tally = new Map();
  for (const label of labels) {
    tally.set(label, (tally.get(label) || 0) + 1);
  }
  return CATEGORIES
    .map(entry => entry.label)
    .filter(label => tally.has(label))
    .map(label => label + " x" + tally.get(label))
    .join(", ");
}

function formatReport(wpms) {
  const labels = type(wpms);
  const rows = labels.map((label, index) => {
    const speed = parseSpeed(wpms[index]);
    return String(speed).padStart(5) + " wpm  ->  " + label;
  });
  rows.push("-".repeat(32));
  rows.push("totals: " + summarize(wpms));
  return rows.join("\n");
}

function main() {
  const samples = [12, 25, "38", 45, 55, 72, 96, 140];
  console.log(formatReport(samples));
  try {
    type([60, "fast"]);
  } catch (err) {
    console.log("rejected input: " + err.message);
  }
}

main();

module.exports = { type, categorize, summarize, formatReport };

