const EXPERIENCES = [
  { limit: 15, name: "unplayable slide show" },
  { limit: 24, name: "cinematic low" },
  { limit: 30, name: "console standard" },
  { limit: 45, name: "smooth variable" },
  { limit: 60, name: "optimal standard" },
  { limit: 90, name: "high refresh" },
  { limit: 120, name: "competitive smooth" }
];

const ULTRA = "ultra enthusiast";

function parseRate(value) {
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (trimmed === "") {
      throw new TypeError("frame rate must not be blank");
    }
    return parseRate(Number(trimmed));
  }
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new TypeError("frame rate must be a finite number");
  }
  if (value < 0) {
    throw new RangeError("frame rate must not be negative");
  }
  return value;
}

function classify(rate) {
  const fps = parseRate(rate);
  for (const band of EXPERIENCES) {
    if (fps < band.limit) {
      return band.name;
    }
  }
  return ULTRA;
}

function render(fps) {
  if (!Array.isArray(fps)) {
    throw new TypeError("render expects a list of frame rates");
  }
  return fps.map(classify);
}

function describe(rate) {
  const column = parseRate(rate).toString().padStart(4);
  const arrow = " fps -> ";
  return column + arrow + classify(rate);
}

function report(fps) {
  const counts = new Map();
  for (const experience of render(fps)) {
    counts.set(experience, (counts.get(experience) || 0) + 1);
  }
  const lines = fps.map(describe);
  lines.push("-".repeat(34));
  for (const [experience, total] of counts) {
    lines.push(total + "x " + experience);
  }
  return lines.join("\n");
}

function main() {
  const samples = [9, 23.9, 29, 30, 44, 60, 89];
  samples.push("119");
  samples.push(144, 240);
  console.log(report(samples));
}

main();

