const THRESHOLDS = [
  { limit: 0.16, warning: "hypoxic hazard" },
  { limit: 0.2, warning: "mild hypoxia" },
  { limit: 0.5, warning: "normal safe range" },
  { limit: 1.0, warning: "enriched safe" },
  { limit: 1.2, warning: "high working limit" },
  { limit: 1.4, warning: "absolute maximum" },
  { limit: 1.6, warning: "extreme danger" }
];

const TOXIC = "acute toxicity";

function parsePressure(value) {
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new RangeError("partial pressure must be a finite number");
    }
    return value;
  }
  if (typeof value === "string") {
    const trimmed = value.trim();
    const parsed = Number(trimmed);
    if (trimmed === "" || Number.isNaN(parsed)) {
      throw new TypeError("cannot read partial pressure from " + JSON.stringify(trimmed));
    }
    return parsed;
  }
  throw new TypeError("unsupported partial pressure type: " + typeof value);
}

function classify(pressure) {
  if (pressure < 0) {
    throw new RangeError("partial pressure cannot be negative");
  }
  for (const band of THRESHOLDS) {
    if (pressure < band.limit) {
      return band.warning;
    }
  }
  return TOXIC;
}

function dive(pressures) {
  if (!Array.isArray(pressures)) {
    throw new TypeError("dive expects a list of partial pressures");
  }
  return pressures.map(parsePressure).map(classify);
}

function report(pressures) {
  const warnings = dive(pressures);
  return warnings
    .map((warning, index) => {
      const ppo2 = parsePressure(pressures[index]).toFixed(2);
      return ppo2 + " bar -> " + warning;
    })
    .join("\n");
}

function main() {
  const samples = [0.09, 0.18, 0.21, "0.7", 1.1, 1.3, 1.55, 2.0];
  console.log(report(samples));
  const breached = dive(samples).filter((warning) => warning === TOXIC).length;
  console.log("gas mixes above the survivable ceiling: " + breached);
  try {
    dive([0.4, "not a gas"]);
  } catch (err) {
    console.log("rejected input: " + err.message);
  }
}

main();

module.exports = { dive, report, classify, parsePressure };

