function zoneFor(temp) {
  if (temp < -18) {
    return "deep freeze";
  }
  if (temp < -5) {
    return "soft freeze";
  }
  if (temp < 0) {
    return "icy chill";
  }
  if (temp < 2) {
    return "raw meat safe";
  }
  if (temp < 4) {
    return "optimal fridge";
  }
  if (temp < 7) {
    return "dairy safe";
  }
  if (temp < 10) {
    return "produce crisper";
  }
  return "unsafe warm";
}

function parseTemperature(value) {
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new RangeError("temperature must be a finite number");
    }
    return value;
  }
  if (typeof value === "string") {
    const cleaned = value.trim().replace(/\s*°?\s*C$/i, "");
    const parsed = Number(cleaned);
    if (cleaned === "" || Number.isNaN(parsed)) {
      throw new TypeError("cannot read temperature from " + JSON.stringify(value));
    }
    return parsed;
  }
  throw new TypeError("unsupported temperature type: " + typeof value);
}

function chill(celsius) {
  if (!Array.isArray(celsius)) {
    throw new TypeError("chill expects a list of temperatures");
  }
  return celsius.map((entry) => zoneFor(parseTemperature(entry)));
}

function formatReading(value) {
  const temp = parseTemperature(value);
  const shown = temp.toFixed(1).replace(/\.0$/, "");
  return shown + " \u00B0C";
}

function report(celsius) {
  const zones = chill(celsius);
  const lines = celsius.map((entry, index) => {
    const label = formatReading(entry).padStart(8, " ");
    return label + "  ->  " + zones[index];
  });
  const warm = zones.filter((zone) => zone === "unsafe warm").length;
  let summary = "all readings within storage limits";
  if (warm > 0) {
    summary = warm + " reading(s) too warm to store";
  }
  return lines.concat([summary]).join("\n");
}

function main() {
  const readings = [-25, -18, -6, -0.5, 1.5, 3, 8.2, 14];
  readings.push("5 °C");
  console.log(report(readings));
  try {
    chill(["twelve"]);
  } catch (err) {
    console.log("rejected input: " + err.message);
  }
}

main();

module.exports = { chill, zoneFor, parseTemperature, formatReading, report };

