function generateFibonacci(n) {
  if (n <= 0) {
    console.log("Input must be a positive integer. Returning an empty array.");
    return [];
  }

  if (n === 1) {
    console.log("Generating a single Fibonacci number.");
    return [0];
  }

  const sequence = [0, 1];
  console.log("Starting Fibonacci sequence generation.");

  for (let i = 2; i < n; i++) {
    const nextFib = sequence[i - 1] + sequence[i - 2];
    sequence.push(nextFib);
    console.log("Added new number to sequence: " + nextFib);
  }

  console.log("Fibonacci sequence generation complete.");
  console.log("The final array contains " + sequence.length + " elements.");
  return sequence;
}

