function capitalizeFirstLetter(str) {
  if (typeof str !== "string" || str === "") {
    return "";
  }

  let words = str.split(" ");
  let result = [];

  for (let i = 0; i < words.length; i++) {
    let word = words[i];
    if (word.length > 0) {
      let firstChar = word.charAt(0).toUpperCase();
      let restOfWord = word.slice(1).toLowerCase();
      result.push(firstChar + restOfWord);
