function parseNumberList(text) {
  if (typeof text !== "string") {
    throw new TypeError("parseNumberList expects a string");
  }
  const cleaned = text.replace(/[\[\]]/g, "").trim();
  if (cleaned === "") {
    return [];
  }
  return cleaned.split(",").map(function (piece) {
    const value = Number(piece.trim());
    if (Number.isNaN(value)) {
      throw new RangeError("not a number: " + piece.trim());
    }
    return value;
  });
}

function sumArray(arr) {
  if (!Array.isArray(arr)) {
    throw new TypeError("sumArray expects an array");
  }
  let total = 0;
  for (const entry of arr) {
    if (typeof entry !== "number" || Number.isNaN(entry)) {
      throw new TypeError("array contains a non-numeric entry");
    }
    total += entry;
  }
  return total;
}

function averageArray(arr) {
  const total = sumArray(arr);
  if (arr.length === 0) {
    return 0;
  }
  return total / arr.length;
}

function formatNumber(value) {
  if (Number.isInteger(value)) {
    return String(value);
  }
  const fixed = value.toFixed(3);
  const trimmed = fixed.replace(/0+$/, "");
  return trimmed.replace(/\.$/, "");
}

function describe(arr) {
  let shown = arr.map(formatNumber).join(" + ");
  if (arr.length === 0) {
    shown = "(empty)";
  }
  const sumPart = " = " + formatNumber(sumArray(arr));
  const meanPart = ", mean " + formatNumber(averageArray(arr));
  return shown + sumPart + meanPart;
}

function main() {
  const inputs = [];
  inputs.push("1, 2, 3");
  inputs.push("[-1, 0, 1]");
  inputs.push("2.5, 2.5, -4");
  inputs.push("");
  inputs.push("7");
  const report = [];
  for (const raw of inputs) {
    let label = raw.trim();
    if (label === "") {
      label = "<blank>";
    }
    try {
      report.push(label + " -> " + describe(parseNumberList(raw)));
    } catch (err) {
      report.push(label + " -> error: " + err.message);
    }
  }
  console.log(report.join("\n"));
}

module.exports = { sumArray, averageArray, parseNumberList, formatNumber, describe };

if (require.main === module) {
  main();
}

