function removeChar(str, charToRemove) {
  let result = "";
  let i = 0;
  while (i < str.length) {
    if (str[i] === charToRemove) {
      // Do nothing, effectively skipping the character
    } else {
      result += str[i];
    }
    i++;
  }
  return result;
}

// Example usage and tests
console.log(removeChar("hello world", "l")); // Expected: "heo word"
