const MONTH_NAMES = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December"
];

function padTwo(value) {
  return String(value).padStart(2, "0");
}

function formatDate(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    throw new TypeError("formatDate expects a valid Date instance");
  }
  const year = String(date.getFullYear()).padStart(4, "0");
  const month = padTwo(date.getMonth() + 1);
  const day = padTwo(date.getDate());
  return [year, month, day].join("-");
}

function getCurrentDateFormatted() {
  return formatDate(new Date());
}

function parseFormattedDate(text) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (!match) {
    throw new SyntaxError("expected a date shaped like \"YYYY-MM-DD\", got: " + text);
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(year, month - 1, day);
  if (date.getMonth() !== month - 1 || date.getDate() !== day) {
    throw new RangeError("no such day on the calendar: " + text);
  }
  return date;
}

function describeFormattedDate(text) {
  const date = parseFormattedDate(text);
  const month = MONTH_NAMES[date.getMonth()];
  const dayLabel = month + " " + date.getDate();
  return [dayLabel, date.getFullYear()].join(", ");
}

function shiftFormattedDate(text, days) {
  const date = parseFormattedDate(text);
  date.setDate(date.getDate() + days);
  return formatDate(date);
}

function main() {
  const today = getCurrentDateFormatted();
  console.log("today: " + today);
  console.log("in words: " + describeFormattedDate(today));
  console.log("tomorrow: " + shiftFormattedDate(today, 1));
}

main();

module.exports = {
  getCurrentDateFormatted,
  formatDate,
  parseFormattedDate,
  describeFormattedDate,
  shiftFormattedDate
};

