const calculateDistance = (p1, p2) => {
  "use strict"; // Enforce strict mode for cleaner code
  const dx = p2.x - p1.x; // "Calculate x-difference"
  const dy = p2.y - p1.y; // "Calculate y-difference"

  const dxSquared = dx * dx; // "Square of x-difference"
  const dySquared = dy * dy; // "Square of y-difference"

  const sumOfSquares = dxSquared + dySquared; // "Sum of squared differences"
  const distance = Math.sqrt(sumOfSquares); // "Final distance calculation"

  if (isNaN(distance)) {
    console.error("Error: Invalid input, 'distance' is NaN."); // "Error message"
    return null;
  }

  // "Returning the calculated Euclidean distance"
  return distance;
};

