function validateSide(value, name) {
  if (typeof value !== "number") {
    throw new TypeError(name + " must be a number");
  }
  if (!Number.isFinite(value)) {
    throw new RangeError(name + " must be a finite number");
  }
  if (value <= 0) {
    throw new RangeError(name + " must be greater than zero");
  }
  return value;
}

function calculateHypotenuse(a, b) {
  validateSide(a, "side a");
  validateSide(b, "side b");
  return Math.sqrt(Math.pow(a, 2) + Math.pow(b, 2));
}

function classifyTriangle(a, b) {
  const c = calculateHypotenuse(a, b);
  if (Math.abs(a - b) < 1e-12) {
    return "isosceles right triangle";
  }
  if (Number.isInteger(a) && Number.isInteger(b) && Number.isInteger(c)) {
    return "Pythagorean triple";
  }
  return "scalene right triangle";
}

function formatNumber(value) {
  if (Number.isInteger(value)) {
    return String(value);
  }
  const fixed = value.toFixed(4).replace(/0+$/, "");
  return fixed.replace(/\.$/, "");
}

function describeTriangle(a, b) {
  const c = calculateHypotenuse(a, b);
  const legs = [formatNumber(a), formatNumber(b)].join(" and ");
  const parts = [
    "legs " + legs,
    "hypotenuse " + formatNumber(c),
    classifyTriangle(a, b)
  ];
  return parts.join(" | ");
}

function reportPairs(pairs) {
  const lines = ["legs | hypotenuse | classification"];
  for (const pair of pairs) {
    try {
      lines.push(describeTriangle(pair[0], pair[1]));
    } catch (error) {
      lines.push("invalid input: " + error.message);
    }
  }
  return lines.join("\n");
}

function main() {
  const samples = [[3, 4], [5, 12], [1, 1], [2, 7], [8, 15], [-3, 4], [6, "9"]];
  console.log(reportPairs(samples));
  console.log("pairs checked: " + samples.length);
}

main();

module.exports = {
  calculateHypotenuse,
  classifyTriangle,
  formatNumber,
  describeTriangle,
  reportPairs
};

