function validateNumbers(arr) {
  if (!Array.isArray(arr)) {
    throw new TypeError("findSecondSmallest expects an array of numbers");
  }
  if (arr.length < 2) {
    throw new RangeError("at least two numbers are required");
  }
  arr.forEach(function (value, index) {
    if (typeof value !== "number" || Number.isNaN(value)) {
      throw new TypeError("invalid entry at position " + index);
    }
  });
  if (new Set(arr).size < 2) {
    throw new RangeError("at least two distinct numbers are required");
  }
}

function findSecondSmallest(arr) {
  validateNumbers(arr);
  let smallest = Infinity;
  let second = Infinity;
  for (const value of arr) {
    if (value < smallest) {
      second = smallest;
      smallest = value;
    } else if (value > smallest && value < second) {
      second = value;
    }
  }
  return second;
}

function parseRow(line) {
  return line.split(",").map(function (part) {
    const trimmed = part.trim();
    if (trimmed === "") {
      throw new SyntaxError("empty field in row");
    }
    const parsed = Number(trimmed);
    if (Number.isNaN(parsed)) {
      throw new SyntaxError("not a number: " + trimmed);
    }
    return parsed;
  });
}

function describeRow(line) {
  let outcome;
  try {
    outcome = "second smallest = " + findSecondSmallest(parseRow(line));
  } catch (error) {
    outcome = "rejected: " + error.message;
  }
  return line + " -> " + outcome;
}

function buildReport(rows) {
  return rows.map(describeRow).join("\n");
}

function main() {
  const rows = [
    "5, 1, 8, 2, 9",
    "10, 20, 3, 40",
    "-4, -4, 0, 7",
    "42",
    "7, seven, 12"
  ];
  console.log("Second smallest report");
  console.log(buildReport(rows));
}

main();

