const ARCHIVE_TYPES = [
  'zip',
  'gz',
  'bz2',
  'xz',
  '7z'
];

const HEADER = 'FILE                    EXT       CATEGORY';

function basename(path) {
  const parts = path.split(/[/\\]/);
  return parts[parts.length - 1];
}

function getFileExtension(filename) {
  if (typeof filename !== 'string') {
    throw new TypeError('getFileExtension expects a string');
  }
  const name = basename(filename);
  const dot = name.lastIndexOf('.');
  if (dot <= 0 || dot === name.length - 1) {
    return '';
  }
  return name.slice(dot + 1);
}

function categorizeExtension(extension) {
  const ext = extension.toLowerCase();
  if (ext.length === 0) {
    return 'unknown';
  }
  if (DOCUMENT_TYPES.includes(ext)) {
    return 'document';
  }
  if (IMAGE_TYPES.includes(ext)) {
    return 'image';
  }
  if (ARCHIVE_TYPES.includes(ext)) {
    return 'archive';
  }
  return 'other';
}

function formatRow(filename, extension, category) {
  let shown = '(none)';
  if (extension.length > 0) {
    shown = extension;
  }
  return basename(filename).padEnd(24) + shown.padEnd(10) + category;
}

function buildReport(filenames) {
  const rows = [HEADER, '-'.repeat(46)];
  for (const filename of filenames) {
    const extension = getFileExtension(filename);
    rows.push(formatRow(filename, extension, categorizeExtension(extension)));
  }
  return rows.join('\n');
}

function main() {
  const files = [
    'document.pdf',
    'archive.tar.gz',
    'nofileextension',
    '/tmp/photos/holiday.JPG',
    'C:\\Users\\me\\notes.txt',
    '.gitignore',
    'backup.'
  ];
  console.log(buildReport(files));
}

main();

module.exports = { getFileExtension, categorizeExtension, buildReport };

