const NUMBER_TYPE = "number";
const STRING_TYPE = "string";
const QUOTE = "\"";
const ITEM_SEPARATOR = ", ";
const OPEN_BRACKET = "[";
const CLOSE_BRACKET = "]";

function assertArray(arr) {
  if (!Array.isArray(arr)) {
    throw new TypeError("findFirstIndex expects an array as its first argument");
  }
}

function sameValue(a, b) {
  if (typeof a === NUMBER_TYPE && typeof b === NUMBER_TYPE) {
    return a === b || (Number.isNaN(a) && Number.isNaN(b));
  }
  return a === b;
}

function findFirstIndex(arr, element) {
  assertArray(arr);
  for (let i = 0; i < arr.length; i += 1) {
    if (sameValue(arr[i], element)) {
      return i;
    }
  }
  return -1;
}

function describeValue(value) {
  if (value === null) {
    return "null";
  }
  if (value === undefined) {
    return "undefined";
  }
  if (typeof value === STRING_TYPE) {
    return QUOTE + value + QUOTE;
  }
  if (Number.isNaN(value)) {
    return "NaN";
  }
  return String(value);
}

function describeArray(arr) {
  const items = arr.map(describeValue).join(ITEM_SEPARATOR);
  return OPEN_BRACKET + items + CLOSE_BRACKET;
}

function reportSearch(arr, element) {
  const index = findFirstIndex(arr, element);
  const parts = [];
  parts.push("searching");
  parts.push(describeArray(arr));
  parts.push("for");
  parts.push(describeValue(element));
  if (index === -1) {
    parts.push("-> not found");
  } else {
    parts.push("-> found at index " + index);
  }
  return parts.join(" ");
}

function main() {
  const letters = [
    "a",
    "b",
    "c"
  ];
  const searches = [];
  searches.push({ data: [1, 5, 2, 8], needle: 2 });
  searches.push({ data: letters, needle: "d" });
  searches.push({ data: letters, needle: "c" });
  searches.push({ data: [NaN, 3, NaN], needle: NaN });
  searches.push({ data: [null, undefined, 0], needle: undefined });
  searches.forEach(function (query) {
    console.log(reportSearch(query.data, query.needle));
  });
  try {
    findFirstIndex(letters.join(ITEM_SEPARATOR), letters[0]);
  } catch (err) {
    console.log("rejected bad input: " + err.message);
  }
}

main();

module.exports = { findFirstIndex, reportSearch, describeArray, describeValue };

