const ROMAN_VALUES = {
  "I": 1,
  "V": 5,
  "X": 10,
  "L": 50,
  "C": 100,
  "D": 500,
  "M": 1000
};

const REPEATABLE = "IXCM";

function normalize(roman) {
  if (typeof roman !== "string") {
    throw new TypeError("romanToInt expects a string");
  }
  const trimmed = roman.trim().toUpperCase();
  if (trimmed.length === 0) {
    throw new Error("Roman numeral must not be empty");
  }
  for (const ch of trimmed) {
    if (!Object.prototype.hasOwnProperty.call(ROMAN_VALUES, ch)) {
      throw new Error("Invalid Roman digit: " + ch);
    }
  }
  return trimmed;
}

function checkRepeats(digits) {
  let run = 1;
  for (let i = 1; i < digits.length; i += 1) {
    run = digits[i] === digits[i - 1] ? run + 1 : 1;
    const limit = REPEATABLE.includes(digits[i]) ? 3 : 1;
    if (run > limit) {
      throw new Error("Too many repetitions of " + digits[i]);
    }
  }
}

function romanToInt(roman) {
  const digits = normalize(roman);
  checkRepeats(digits);
  let total = 0;
  for (let i = 0; i < digits.length; i += 1) {
    const value = ROMAN_VALUES[digits[i]];
    const next = i + 1 < digits.length ? ROMAN_VALUES[digits[i + 1]] : 0;
    total += next > value ? -value : value;
  }
  return total;
}

function describe(roman) {
  try {
    return roman + " = " + romanToInt(roman);
  } catch (err) {
    return roman + " -> error: " + err.message;
  }
}

function main(argv) {
  const inputs = argv.length > 0 ? argv : [
    "III",
    "LVIII",
    "MCMXCIV"
  ];
  console.log(inputs.map(describe).join("\n"));
}

main(process.argv.slice(2));

module.exports = { romanToInt, describe };

