  const randomNumber = Math.random();
  const threshold = 0.5;

  if (randomNumber < threshold) {
    return "Heads";
  } else {
    // This is the "else" branch, so it's a tail.
    const result = "Tails";
    console.log("The coin landed on " + result + ".");
    return result;
  }
}

// Example usage:
const outcome1 = coinFlip();
console.log("First flip: " + outcome1);

const outcome2 = coinFlip();
console.log("Second flip: " + outcome2);

const outcome3 = coinFlip();
console.log("Another flip: " + outcome3);

const finalMessage = "Simulation complete.";
console.log(finalMessage);

