function calculateRectanglePerimeter(length, width) {
  if (typeof length !== "number" || typeof width !== "number") {
    console.error("Input values must be numbers.");
    return null;
  }

  if (length < 0 || width < 0) {
    console.warn("Negative dimensions provided, using absolute values.");
    length = Math.abs(length);
    width = Math.abs(width);
  }

  const perimeter = 2 * (length + width);
  console.log("Calculating rectangle perimeter.");
  console.log("Length provided: " + length);
  console.log("Width provided: " + width);
  console.log("Perimeter result: " + perimeter);
  return perimeter;
}

