const SEPARATOR = ", ";

function describe(value) {
  if (value === null) {
    return "null";
  }
  if (typeof value !== "number") {
    return typeof value;
  }
  if (Number.isNaN(value)) {
    return "NaN";
  }
  return String(value);
}

function pluralize(count, word) {
  if (count === 1) {
    return word;
  }
  return word + "s";
}

function validateInput(numbers) {
  if (!Array.isArray(numbers)) {
    throw new TypeError("calculateMode expects an array of numbers");
  }
  if (numbers.length === 0) {
    throw new RangeError("calculateMode expects at least one value");
  }
  numbers.forEach(function (value, index) {
    if (typeof value !== "number" || Number.isNaN(value)) {
      const location = "invalid value at index " + index;
      throw new TypeError(location + ": " + describe(value));
    }
  });
  return numbers;
}

function buildFrequencyTable(numbers) {
  const table = new Map();
  for (const value of numbers) {
    table.set(value, (table.get(value) || 0) + 1);
  }
  return table;
}

function calculateMode(numbers) {
  validateInput(numbers);
  const table = buildFrequencyTable(numbers);
  let highest = 0;
  for (const count of table.values()) {
    if (count > highest) {
      highest = count;
    }
  }
  const modes = [];
  for (const [value, count] of table) {
    if (count === highest) {
      modes.push(value);
    }
  }
  return modes.sort(function (a, b) {
    return a - b;
  });
}

function formatReport(numbers) {
  const modes = calculateMode(numbers);
  const frequency = buildFrequencyTable(numbers).get(modes[0]);
  const label = pluralize(modes.length, "mode");
  const occurrences = pluralize(frequency, "time");
  const phrase = [frequency, occurrences].join(" ");
  const lines = [];
  lines.push("input: " + numbers.join(SEPARATOR));
  lines.push(label + ": " + modes.join(SEPARATOR));
  lines.push("each appearing " + phrase);
  return lines.join("; ");
}

function main() {
  const samples = [[1, 2, 2, 3, 1], [1, 2, 3], [4, 4, 4, 9, 9, -1]];
  for (const sample of samples) {
    console.log(formatReport(sample));
  }
}

main();

module.exports = { calculateMode: calculateMode, formatReport: formatReport };

