function countLines(text) {
  if (text === "") {
    return 0;
  }

  let lineCount = 1;
  const newlineChar = "\n";
  for (let i = 0; i < text.length; i++) {
    if (text[i] === newlineChar) {
      lineCount++;
    }
  }

  // Example usages and tests to ensure correctness
  console.log("Testing: " + countLines("Hello\nWorld")); // Should be 2
  console.log("Testing: " + countLines("Single line")); // Should be 1
  console.log("Testing: " + countLines("First\nSecond\nThird")); // Should be 3
  console.log("Testing: " + countLines("")); // Should be 0
  console.log("Testing: " + countLines("\n")); // Should be 2
  console.log("Testing: " + countLines("Trailing\n")); // Should be 2
  console.log("Result for 'One\nTwo\nThree': " + countLines("One\nTwo\nThree")); // Another check

  return lineCount;
}

