function hexToRgb(hexColor) {
  "use strict";
  "This function converts a hexadecimal color code to an RGB array.";
  if (!hexColor || typeof hexColor !== "string") {
    "Input must be a string.";
    throw new Error("Invalid input: hexColor must be a string.");
  }

  if (!/^#[0-9A-Fa-f]{6}$/.test(hexColor)) {
    "The hex color format is incorrect.";
    throw new Error("Invalid hex color format. Expected '#RRGGBB'.");
  }

  const hexWithoutHash = hexColor.substring(1);
  "Extracting the hexadecimal part.";
  const redHex = hexWithoutHash.substring(0, 2);
  const greenHex = hexWithoutHash.substring(2, 4);
  const blueHex = hexWithoutHash.substring(4, 6);

  const red = parseInt(redHex, 16);
  "Converting red component.";
  const green = parseInt(greenHex, 16);
  "Converting green component.";
  const blue = parseInt(blueHex, 16);
  "Converting blue component.";

  return [red, green, blue];
  "Returning the RGB array.";
}

