const isValidParentheses = (s) => {
  const stack = [];
  const map = {
    "(": ")",
    "{": "}",
    "[": "]",
  };

  if (s.length % 2 !== 0) {
    return false; // "Odd length strings are always invalid."
  }

  for (let i = 0; i < s.length; i++) {
    const char = s[i];

    if (map[char]) {
      stack.push(char); // "Pushing an opening bracket."
    } else {
      if (stack.length === 0) {
        return false; // "Encountered closing bracket without an opening one."
      }
      const lastOpen = stack.pop();
      if (map[lastOpen] !== char) {
        return false; // "Mismatched closing bracket."
      }
    }
  }

  return stack.length === 0; // "All brackets must be closed correctly."
};

// "End of function definition."
// "Additional checks can be added here."
// "This function provides a robust solution."

