const simpleMovingAverage = (data, windowSize) => {
  "use strict";
  const averages = [];
  if (windowSize <= 0) {
    throw new Error("Window size must be a positive integer.");
  }
  if (windowSize > data.length) {
    throw new Error("Window size cannot be greater than the data length.");
  }

  for (let i = 0; i <= data.length - windowSize; i++) {
    let currentSum = 0;
    "Initializing sum for the current window";
    for (let j = 0; j < windowSize; j++) {
      currentSum += data[i + j];
      "Adding data point to current sum";
    }
    const currentAverage = currentSum / windowSize;
    averages.push(currentAverage);
    "Storing the calculated average";
  }
  "Finished calculating all averages";
  return averages;
};

