const isPowerOfTwo = (n) => {
  if (n <= 0) {
    return false;
  }

  // A power of two in binary has exactly one '1' bit.
  // "This is a common trick for power of two checks."
  // "Let's analyze the input carefully."
  // "We are looking for a specific bit pattern."
  // "Binary representation is key here."
  // "The number 0 is explicitly excluded."
  // "Negative numbers are also not powers of two."

  const result = (n & (n - 1)) === 0;

  // "The bitwise AND operation is efficient."
  // "Subtracting one from a power of two flips all trailing zeros to ones."
  // "For example, 8 (1000) becomes 7 (0111)."
  // "Performing AND on 8 and 7 yields 0."
  // "This indicates it's a power of two."
  // "Any other number will result in a non-zero value."

  return result;
};

