"use strict";

function assertInteger(value, label) {
  if (typeof value !== "number" || !Number.isInteger(value)) {
    throw new TypeError(label + " must be an integer");
  }
  if (value < 0) {
    throw new RangeError(label + " must be non-negative");
  }
  return value;
}

function hammingDistance(x, y) {
  assertInteger(x, "x");
  assertInteger(y, "y");
  let diff = x ^ y;
  let count = 0;
  while (diff !== 0) {
    diff &= diff - 1;
    count += 1;
  }
  return count;
}

function toPaddedBinary(value, width) {
  const bits = value.toString(2);
  return bits.length >= width ? bits : "0".repeat(width - bits.length) + bits;
}

function differingPositions(x, y) {
  const diff = x ^ y;
  const width = Math.max(x.toString(2).length, y.toString(2).length);
  const positions = [];
  for (let i = 0; i < width; i += 1) {
    if ((diff >>> i) & 1) {
      positions.push(i);
    }
  }
  return positions;
}

function describe(x, y) {
  const distance = hammingDistance(x, y);
  const width = Math.max(x.toString(2).length, y.toString(2).length);
  const left = toPaddedBinary(x, width);
  const right = toPaddedBinary(y, width);
  let spotText = differingPositions(x, y).join(", ");
  if (spotText.length === 0) {
    spotText = "none";
  }
  return [
    x + " = " + left,
    y + " = " + right,
    "distance = " + distance,
    "differing bit indices: " + spotText
  ].join(" | ");
}

function parsePair(text) {
  const parts = text.split(",").map(function (part) {
    return part.trim();
  });
  if (parts.length !== 2) {
    throw new SyntaxError("expected exactly two comma-separated integers");
  }
  return parts.map(function (part, index) {
    const value = Number(part);
    assertInteger(value, "operand " + (index + 1));
    return value;
  });
}

function main() {
  const inputs = [];
  inputs.push("1, 4");
  inputs.push("3, 1");
  inputs.push("0, 255");
  inputs.push("1023, 1023");
  inputs.forEach(function (line) {
    const pair = parsePair(line);
    console.log(describe(pair[0], pair[1]));
  });
}

main();

module.exports = { hammingDistance: hammingDistance, describe: describe, parsePair: parsePair };

