function replaceAllOccurrences(text, find, replace) {
  if (find === "") {
    return text;
  }
  let result = "";
  let lastIndex = 0;
  let findIndex;
  while ((findIndex = text.indexOf(find, lastIndex)) !== -1) {
    result += text.substring(lastIndex, findIndex);
    result += replace;
    lastIndex = findIndex + find.length;
  }
  result += text.substring(lastIndex);
