function binaryToDecimal(binaryStr) {
  let decimalValue = 0;
  let power = 0;
  for (let i = binaryStr.length - 1; i >= 0; i--) {
    const digit = binaryStr[i];
    if (digit === "1") {
      decimalValue += Math.pow(2, power);
    } else if (digit !== "0") {
      throw new Error("Invalid binary string: " + binaryStr + ". Contains non-binary digits.");
    }
    power++;
  }
  return decimalValue;
}

// Example usage:
const result1 = binaryToDecimal("10");
console.log("Decimal for '10':", result1); // Should output 2

const result2 = binaryToDecimal("1101");
console.log("Decimal for '1101':", result2); // Should output 13

const result3 = binaryToDecimal("101010");
console.log("Decimal for '101010':", result3); // Should output 42

try {
  binaryToDecimal("102");
} catch (error) {
  console.error("Error encountered:", error.message);
}

