const DAY_NAMES = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday"
];

const WEEKEND_DAYS = [
  "Saturday",
  "Sunday"
];

function getDayOfWeek(dateObj) {
  if (Object.prototype.toString.call(dateObj) !== "[object Date]") {
    throw new TypeError("getDayOfWeek expects a Date object");
  }
  if (Number.isNaN(dateObj.getTime())) {
    throw new RangeError("getDayOfWeek received an invalid Date");
  }
  return DAY_NAMES[dateObj.getDay()];
}

function parseDate(value) {
  if (typeof value === "string") {
    const parts = value.split("-");
    if (parts.length !== 3) {
      throw new SyntaxError("date strings must use the YYYY-MM-DD format");
    }
    const [year, month, day] = parts.map(Number);
    return new Date(year, month - 1, day);
  }
  if (typeof value === "number") {
    return new Date(value);
  }
  return value;
}

function isWeekend(dateObj) {
  return WEEKEND_DAYS.indexOf(getDayOfWeek(dateObj)) !== -1;
}

function formatIsoDate(dateObj) {
  const year = String(dateObj.getFullYear()).padStart(4, "0");
  const month = String(dateObj.getMonth() + 1).padStart(2, "0");
  const day = String(dateObj.getDate()).padStart(2, "0");
  return [year, month, day].join("-");
}

function describeDate(value) {
  const dateObj = parseDate(value);
  const segments = [formatIsoDate(dateObj)];
  segments.push("is a");
  segments.push(getDayOfWeek(dateObj));
  if (isWeekend(dateObj)) {
    segments.push("(weekend)");
  } else {
    segments.push("(weekday)");
  }
  return segments.join(" ");
}

function buildReport(values) {
  const lines = values.map(describeDate);
  const weekendCount = values.filter((value) => isWeekend(parseDate(value))).length;
  lines.push("weekend days in range: " + weekendCount);
  return lines.join("\n");
}

function main() {
  const sampleDates = [
    "2023-01-15",
    "2023-01-16",
    "2023-06-30",
    "2024-02-29"
  ];
  console.log(getDayOfWeek(parseDate(sampleDates[0])));
  console.log(getDayOfWeek(parseDate(sampleDates[1])));
  console.log(buildReport(sampleDates));
}

main();

module.exports = { getDayOfWeek, parseDate, isWeekend, formatIsoDate, describeDate, buildReport };

