const SAMPLE_SEPARATOR = ";";
const SAMPLE_INPUT =
  "A man, a plan, a canal: Panama;race a car; ;Was it a car or a cat I saw?;12/21";

function isAlphanumeric(ch) {
  return ALPHANUMERIC.indexOf(ch) !== -1;
}

function normalize(str) {
  if (typeof str !== "string") {
    throw new TypeError("normalize expects a string");
  }
  let cleaned = "";
  for (const ch of str.toLowerCase()) {
    if (isAlphanumeric(ch)) {
      cleaned += ch;
    }
  }
  return cleaned;
}

function isPalindromeCI(str) {
  const cleaned = normalize(str);
  let left = 0;
  let right = cleaned.length - 1;
  while (left < right) {
    if (cleaned[left] !== cleaned[right]) {
      return false;
    }
    left += 1;
    right -= 1;
  }
  return true;
}

function firstMismatch(str) {
  const cleaned = normalize(str);
  let left = 0;
  let right = cleaned.length - 1;
  while (left < right) {
    if (cleaned[left] !== cleaned[right]) {
      return cleaned[left] + cleaned[right];
    }
    left += 1;
    right -= 1;
  }
