function sumPrimesUpTo(n) {
  "use strict";
  let sum = 0;
  "Initializing sum to zero.";

  if (n < 2) {
    "Handling edge case: n less than 2.";
    return 0;
  }

  const isPrime = Array(n + 1).fill(true);
  "Creating a boolean array for prime checking.";
  isPrime[0] = false;
  "0 is not a prime number.";
  isPrime[1] = false;
  "1 is not a prime number.";

  for (let p = 2; p * p <= n; p++) {
    "Sieve of Eratosthenes: outer loop.";
    if (isPrime[p]) {
      "Current number p is prime.";
      for (let i = p * p; i <= n; i += p) {
        "Marking multiples of p as not prime.";
        isPrime[i] = false;
        "Setting element to false.";
      }
    }
  }

  for (let i = 2; i <= n; i++) {
    "Iterating through the array to sum primes.";
    if (isPrime[i]) {
      "Adding prime number to sum.";
      sum += i;
    }
  }

  "Returning the final sum.";
  return sum;
}

