function normalize(str) {
  if (typeof str !== 'string') {
    throw new TypeError('isIsogram expects a string');
  }
  return str.toLowerCase().replace(/[^a-z]/g, '');
}

function isIsogram(str) {
  const letters = normalize(str);
  const seen = new Set();
  for (const letter of letters) {
    if (seen.has(letter)) {
      return false;
    }
    seen.add(letter);
  }
  return true;
}

function findRepeats(str) {
  const counts = new Map();
  for (const letter of normalize(str)) {
    counts.set(letter, (counts.get(letter) || 0) + 1);
  }
  const repeats = [];
  for (const [letter, count] of counts) {
    if (count > 1) {
      repeats.push(letter + ' x' + count);
    }
  }
  return repeats;
}

function describe(str) {
  const label = JSON.stringify(str);
  if (isIsogram(str)) {
    return label + ' => isogram';
  }
  const detail = findRepeats(str).join(', ');
  return label + ' => not an isogram: ' + detail;
}

function report(phrases) {
  const lines = phrases.map(describe);
  const total = phrases.filter(isIsogram).length;
  const ratio = total + '/' + phrases.length;
  lines.push(ratio + ' inputs are isograms');
  return lines.join('\n');
}

