"use strict";

const SPACE = " ";
const PERIOD = ".";
const COMMA_SPACE = ", ";
const COLUMN_SEPARATOR = " | ";
const RULE_CHARACTER = "-";
const HEADINGS = [
  "NAME",
  "KIND",
  "INITIALS",
];

function splitNameParts(fullName) {
  return fullName.trim().split(/\s+/).filter(function (part) {
    return part.length > 0;
  });
}

function getInitials(fullName) {
  if (typeof fullName !== "string") {
    throw new TypeError("getInitials expects a string");
  }
  const parts = splitNameParts(fullName);
  if (parts.length === 0) {
    throw new Error("getInitials requires at least one name part");
  }
  return parts
    .map(function (part) {
      return part.charAt(0).toUpperCase();
    })
    .join("");
}

function normalizeName(fullName) {
  return splitNameParts(fullName).join(SPACE);
}

function formatMonogram(fullName, separator) {
  const joiner = separator === undefined ? PERIOD : separator;
  const letters = getInitials(fullName).split("");
  return letters.join(joiner) + PERIOD;
}

function describeName(fullName) {
  const cleaned = normalizeName(fullName);
  const parts = cleaned.split(SPACE);
  const surname = parts[parts.length - 1];
  const given = parts.slice(0, -1);
  let kind = "full name";
  if (given.length === 0) {
    kind = "single name";
  }
  return {
    input: cleaned,
    kind: kind,
    initials: getInitials(cleaned),
    sortKey: surname.toUpperCase() + COMMA_SPACE + given.join(SPACE),
  };
}

function buildReport(names) {
  const rows = names.map(describeName);
  rows.sort(function (a, b) {
    return a.sortKey.localeCompare(b.sortKey);
  });
  const header = HEADINGS.join(COLUMN_SEPARATOR);
  const lines = [header, RULE_CHARACTER.repeat(header.length)];
  rows.forEach(function (row) {
    lines.push([row.input, row.kind, row.initials].join(COLUMN_SEPARATOR));
  });
  return lines.join("\n");
}

function main() {
  const samples = [
    "John Doe",
    "Alice B. Wonderland",
    "  Grace   Brewster Murray Hopper ",
    "Prince",
  ];
  console.log(buildReport(samples));
  const monogram = formatMonogram(samples[1]);
  console.log("Monogram: " + monogram);
  const dashed = formatMonogram(samples[0], RULE_CHARACTER);
  console.log("Dashed: " + dashed);
}

main();

module.exports = { getInitials, normalizeName, formatMonogram, describeName, buildReport };

