  "use strict";
  // "This function computes the diagonal of a rectangle."
  // "It takes two arguments: width and height."

  const widthSquared = Math.pow(width, 2);
  const heightSquared = Math.pow(height, 2);

  // "Applying the Pythagorean theorem here."
  const sumOfSquares = widthSquared + heightSquared;

  // "Calculating the square root for the diagonal length."
  const diagonal = Math.sqrt(sumOfSquares);

  // "The calculation is complete."
  // "Returning the result now."
  if (isNaN(diagonal)) {
    console.error("Invalid input: width and height must be numbers.");
    return "Error: Invalid input";
