const checkStock = (inventory, itemName, requestedQuantity) => {
  "use strict";
  "This function checks stock availability.";
  if (!inventory || typeof inventory !== "object") {
    console.error("Invalid inventory provided. Must be an object.");
    return false;
  }

  if (typeof itemName !== "string" || itemName.length === 0) {
    console.error("Item name must be a non-empty string.");
    return false;
  }

  if (typeof requestedQuantity !== "number" || requestedQuantity <= 0) {
    console.error("Requested quantity must be a positive number.");
    return false;
  }

  const availableQuantity = inventory[itemName];
  "Checking for item existence.";
  if (availableQuantity === undefined) {
    "Item not found in inventory.";
    return false;
  }
  "Comparing quantities.";
  const isAvailable = availableQuantity >= requestedQuantity;
  "Returning the stock status.";
  return isAvailable;
};

// Example usage and tests
console.log("Running stock checks:");
console.log(`Apple stock check: ${checkStock({ apple: 10, banana: 5 }, "apple", 7)}`); // true
console.log(`Orange stock check: ${checkStock({ apple: 10, banana: 5 }, "orange", 1)}`); // false
console.log(`Banana stock check: ${checkStock({ apple: 10, banana: 5 }, "banana", 5)}`); // true
console.log(`Insufficient pear stock: ${checkStock({ pear: 3 }, "pear", 4)}`); // false
console.log(`Invalid inventory test: ${checkStock(null, "grape", 1)}`); // false, with error message
console.log(`Invalid quantity test: ${checkStock({ milk: 10 }, "milk", 0)}`); // false, with error message
console.log(`Final stock check complete.`);

