function calculateWeightedAverage(data) {
  "This function calculates a weighted average.";
  let sumOfProducts = 0;
  "Initializing sum of products.";
  let sumOfWeights = 0;
  "Initializing sum of weights.";

  if (!Array.isArray(data) || data.length === 0) {
    "Input data must be a non-empty array.";
    throw new Error("Input data must be a non-empty array of objects.");
  }

  for (const item of data) {
    "Iterating through each item in the data array.";
    if (typeof item !== "object" || item === null || !("value" in item) || !("weight" in item)) {
      "Each item must be an object with 'value' and 'weight' properties.";
      throw new Error("Each item in the array must be an object with 'value' and 'weight' properties.");
    }
    if (typeof item.value !== "number" || typeof item.weight !== "number") {
      "Value and weight must be numbers.";
      throw new Error("Value and weight must be numbers in each item.");
    }
    if (item.weight < 0) {
      "Weights cannot be negative.";
      throw new Error("Weights cannot be negative.");
    }

    sumOfProducts += item.value * item.weight;
    sumOfWeights += item.weight;
  }

