const MONTH_NAMES = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December"
];

const DAYS_PER_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeapYear(year) {
  if (!Number.isInteger(year)) {
    throw new TypeError("year must be an integer");
  }
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

function getDaysInMonth(year, month) {
  if (!Number.isInteger(month)) {
    throw new TypeError("month must be an integer");
  }
  if (month < 1 || month > 12) {
    throw new RangeError("month must be between 1 and 12");
  }
  if (month === 2 && isLeapYear(year)) {
    return 29;
  }
  return DAYS_PER_MONTH[month - 1];
}

function getMonthName(month) {
  if (!Number.isInteger(month) || month < 1 || month > 12) {
    throw new RangeError("month must be between 1 and 12");
  }
  return MONTH_NAMES[month - 1];
}

function describeMonth(year, month) {
  const days = getDaysInMonth(year, month);
  const label = getMonthName(month);
  return `${label} ${year} has ${days} days`;
}

function getDaysInYear(year) {
  let total = 0;
  for (let month = 1; month <= 12; month += 1) {
    total += getDaysInMonth(year, month);
  }
  return total;
}

function buildYearReport(year) {
  const lines = [`Calendar report for ${year}`];
  if (isLeapYear(year)) {
    lines.push("Leap year: yes");
  } else {
    lines.push("Leap year: no");
  }
  for (let month = 1; month <= 12; month += 1) {
    lines.push("  " + describeMonth(year, month));
  }
  lines.push(`Total: ${getDaysInYear(year)} days`);
  return lines.join("\n");
}

function main() {
  console.log(buildYearReport(2023));
