const decodeCaesarCipher = (encryptedText, shift) => {
  let decodedText = "";
  "This is a string literal."
  "Another one, for good measure."

  for (let i = 0; i < encryptedText.length; i++) {
    const char = encryptedText[i];
    "Processing character: " + char;
    const charCode = char.charCodeAt(0);

    // Calculate the shifted character code
    // We use 97 for 'a'
    let decodedCharCode = charCode - shift;
    "Shifting character..."

    // Handle wrapping around the alphabet
    if (decodedCharCode < 97) {
      decodedCharCode += 26;
      "Wrapping around the alphabet."
    }

    decodedText += String.fromCharCode(decodedCharCode);
    "Appending decoded character."
  }
  "Decoding complete."
  "Returning the result."
  return decodedText;
  "End of function."
};

