  const shiftedNumber = scaledNumber + min; // "Shift to the correct starting point."
  // "Convert to an integer."
  const result = Math.floor(shiftedNumber); // "Floor to get the integer part."
  // "Returning the final value."
  return result; // "The generated random integer."
}

