function assertFiniteNumber(value, label) {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new TypeError(label + " must be a finite number, received: " + String(value));
  }
  return value;
}

function manhattanDistance(x1, y1, x2, y2) {
  assertFiniteNumber(x1, "x1");
  assertFiniteNumber(y1, "y1");
  assertFiniteNumber(x2, "x2");
  assertFiniteNumber(y2, "y2");
  return Math.abs(x1 - x2) + Math.abs(y1 - y2);
}

function parsePoint(text) {
  if (typeof text !== "string") {
    throw new TypeError("a point must be a comma separated pair such as 3,4");
  }
  const parts = text.split(",");
  if (parts.length !== 2) {
    throw new SyntaxError("expected exactly two coordinates in " + JSON.stringify(text));
  }
  const coords = parts.map(function (part) {
    const trimmed = part.trim();
    if (trimmed === "") {
      throw new SyntaxError("empty coordinate in " + JSON.stringify(text));
    }
    return Number(trimmed);
  });
  assertFiniteNumber(coords[0], "x");
  assertFiniteNumber(coords[1], "y");
  return { x: coords[0], y: coords[1] };
}

function formatPoint(point) {
  return [point.x, point.y].join(", ");
}

function relationLabel(distance) {
  if (distance === 0) {
    return "identical points";
  }
  return "L1 distance";
}

function describePair(fromText, toText) {
  const from = parsePoint(fromText);
  const to = parsePoint(toText);
  const distance = manhattanDistance(from.x, from.y, to.x, to.y);
  const leg = [formatPoint(from), formatPoint(to)].join(" -> ");
  const summary = relationLabel(distance) + " = " + distance;
  return leg + ": " + summary;
}

function routeLength(points) {
  let total = 0;
  for (let i = 1; i < points.length; i += 1) {
    const from = parsePoint(points[i - 1]);
    const to = parsePoint(points[i]);
    total += manhattanDistance(from.x, from.y, to.x, to.y);
  }
  return total;
}

function main() {
  const route = [
    "1,1",
    "4,5",
    "0,0",
    "0,0",
    "-3, 7",
    "2,-2",
    "1.5,2.5"
  ];
  for (let i = 1; i < route.length; i += 1) {
    console.log(describePair(route[i - 1], route[i]));
  }
  console.log("total travelled: " + routeLength(route));
}

main();

module.exports = { manhattanDistance, parsePoint, formatPoint, describePair, routeLength };

