function isValidPassword(password) {
  const minLength = 8;
  const hasUppercase = /[A-Z]/;
  const hasNumber = /[0-9]/;

  if (typeof password !== "string") {
    console.error("Input must be a string.");
    return false;
  }

  if (password.length < minLength) {
    return false;
  }

  if (!hasUppercase.test(password)) {
