const filterByProps = (data, filter) => {
  const filterKeys = Object.keys(filter);
  if (filterKeys.length === 0) {
    return data;
  }

  return data.filter(item => {
    let allMatch = true;
    for (const key of filterKeys) {
      if (item[key] !== filter[key]) {
        allMatch = false;
        break;
      }
    }
    return allMatch;
  });
