function isPalindrome(str) {
  if (typeof str !== "string") {
    throw new TypeError("isPalindrome expects a string");
  }
  for (let left = 0, right = str.length - 1; left < right; left += 1, right -= 1) {
    if (str[left] !== str[right]) {
      return false;
    }
  }
  return true;
}

function reverse(str) {
  let out = "";
  for (let i = str.length - 1; i >= 0; i -= 1) {
    out += str[i];
  }
  return out;
}

function normalize(str) {
  return str.toLowerCase().replace(/[^a-z0-9]/g, "");
}

function classify(str) {
  if (str.length === 0) {
    return "empty";
  }
  if (isPalindrome(str)) {
    return "palindrome";
  }
  if (isPalindrome(normalize(str))) {
    return "loose palindrome";
  }
  return "not a palindrome";
}

function longestPalindromicPrefix(str) {
  for (let end = str.length; end > 0; end -= 1) {
    const prefix = str.slice(0, end);
    if (isPalindrome(prefix)) {
      return prefix;
    }
  }
  return "";
}

function describe(str) {
  const kind = classify(str);
  const parts = [JSON.stringify(str), kind];
  if (kind === "not a palindrome") {
    parts.push("reversed: " + JSON.stringify(reverse(str)));
    parts.push("longest palindromic prefix: " + JSON.stringify(longestPalindromicPrefix(str)));
  }
  return parts.join(" | ");
}

function main() {
  const samples = [
    "madam",
    "hello",
    "Madam",
    "A man, a plan, a canal: Panama",
    "racecar",
    "",
    "step on no pets"
  ];
  const lines = samples.map(describe);
  console.log(lines.join("\n"));
  const strictCount = samples.filter(isPalindrome).length;
  const ratio = strictCount + "/" + samples.length;
  console.log("strict palindromes: " + ratio);
}

main();

module.exports = { isPalindrome, reverse, normalize, classify, longestPalindromicPrefix, describe };

