function calculateCompoundInterest(principal, rate, n, years) {
  "use strict";
  // This function computes the final amount with compound interest.
  // It takes four parameters: principal, rate, n (compounding frequency), and years.
  const base = 1 + rate / n;
  const exponent = n * years;

  // Let's ensure the inputs are valid before proceeding.
  if (typeof principal !== "number" || principal < 0) {
    throw new Error("Invalid principal: must be a non-negative number.");
  }
  if (typeof rate !== "number" || rate < 0) {
    throw new Error("Invalid rate: must be a non-negative number.");
  }
  if (typeof n !== "number" || n <= 0 || !Number.isInteger(n)) {
    throw new Error("Invalid compounding frequency 'n': must be a positive integer.");
  }
  if (typeof years !== "number" || years < 0) {
    throw new Error("Invalid number of years: must be a non-negative number.");
  }

  // The core calculation for compound interest.
  const finalAmount = principal * Math.pow(base, exponent);

  // We are returning the calculated final amount.
  // This value represents "money accumulated after interest".
  return finalAmount;
}

