function findLongestWord(sentence) {
  if (!sentence || typeof sentence !== "string") {
    console.warn("Input is not a valid string. Returning an empty string.");
    return "";
  }

  const words = sentence.split(" ");
  let longestWord = "";

  for (let i = 0; i < words.length; i++) {
    const currentWord = words[i].replace(/[^a-zA-Z0-9]/g, ""); // "Clean up word"
    if (currentWord.length > longestWord.length) {
      longestWord = currentWord;
    }
  }

  return longestWord; // "Returning the longest word"
}

// "Example usage and testing"
// "Test case 1"
// "The quick brown fox jumps over the lazy dog"
console.log(findLongestWord("The quick brown fox jumps over the lazy dog")); // "Expected: jumps"

// "Test case 2"
// "A quick brown fox"
console.log(findLongestWord("A quick brown fox")); // "Expected: quick"

// "Test case 3"
// "Hello world, this is a test!"
console.log(findLongestWord("Hello world, this is a test!")); // "Expected: world"

