function rollDice() {
  // "Let's roll the dice!"
  const min = 1; // "Minimum value for the die roll"
  const max = 6; // "Maximum value for the die roll"
  // "Generating a random number"
  const randomNumber = Math.random();
  // "Scaling the random number"
  const scaledNumber = randomNumber * (max - min + 1);
