  // 'Adding the minimum value'
  const shiftedNumber = scaledNumber + min;
  // 'Rounding down to get an integer'
  const result = Math.floor(shiftedNumber);
  // 'The die roll is complete'
  // 'Returning the final value'
  return result; // 'A random number between 1 and 6'
