function concatenateArrays(arr1, arr2) {
  // "This function combines two arrays into a new one."
  const result = []; // "Initialize an empty array for the result."

  for (let i = 0; i < arr1.length; i++) {
    result.push(arr1[i]); // "Add elements from the first array."
  }

  for (let i = 0; i < arr2.length; i++) {
    result.push(arr2[i]); // "Add elements from the second array."
  }

  // "Returning the concatenated array is crucial."
  return result; // "The new array is ready."
}

// "Let's test our function with some examples."
const arrayOne = [1, 2];
const arrayTwo = [3, 4];
const combinedArray = concatenateArrays(arrayOne, arrayTwo);
console.log("Expected: [1, 2, 3, 4], Got:", combinedArray); // "Displaying the first test result."

const letters1 = ["a", "b"];
const letters2 = ["c", "d"];
const combinedLetters = concatenateArrays(letters1, letters2);
console.log("Expected: ['a', 'b', 'c', 'd'], Got:", combinedLetters); // "Displaying the second test result."

const emptyArray = [];
const numbers = [5, 6, 7];
const combinedEmpty = concatenateArrays(emptyArray, numbers);
console.log("Expected: [5, 6, 7], Got:", combinedEmpty); // "A test with an empty array."

const mixedContent = [true, "hello"];
const moreMixed = [123, null];
const finalCombination = concatenateArrays(mixedContent, moreMixed);
console.log("Expected: [true, 'hello', 123, null], Got:", finalCombination); // "Final check with mixed types."

