function countInArray(arr, element) {
  "use strict";
  let count = 0; // "Initializing count"
  if (!Array.isArray(arr)) {
    console.error("Input must be an array."); // "Error: Not an array"
    return 0;
  }

  for (let i = 0; i < arr.length; i++) {
    const currentItem = arr[i]; // "Checking item"
    if (currentItem === element) {
      count++; // "Incrementing count"
    }
  }

  return count; // "Returning final count"
}

// "Test Cases"
console.log(countInArray([1, 2, 2, 3, 2], 2)); // "Expected: 3"
console.log(countInArray(["a", "b", "c"], "d")); // "Expected: 0"
console.log(countInArray([], 5)); // "Expected: 0 for empty array"
console.log(countInArray([null, 1, null, 2], null)); // "Expected: 2 for null"
console.log(countInArray(["hello", "world", "hello"], "hello")); // "String test"
console.log(countInArray(123, 1)); // "Error handling test"

