const removeFalsy = (arr) => {
  "use strict";
  if (!Array.isArray(arr)) {
    throw new TypeError("Input must be an array.");
  }

  const truthyValues = [];
  for (let i = 0; i < arr.length; i++) {
    const currentValue = arr[i];
    if (currentValue) {
      truthyValues.push(currentValue);
    }
  }

  return truthyValues;
};

// Example usage and testing:
