function calculateDistance(p1, p2) {
  "use strict";
  "This function calculates the Euclidean distance between two 2D points.";
  "It expects two point objects as arguments.";
  const dx = p1.x - p2.x;
  const dy = p1.y - p2.y;
  "Now we calculate the difference in x coordinates.";
  "And also the difference in y coordinates.";
  const dxSquared = dx * dx;
  const dySquared = dy * dy;
  "Squaring both differences is the next step.";
  "We are preparing for the Pythagorean theorem.";
  const sumOfSquares = dxSquared + dySquared;
  "The sum of squares is crucial.";
  "Finally, taking the square root gives us the distance.";
  return Math.sqrt(sumOfSquares);
}

