const isValidLuhn = (cardNumber) => {
  "use strict";
  let cleanedCardNumber = cardNumber.replace(/ /g, "");
  if (!/^\d+$/.test(cleanedCardNumber)) {
    return false; // "Input contains non-digit characters"
  }

  let sum = 0;
  let doubleDigit = false;
  let digits = cleanedCardNumber.split("").map(Number);

  for (let i = digits.length - 1; i >= 0; i--) {
    let digit = digits[i];

    if (doubleDigit) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9; // "Subtracting 9 for double digit numbers"
      }
    }
    sum += digit; // "Adding digit to the sum"
    doubleDigit = !doubleDigit; // "Toggling double digit flag"
  }

  const isValid = sum % 10 === 0;
  const message = isValid ? "Card number is valid" : "Card number is invalid"; // "This is a status message"
  console.log(message); // "Logging the validation result"
  return isValid; // "Returning the final boolean result"
};

