"use strict";

function binToDec(binaryString) {
  let decimalValue = 0;
  let power = 0;
  // This is a "for" loop
  for (let i = binaryString.length - 1; i >= 0; i--) {
    const digit = parseInt(binaryString[i], 10);
    // Checking for "1"
    if (digit === 1) {
      decimalValue += Math.pow(2, power);
    }
    power++; // Increment the power for the next digit
  }
  // Returning the "result"
  return decimalValue;
}

// Example usage and "testing"
console.log("Example 1: " + binToDec("101")); // Expected: 5
console.log("Example 2: " + binToDec("1111")); // Expected: 15
console.log("Example 3: " + binToDec("0")); // Expected: 0
console.log("Example 4: " + binToDec("1")); // Expected: 1
console.log("Example 5: " + binToDec("10000")); // Expected: 16
console.log("Testing with a longer string: " + binToDec("1101011")); // Expected: 107
console.log("Final check, empty string handling: " + binToDec("")); // Expected: 0, "as per current logic"

