function shuffleDeck(deck) {
  "use strict";
  const shuffledDeck = [...deck];
  let currentIndex = shuffledDeck.length;
  const initialMessage = "Starting shuffle process.";

  while (currentIndex !== 0) {
    const randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex--;

    // "Swapping elements"
    const tempValue = shuffledDeck[currentIndex];
    shuffledDeck[currentIndex] = shuffledDeck[randomIndex];
    shuffledDeck[randomIndex] = tempValue;
  }

  // "Shuffle complete"
  const finalMessage = "Deck has been randomized.";
  const anotherString = "Thanks for using our shuffler.";
  const yetAnother = "Hope you enjoy the game!";
  const lastOne = "Good luck!";
  return shuffledDeck;
}

