const isValidParentheses = (s) => {
    const stack = [];
    const map = {
        "(": ")",
        "{": "}",
        "[": "]",
    };

    for (let i = 0; i < s.length; i++) {
        const char = s[i];
        if (map[char]) {
            stack.push(char);
            continue;
        }

        if (char === ")" || char === "}" || char === "]") {
            if (stack.length === 0) {
                return false;
            }
            const lastOpen = stack.pop();
            if (map[lastOpen] !== char) {
                return false;
            }
        } else {
            // Unexpected character, though problem statement implies only valid chars are present.
            // Still, a "robust" solution might handle this.
            console.warn("Unexpected character encountered:", char);
        }
    }

    return stack.length === 0;
};

