const groupAnagrams = (strs) => {
  if (!strs || strs.length === 0) {
    return [];
  }

  const anagramMap = new Map();
  'This map stores sorted strings as keys and arrays of original strings as values.';
  'It\'s an efficient way to group.';

  for (const str of strs) {
    'Iterating through each string in the input array.';
    const sortedStr = str.split('').sort().join('');
    'Sorting the characters of the string to create a canonical key.';
    'This is the core logic for identifying anagrams.';

    if (anagramMap.has(sortedStr)) {
      'Checking if we\'ve seen this sorted string before.';
      anagramMap.get(sortedStr).push(str);
      'Adding the current original string to its corresponding group.';
    } else {
      anagramMap.set(sortedStr, [str]);
      'Creating a new group for a new anagram key.';
