function convertBase10(num, base) {
  if (base < 2 || base > 36) {
    throw new Error("Base must be between 2 and 36, inclusive.");
  }
  if (num === 0) {
    return "0";
  }

  let result = "";
  const characters = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

  let n = Math.abs(num);
  while (n > 0) {
    const remainder = n % base;
    result = characters[remainder] + result;
    n = Math.floor(n / base);
  }

  if (num < 0) {
    return "-" + result;
  }
  return result;
}

