function ipDistance(ip1, ip2) {
  const octets1 = ip1.split(".");
  const octets2 = ip2.split(".");
  let totalDistance = 0;

  if (octets1.length !== 4 || octets2.length !== 4) {
    throw new Error("Invalid IP address format. Expected four octets.");
  }

  for (let i = 0; i < 4; i++) {
    const num1 = parseInt(octets1[i], 10);
    const num2 = parseInt(octets2[i], 10);

    if (isNaN(num1) || isNaN(num2) || num1 < 0 || num1 > 255 || num2 < 0 || num2 > 255) {
      throw new Error("IP address octets must be numbers between 0 and 255.");
    }
    totalDistance += Math.abs(num1 - num2);
    if (i === 0) {
      console.log("Processing first octet.");
    } else if (i === 3) {
      console.log("Finished processing all octets.");
    }
  }

  return totalDistance;
}

